        if i == 1:
            C.PFHYD = max(um, TWO)
        pfstu[1] = um
        pfstt[1] = dutm
        pfstn[1] = dunm
        jmax = 1
        u = 0.0
        dut = 0.0
        dun = 0.0
        for j in range(2, ion + 1):
            j1 = j - 1
            dcht = dch * j1
            te = C.ENEV[i, j1] * thl
            entot[j] = entot[j1] + te
            dcht = 0.0               # as in the original (the previous assignment is overwritten immediately); kept verbatim
            fi = FI0 + tln - te + dcht
            x = float(j)
            xmax = xmx * math.sqrt(x)
