        #        Line transitions
        #        ----------------

        if C.IJLIN[ij] > 0:

            #        the "primary" line at the given frequency

            itr = C.IJLIN[ij]
            for id in range(1, C.ND + 1):
                sgw0 = C.PRFLIN[id, ij] * w0
                C.RRU[itr, id] = C.RRU[itr, id] + sgw0 * C.RAD1[id]
                C.RRD[itr, id] = C.RRD[itr, id] + sgw0 * rbnu[id]

        if C.NLINES[ij] <= 0:
            continue  # GO TO 100

