def gaunt(i, fr):
    """C     ====================
    C
    C     Hydrogenic bound-free Gaunt factor for the principal quantum
    C     number I and frequency FR

    Corresponds to tlusty208.f lines 9943-9987. FUNCTION, returns the function value.
    DATA tables are read-only -> assigned directly at the top of the function.
    """
    # Local PARAMETER (UN=1.) has the same value as in params.py; use UN directly
    x = np.zeros(8)                  # DIMENSION X(7), 1-based
    # DATA CGT/.../ -- CGT(7,10) filled sequentially in Fortran column-major order
    _cgt_flat = [
        0., 12.803223, -5.5759888, 1.2302628, -2.9094219e-3,
        7.3993579e-6, -8.7356966e-9, -2.0244141, 2.1325684, -1.2709045,
        1.1595421, -2.0735860e-3, 2.7033384e-6, 0., -0.23387146,
        0.52471924, -0.55936432, 1.1450949, -1.9366592e-3, 2.3572356e-6,
        0., -5.4418565e-2, 0.19683564, -0.31190730, 1.1306695,
        -1.3482273e-3, -4.6949424e-6, 2.3548636e-8, -8.9182854e-3,
        5.5545091e-2, -0.16051018, 1.1190904, -1.0401085e-3,
        -6.9943488e-6, 2.8496742e-8, -5.5303574e-3, 4.1921183e-2,
        -0.13075417, 1.1168376, -8.9466573e-4, -8.8393133e-6,
        3.4696768e-8, -2.2752881e-3, 2.3350812e-2, -9.5441161e-2,
        1.1128632, -7.4833260e-4, -1.0244504e-5, 3.8595771e-8,
        -9.7200274e-4, 1.3298411e-2, -7.1010560e-2, 1.1093137,
        -6.2619148e-4, -1.1342068e-5, 4.1477731e-8, -4.9576163e-4,
        8.5139736e-3, -5.6046560e-2, 1.1078717, -5.4837392e-4,
        -1.2157943e-5, 4.3796716e-8, -2.9467046e-4, 6.1516856e-3,
        -4.7326370e-2, 1.1052734, -4.4341570e-4, -1.3235905e-5,
        4.7003140e-8]
    cgt = np.zeros((8, 11))
    # reshape to (7,10) in column-major order, then embed in the 1-based array
    cgt[1:, 1:] = np.array(_cgt_flat).reshape((7, 10), order='F')
    # DATA FRKW/6.6D15,9*3.3D15/ (FRKW is unused in this function; kept as a literal translation)
    frkw = np.zeros(11)
    frkw[1] = 6.6e15
    frkw[2:11] = 3.3e15

    if i <= 10:
        x[5] = fr / 2.99793e14
        x[6] = x[5] * x[5]
        x[7] = x[6] * x[5]
        x[4] = UN
        x[3] = UN / x[5]
        x[2] = x[3] * x[3]
        x[1] = x[2] * x[3]
        gaunt_ = 0.0
        for j in range(1, 8):        # DO 10 J=1,7
            gaunt_ = gaunt_ + cgt[j, i] * x[j]
        # 10 CONTINUE
    else:
        gaunt_ = UN
    return gaunt_


def gntk(i, fr):
    """C     ===================
    C
    C     Hydrogenic bound-free Gaunt factor for the principal quantum
    C     number I and frequency FR (from Klaus Werner)

    Corresponds to tlusty208.f lines 9994-10010. FUNCTION, returns the function value.
    No RETURN before END in the original (END implies a return).
    """
    gntk_ = 1.0
    y = 1.0 / fr
    if i == 1:
        gntk_ = 0.9916 + y * (2.71852e13 - y * 2.26846e30)
    elif i == 2:
        gntk_ = 1.1050 - y * (2.37490e14 - y * 4.07677e28)
    elif i == 3:
        gntk_ = 1.1010 - y * (0.98632e14 - y * 1.03540e28)
    return gntk_


def spsigk(ib, fr, sigsp):
    """C     ==============================
    C
    C     Non-standard evaluation of the photoionization cross-sections
    C     Basically user-suppled procedure; here are some examples

    Corresponds to tlusty208.f lines 10016-10048.
    This subprogram assigns to the scalar dummy arg SIGSP, so by convention return all scalar dummy args
    (ib, fr, sigsp).
    """
    sigsp = 0.0

    # Special formula for the He I ground state
    if ib == -201:
        sigsp = 7.3e-18 * math.exp(1.373 - 2.311e-16 * fr)

    # Special formula for the averaged <n=2> level of He I
    if ib == -202:
        sigsp = sghe12(fr)

    # Carbon ground configuration levels 2p2 1D and 1S
    if ib == -602 or ib == -603:
        # CARBON assigns to scalar dummy arg SG -> unpack and receive all scalar dummy args
        sg = 0.0                         # placeholder actual argument
        ib, fr, sg = carbon(ib, fr, sg)
        sigsp = sg

    # Hidalgo (Ap.J. 153, 981, 1968) photoionization data
    if ib <= -101 and ib >= -137:
        sigsp = hidalg(ib, fr)

    # Reilman and Manson (Ap.J. Suppl. 40, 815, 1979) photoionization data
    if ib <= -301 and ib >= -337:
        sigsp = reiman(ib, fr)
    return ib, fr, sigsp


def hidalg(ib, fr):
    """C     ======================
    C
    C     Read table of wavelengths and photo-ionization cross-sections
    C     from Hidalgo (1968, Ap. J., 153, 981) for the species indicated by IB
    C     (Hidalgo's number = INDEX = -IB-100).
    C     Compute linearly interpolated value of the cross-section
    C     at the frequency FR.
    C
    C     (At the moment, only a few transitions are considered)

    Corresponds to tlusty208.f lines 10055-10133. FUNCTION, returns the function value.
    SAVE WL1,WL2,SIG0: read-only after DATA initialization -> assigned directly at the top of the function.
    """
    wl1 = np.zeros(21)                 # DIMENSION WL1(20)
    # DATA WL1 /.../
    wl1[1:] = [39.1, 80.9, 97.6, 100.1, 104.3, 107.2, 108.7, 111.9,
               113.6, 115.4, 117.1, 119.0, 124.8, 126.9, 129.1, 131.3,
               133.6, 136.0, 138.5, 141.1]
    wl2 = np.zeros(21)                 # DIMENSION WL2(20)
    # DATA WL2 /... 15 values, 5*0./
    wl2[1:16] = [68.5, 80.9, 100.1, 120.9, 158.8, 165.7, 177.3, 190.6,
                 200.7, 206.2, 211.9, 218.0, 224.5, 231.3, 246.3]
    # DATA SIG0 /.../ -- SIG0(20,24) filled in Fortran column-major order;
    # repetition factors in the original DATA (120*0. etc.) expanded into an explicit list concatenation
    _sig0_flat = (
        [0.0] * 120 +
        [.0460, .2400, .3500, .3700, .4000, .4300, .4400, .4600, .4700,
         .4900, .5000, .5200, .5700, .6200] + [0.0] * 6 +
        [0.0] * 80 +
        [.0092, .1000, .1900, .2100, .2300, .2500, .2600, .2900, .3000,
         .3200, .3400, .3500, .4100, .4300, .4500, .4800, .5000, .5300,
         .5600, .5900] +
        [0.0] * 20 +
        [.3400, .4600, .6300, .7700, .9100, 1.080] + [0.0] * 14 +
        [0.0] * 20 +
        [.0064, .1100, .2200, .4100, .9400, 1.000, 1.300, 1.600] +
        [0.0] * 12 +
        [0.0] * 80 +
        [.0370, .0650, .1300, .2400, .5500, .6300, .7700, .9500, 1.100,
         1.250] + [0.0] * 10 +
        [0.0] * 20 +
        [0.0] * 20 +
        [.0220, .0390, .0800, .1500, .3500, .4000, .4900, .6200, .7200,
         .7800, .8500, .9300, 1.020] + [0.0] * 7)
    sig0 = np.zeros((21, 25))
    sig0[1:, 1:] = np.array(_sig0_flat).reshape((20, 24), order='F')

    wl = np.zeros(21)                  # DIMENSION WL(20)
    sigs = np.zeros(21)                # DIMENSION SIGS(20)

    index = -ib - 100
    num = 20
    if index >= 13 and index <= 27:
        num = 15
    for i in range(1, num + 1):
        if index < 13:
            wl[i] = wl1[i]
        if index >= 13:
            wl[i] = wl2[i]
        sigs[i] = sig0[i, index]

    wlam = 2.997925e18 / fr
    il = 1
    ir = num
    for i in range(1, num):
        if wl[i] <= wlam <= wl[i + 1]:
            il = i
            ir = i + 1
            break                        # GO TO 60

    # 60 -- LINEAR INTERPOLATION:
    sigm = ((sigs[ir] - sigs[il]) * (wlam - wl[il]) / (wl[ir] - wl[il])
            + sigs[il])

    # IF OUTSIDE WAVELENGTH RANGE SET TO FIRST(LAST) VALUE:
    if wlam <= wl[1]:
        sigm = sigs[1]
    if wlam >= wl[num]:
        sigm = sigs[num]

    # IF LAST NON-ZERO SIG VALUES, NO INTERPOLATION:
    # (this line is commented out in the original: c  IF(SIGS(IR).EQ.0.) SIGM=SIGS(IL))

    return sigm * 1.e-18


def reiman(ib, fr):
    """C     ======================
    C
    C     Read table of photon energies and photo-ionization cross-sections
    C     from Reilman & Manson (1979, Ap. J. Suppl., 40, 815) for the species
    C     indicated by IB
    C
    C     Compute linearly interpolated value of the cross-section
    C     at the frequency FR.
    C
    C     (At the moment, only a few transitions are considered)

    Corresponds to tlusty208.f lines 10140-10207. FUNCTION, returns the function value.
    SAVE HEV,SIG0: read-only after DATA initialization -> assigned directly at the top of the function.
    """
    hev = np.zeros(31)                 # DIMENSION HEV(30)
    # DATA HEV /.../
    hev[1:] = [130., 160., 190., 210., 240., 270., 300., 330., 360., 390.,
               420., 450., 480., 510., 540., 570., 600., 630., 660., 690.,
               720., 750., 780., 810., 840., 870., 900., 930., 960., 990.]
    # DATA SIG0 /.../ -- SIG0(30,2) column-major; repetition factors expanded
    _sig0_flat = (
        [0.0] * 3 +
        [4.422e-1, 3.478e-1, 2.794e-1, 2.286e-1, 1.899e-1, 1.598e-1,
         1.360e-1, 1.169e-1, 1.013e-1, 8.845e-2, 7.776e-2, 6.877e-2,
         6.114e-2, 5.463e-2, 4.904e-2, 4.419e-2, 3.998e-2, 3.629e-2,
         3.305e-2, 3.019e-2, 2.766e-2, 2.540e-2, 2.339e-2, 2.158e-2,
         1.996e-2, 1.850e-2, 1.718e-2] +
        [0.0] * 4 +
        [1.981e-1, 1.584e-1, 1.290e-1, 1.066e-1, 8.932e-2, 7.567e-2,
         6.475e-2, 5.589e-2, 4.862e-2, 4.259e-2, 3.754e-2, 3.329e-2,
         2.966e-2, 2.656e-2, 2.388e-2, 2.157e-2, 1.954e-2, 1.777e-2,
         1.621e-2, 1.484e-2, 1.362e-2, 1.253e-2, 1.155e-2, 1.067e-2,
         9.888e-3, 9.179e-3])
    sig0 = np.zeros((31, 3))
    sig0[1:, 1:] = np.array(_sig0_flat).reshape((30, 2), order='F')

    f0 = np.zeros(31)                  # DIMENSION F0(30)
    sigs = np.zeros(31)                # DIMENSION SIGS(30)

    index = -ib - 300
    num = 30
    for i in range(1, num + 1):
        f0[i] = hev[i] * 2.418573e14
        sigs[i] = sig0[i, index]

    il = 1
    ir = num
    for i in range(1, num):
        if f0[i] <= fr <= f0[i + 1]:
            il = i
            ir = i + 1
            break                        # GO TO 60

    # 60 -- LINEAR INTERPOLATION:
    sigm = ((sigs[ir] - sigs[il]) * (fr - f0[il]) / (f0[ir] - f0[il])
            + sigs[il])

    # IF OUTSIDE WAVELENGTH RANGE SET TO FIRST(LAST) VALUE:
    if fr <= f0[1]:
        sigm = sigs[1]
    if fr >= f0[num]:
        sigm = sigs[num]

    # IF LAST NON-ZERO SIG VALUES, NO INTERPOLATION:
    # (this line is commented out in the original: c  IF(SIGS(IR).EQ.0.) SIGM=SIGS(IL))

    return sigm * 1.e-18


