    dxt = 0.05
    at1 = (xt - xt1) / dxt
    xn1 = 0.5 * kn1
    dxn = 0.5
    an1 = (xne - xn1) / dxn
    x11 = C.pfop[kt1, kn1, indx]
    x21 = C.pfop[kt1 + 1, kn1, indx]
    x12 = C.pfop[kt1, kn1 + 1, indx]
    x22 = C.pfop[kt1 + 1, kn1 + 1, indx]
    x1221 = x11 * x21 * x12 * x22
    if x1221 == 0.0:
        xx1 = x11 + at1 * (x21 - x11)
        xx2 = x12 + at1 * (x22 - x12)
        rrx = xx1 + an1 * (xx2 - xx1)
    else:
        x11 = math.log10(x11)
        x21 = math.log10(x21)
        x12 = math.log10(x12)
        x22 = math.log10(x22)
        xx1 = x11 + at1 * (x21 - x11)
        xx2 = x12 + at1 * (x22 - x12)
        rrx = xx1 + an1 * (xx2 - xx1)
        rrx = math.exp(2.3025851 * rrx)
