def intlem(prfh, wl0, iline, id):
    """C     ====================================
C
C     temperature is modified in order to account for the
C     effect of turbulent velocity on the Doppler width
C
C     interpolation to the actual values of temperature and electron
C     density
C
    Scalar dummies WL0, ILINE, ID are never modified -> no return.
    Corresponds to tlusty208.f lines 28634-28666"""
    FOC1 = 1.25e-9   # PARAMETER
    TTW = 2.0 / 3.0
    VTBC = 6.06e-9
    t = C.TEMP[id] + VTBC * C.VTURBS[id] * C.VTURBS[id]
    ane = C.ELEC[id]
    tl = math.log10(t)
    anel = math.log10(ane)
    f00 = FOC1 * math.exp(TTW * math.log(ane))
    C.XK = C.XK0[iline]  # XK belongs to COMMON /STRAUX/, used by INTHYD
    fxk = f00 * C.XK
    dop = 1.0e8 / wl0 * math.sqrt(1.65e8 * t)
    C.DBETA = wl0 * wl0 / 2.997925e18 / fxk
    C.BETAD = C.DBETA * dop
    nwl = C.NWLHYD[iline]
    for iwl in range(1, nwl + 1):
        prfh0 = 0.0
        # INTHYD assigns scalar dummy W0 -> by convention return all scalar dummies
        prfh0, tl, anel, iwl, iline = inthyd(prfh0, tl, anel, iwl, iline)
        prfh[iwl] = prfh0
    return


# ---------------------------------------------------------------------

def inthyd(w0, x0, z0, iwl, iline):
    """C     =====================================
C
C     Interpolation in temperature and electron density from the
C     Lemke tables for hydrogen lines to the actual valus of
C     temperature and electron density
C
    Scalar dummy W0 is assigned -> return all scalar dummies (w0, x0, z0, iwl, iline).
    Corresponds to tlusty208.f lines 28672-28761"""
    zz = np.zeros(4)  # DIMENSION ZZ(3),XX(3),WX(3),WZ(3), 1-based
    xx = np.zeros(4)
    wx = np.zeros(4)
    wz = np.zeros(4)
    nx = 2
    nz = 2
    nt = C.NTH[iline]
    ne = C.NEH[iline]
    beta = C.WLH[iwl, iline] / C.XK
    izh = 1
    # for values lower than the lowest grid value of electron density
    # the profiles are determined by the approximate expression
    # (see STARKA); not by an extrapolation in the HYD tables which may
    # be very inaccurate
    if z0 < C.XNELEM[1, iline] * 0.99:
        divstr(izh)
        w0 = starka(beta, TWO) * C.DBETA
        w0 = math.log10(w0)
        return w0, x0, z0, iwl, iline
    # Otherwise, one interpolates (or extrapolates for higher than the
    # highes grid value of electron density) in the HYD tables
    ipz = ne - 1  # if the loop never triggers GO TO 20, IPZ keeps the loop's last value NE-1
    for izz in range(1, ne):  # DO IZZ=1,NE-1
        ipz = izz
        if z0 <= C.XNELEM[izz + 1, iline]:
            break  # GO TO 20
    # 20
    n0z = ipz - idiv(nz, 2) + 1
    if n0z < 1:
        n0z = 1
    if n0z > ne - nz + 1:
        n0z = ne - nz + 1
    n1z = n0z + nz - 1
    for izz in range(n0z, n1z + 1):
        i0z = izz - n0z + 1
        zz[i0z] = C.XNELEM[izz, iline]
        # Likewise, the approximate expression instead of extrapolation
        # is used for higher that the highest grid value of temperature,
        # if the Doppler width expressed in beta units (BETAD) is
        # sufficiently large (> 10)
        # IF(X0.GT.1.01*XTLEM(NT,ILINE).AND.BETAD.GT.10.) THEN (original condition since changed)
        if x0 > 1.01 * C.XTLEM[nt, iline]:
            divstr(izh)
            w0 = starka(beta, TWO) * C.DBETA
            w0 = math.log10(w0)
            return w0, x0, z0, iwl, iline
        # Otherwise, normal inter- or extrapolation
        # Both interpolations (in T as well as in electron density) are
        # by default the quadratic interpolations in logarithms
        ipx = nt - 1  # if the loop never triggers GO TO 40, IPX keeps NT-1
        for ix in range(1, nt):  # DO IX=1,NT-1
            ipx = ix
            if x0 <= C.XTLEM[ix + 1, iline]:
                break  # GO TO 40
        # 40
        n0x = ipx - idiv(nx, 2) + 1
        if n0x < 1:
            n0x = 1
        if n0x > nt - nx + 1:
            n0x = nt - nx + 1
        n1x = n0x + nx - 1
        for ix in range(n0x, n1x + 1):
            i0 = ix - n0x + 1
            xx[i0] = C.XTLEM[ix, iline]
            wx[i0] = C.PRFHYD[iline, iwl, ix, izz]
        if wx[1] < -99.0 or wx[2] < -99.0 or wx[3] < -99.0:
            divstr(izh)
            w0 = starka(beta, TWO) * C.DBETA
            w0 = math.log10(w0)
            return w0, x0, z0, iwl, iline
        else:
            wz[i0z] = yint(xx, wx, x0)
    w0 = yint(zz, wz, z0)
    return w0, x0, z0, iwl, iline


# ---------------------------------------------------------------------

def yint(xl, yl, xl0):
    """C     ========================
C
C     Quadratic interpolation routine
C
C     Input:  XL - array of x
C             YL - array of f(x)
C             XL0 - the point x(0) to which one interpolates
C
    Corresponds to tlusty208.f lines 28767-28784"""
    a0 = (xl[2] - xl[1]) * (xl[3] - xl[2]) * (xl[3] - xl[1])
    a1 = (xl0 - xl[2]) * (xl0 - xl[3]) * (xl[3] - xl[2])
    a2 = (xl0 - xl[1]) * (xl[3] - xl0) * (xl[3] - xl[1])
    a3 = (xl0 - xl[1]) * (xl0 - xl[2]) * (xl[2] - xl[1])
    return (yl[1] * a1 + yl[2] * a2 + yl[3] * a3) / a0


# ---------------------------------------------------------------------

def stark0(i, j, izz, xkij, wl0, fij):
    """C     =======================================
C
C     Auxiliary procedure for evaluating the approximate Stark profile
C     of hydrogen lines - sets up necessary frequency independent
C     parameters
C
C     Input:  I     - principal quantum number of the lower level
C             J     - principal quantum number of the upper level
C             IZZ   - ionic charge (IZZ=1 for hydrogen, etc.)
C     Output: XKIJ  - coefficients K(i,j) for the Hotzmark profile;
C                     exact up to j=6, asymptotic for higher j
C             WL0   - wavelength of the line i-j
C             FIJ   - Stark f-value for the line i-j
C
    Scalar dummies XKIJ, WL0, FIJ are assigned -> return all scalar dummies (i, j, izz, xkij, wl0, fij).
    Corresponds to tlusty208.f lines 28790-28840"""
    # PARAMETER (RYD1=911.763811,RYD2=911.495745/4.,CXKIJ=5.5E-5)
    RYD1 = 911.763811  # unused; kept
    RYD2 = 911.495745 / 4.0  # unused; kept
    CXKIJ = 5.5e-5
    # PARAMETER (WI1=911.753578, WI2=227.837832)
    WI1 = 911.753578
    WI2 = 227.837832
    # PARAMETER (UN=1.,TEN=10.,TWEN=20.,HUND=100.) (UN same as in params)
    TEN = 10.0
    TWEN = 20.0
    HUND = 100.0
    # DATA XKIJT/.../; SAVE XKIJT,FSTARK; not modified afterwards -> assigned at function top.
    # Fortran DATA fills in column-major order: XKIJT(JMIN,I), 5 values per column (JMIN=1..5).
    _xkijt_cols = [
        None,
        [3.56e-4, 5.23e-4, 1.09e-3, 1.49e-3, 2.25e-3],
        [0.0125, 0.0177, 0.028, 0.0348, 0.0493],
        [0.124, 0.171, 0.223, 0.261, 0.342],
        [0.683, 0.866, 1.02, 1.19, 1.46],
    ]
    xkijt = np.zeros((6, 5))
    for _ic in range(1, 5):
        for _jr in range(1, 6):
            xkijt[_jr, _ic] = _xkijt_cols[_ic][_jr - 1]
    # DATA FSTARK/.../; FSTARK(JMIN,I), 10 values per column (JMIN=1..10).
    _fstark_cols = [
        None,
        [0.1387, 0.0791, 0.02126, 0.01394, 0.00642, 4.814e-3, 2.779e-3,
         2.216e-3, 1.443e-3, 1.201e-3],
        [0.3921, 0.1193, 0.03766, 0.02209, 0.01139, 8.036e-3, 5.007e-3,
         3.85e-3, 2.658e-3, 2.151e-3],
        [0.6103, 0.1506, 0.04931, 0.02768, 0.01485, 0.01023, 6.588e-3,
         4.996e-3, 3.524e-3, 2.838e-3],
        [0.8163, 0.1788, 0.05985, 0.03189, 0.01762, 0.01196, 7.825e-3,
         5.882e-3, 4.233e-3, 3.375e-3],
    ]
    fstark = np.zeros((11, 5))
    for _ic in range(1, 5):
        for _jr in range(1, 11):
            fstark[_jr, _ic] = _fstark_cols[_ic][_jr - 1]
    ii = i * i
    jj = j * j
    jmin = j - i
    if jmin <= 5:
        xkij = xkijt[jmin, i]
    else:
        xkij = CXKIJ * (ii * jj) * (ii * jj) / (jj - ii)
    if jmin <= 10:
        fij = fstark[jmin, i]
    else:
        cfij = ((TWEN * i + HUND) * j / (i + TEN) / (jj - ii))
        fij = fstark[10, i] * cfij * cfij * cfij
    wl0 = WI1
    if izz == 2:
        wl0 = WI2
    wl0 = wl0 / (UN / ii - UN / jj)
    return i, j, izz, xkij, wl0, fij


# ---------------------------------------------------------------------

def starka(beta, fac):
    """C     =========================
C
C     Approximate expressions for the hydrogen Stark profile
C
C     Input: BETA  - delta lambda in beta units,
C            BETAD - Doppler width in beta units
C            A     - auxiliary parameter
C                    A=1.5*LOG(BETAD)-1.761
C            DIV   - only for A > 1; division point between Doppler
C                    and asymptotic Stark wing, expressed in units
C                    of betad.
C                    DIV = solution of equation
C                    exp(-(beta/betad)**2)/betad/sqrt(pi)=
C                     = 1.5*FAC*beta**-5/2
C                    (ie. the point where Doppler profile is equal to
C                    the asymptotic Holtsmark)
C                    In order to save computer time, the division point
C                    DIV is calculated in advance by routine DIVSTR.
C            FAC   - Multiplicative factor (2. for H I; 1. for He II)
C
    Corresponds to tlusty208.f lines 28847-28901"""
    # PARAMETER (F0=-0.5758228,F1=0.4796232,F2=0.07209481,AL=1.26)
    F0 = -0.5758228
    F1 = 0.4796232
    F2 = 0.07209481
    AL = 1.26
    # PARAMETER (SD=0.5641895,SLO=-2.5,THRA=1.5,BL1=1.14,BL2=11.4)
    SD = 0.5641895  # unused; kept
    SLO = -2.5
    THRA = 1.5
    BL1 = 1.14
    BL2 = 11.4
    # PARAMETER (SAC=0.08, PISQ1=UN/1.77245385090551D0)
    SAC = 0.08
    PISQ1 = UN / 1.77245385090551
    # for a > 1 Doppler core + asymptotic Holtzmark wing with division
    #           point DIV
    betad1 = UN / C.BETAD
    if C.ADH > AL:
        xd = beta * betad1
        if xd <= C.DIVH:
            starka_ = math.exp(-xd * xd) * betad1 * PISQ1
        else:
            starka_ = THRA * fac * math.exp(SLO * math.log(beta))
    else:
        # empirical formula for a < 1
        if beta <= BL1:
            starka_ = SAC
        elif beta < BL2:
            xl = math.log(beta)
            fl = (F0 * xl + F1) * xl
            starka_ = F2 * math.exp(fl)
        else:
            starka_ = THRA * fac * math.exp(SLO * math.log(beta))
    return starka_


# ---------------------------------------------------------------------

def divstr(iah):
    """C     ======================
C
C     Auxiliary procedure for STARKA - determination of the division
C     point between Doppler and asymptotic Stark profiles
C
C     Input:  BETAD - Doppler width in beta units
C     Output: A     - auxiliary parameter
C                     A=1.5*LOG(BETAD)-1.671
C             DIV   - only for A > 1; division point between Doppler
C                     and asymptotic Stark wing, expressed in units
C                     of betad.
C                     DIV = solution of equation
C                     exp(-(beta/betad)**2)/betad/sqrt(pi)=3*beta**-5/2
C
C     He II: different definition of parameter ADH !
C
    Dummy IAH is never modified (output via ADH, DIVH of COMMON /STRAUX/) -> no return.
    Corresponds to tlusty208.f lines 28908-28948"""
    # PARAMETER (UNQ=1.25,UNH=1.5,TWH=2.5,FO=4.,FI=5.)
    UNQ = 1.25
    UNH = 1.5
    TWH = 2.5
    FO = 4.0
    FI = 5.0
    # PARAMETER (CA=1.671,BL=5.821,AL=1.26,CX=0.28,DX=0.0001)
    CA = 1.671
    BL = 5.821
    AL = 1.26
    CX = 0.28
    DX = 0.0001
    # PARAMETER (CA2=0.978,XA2=0.69314718)
    CA2 = 0.978  # unused; kept
    XA2 = 0.69314718
    C.ADH = UNH * math.log(C.BETAD) - CA
    if iah == 2:
        C.ADH = C.ADH + XA2
    if C.BETAD < BL:
        return
    if C.ADH >= AL:
        x = math.sqrt(C.ADH) * (UN + UNQ * math.log(C.ADH) / (FO * C.ADH - FI))
    else:
        x = math.sqrt(CX + C.ADH)
    for i in range(1, 6):  # DO I=1,5
        x2 = x * x
        xn = x * (UN - (x2 - TWH * math.log(x) - C.ADH) / (TWO * x2 - TWH))
        if abs(xn - x) <= DX:
            break  # GO TO 10
        x = xn
    # 10
    C.DIVH = x
    return


# ---------------------------------------------------------------------

def opahst():
    """C     =================
C
C     Auxiliary routine for START
C     sets up necessary parameters for routines OPAHYL and OPHYL1, i.e.
C     for opacity and emissivity in higher hydrogen lines
C     Also sets up Stark parameters for OPAHYL
C
    Corresponds to tlusty208.f lines 28954-29084"""
    C.ALLIM1 = 1450.0
    C.ABLIM1 = 6650.0
    C.ABLIM2 = 5000.0
    C.ABLIM3 = 6500.0
    # Lyman lines
    ilow = 1
    if abs(C.IOPHL1) == 1:
        C.IOPHL2 = C.IOPHL2 * 2
    for i in range(1, 5):
        C.M1FILE[i, ilow] = max(i, abs(C.IOPHL1))
        C.M2FILE[i, ilow] = i + 1
    for i in range(5, NLMX + 1):
        C.M1FILE[i, ilow] = max(i - 1, abs(C.IOPHL1))
        C.M2FILE[i, ilow] = min(i + 3, NLMX)
    C.M1FILE[NLMX, ilow] = NLMX + 1
    C.M2FILE[NLMX, ilow] = NLMX
    if abs(C.IOPHL1) > 100:
        C.IOPHL1 = imod(C.IOPHL1, 100)
        iset = 0
        while True:  # label 40
            # READ(IBUFF,*,ERR=90) IL1,IU1,IM1,IP1
            try:
                _v = _ldread(IBUFF, 4)
                il1 = int(_v[0])
                iu1 = int(_v[1])
                im1 = int(_v[2])
                ip1 = int(_v[3])
            except (EOFError, ValueError, IndexError):
                pass  # ERR=90: read error/EOF falls through to label 90
            else:
                iset = iset + 1
                if il1 <= 0 and iset == 1:
                    il1 = 1
                    iu1 = 4
                    im1 = 0
                    ip1 = 1
                if il1 <= 0 and iset == 2:
                    il1 = 5
                    iu1 = NLMX
                    im1 = 1
                    ip1 = 3
                iup1 = min(iu1, NLMX)
                for i in range(il1, iup1 + 1):
                    C.M1FILE[i, ilow] = max(i - im1, abs(C.IOPHL1))
                    C.M2FILE[i, ilow] = min(i + ip1, NLMX)
                if iu1 < NLMX:
                    continue  # GO TO 40
            # 90 CONTINUE
            # READ(IBUFF,*,ERR=100) ALLIM1
            try:
                _v = _ldread(IBUFF, 1)
            except (EOFError, ValueError, IndexError):
                break  # ERR=100: go straight to label 100 (skipping the ALLIM1<=0 check)
            C.ALLIM1 = _v[0]
            if C.ALLIM1 <= 0:
                C.ALLIM1 = 1450.0
            break
    C.M1FILE[NLMX, ilow] = NLMX + 1
    C.M2FILE[NLMX, ilow] = NLMX
    # Balmer lines
    # 100
    ilow = 2
    if abs(C.IOPHL2) == 1:
        C.IOPHL2 = C.IOPHL2 * 3
    if abs(C.IOPHL2) == 2:
        C.IOPHL2 = idiv(C.IOPHL2 * 3, 2)  # Fortran integer division
    for i in range(1, 7):
        C.M1FILE[i, ilow] = max(i, abs(C.IOPHL2))
        C.M2FILE[i, ilow] = i + 1
    for i in range(7, NLMX + 1):
        C.M1FILE[i, ilow] = max(i - 1, abs(C.IOPHL2))
        C.M2FILE[i, ilow] = min(i + 3, NLMX)
    if abs(C.IOPHL2) > 100:
        C.IOPHL2 = imod(C.IOPHL2, 100)
        iset = 0
        while True:  # label 140
            # READ(IBUFF,*,ERR=190) IL1,IU1,IM1,IP1
            try:
                _v = _ldread(IBUFF, 4)
                il1 = int(_v[0])
                iu1 = int(_v[1])
                im1 = int(_v[2])
                ip1 = int(_v[3])
            except (EOFError, ValueError, IndexError):
                pass  # ERR=190
            else:
                iset = iset + 1
                if il1 <= 0 and iset == 1:
                    il1 = 1
                    iu1 = 6
                    im1 = 0
                    ip1 = 1
                if il1 <= 0 and iset == 2:
                    il1 = 7
                    iu1 = NLMX
                    im1 = 1
                    ip1 = 3
                iup1 = min(iu1, NLMX)
                for i in range(il1, iup1 + 1):
                    C.M1FILE[i, ilow] = max(i - im1, abs(C.IOPHL2))
                    C.M2FILE[i, ilow] = min(i + ip1, NLMX)
                if iu1 < NLMX:
                    continue  # GO TO 140
            # 190 CONTINUE
            # READ(IBUFF,*,ERR=200,END=200) ABLIM1,ABLIM2,ABLIM3
            try:
                _v = _ldread(IBUFF, 3)
            except (EOFError, ValueError, IndexError):
                break  # ERR=200 / END=200
            C.ABLIM1 = _v[0]
            C.ABLIM2 = _v[1]
            C.ABLIM3 = _v[2]
            if C.ABLIM1 <= 0:
                C.ABLIM1 = 6650.0
            if C.ABLIM2 <= 0:
                C.ABLIM2 = 5000.0
            if C.ABLIM3 <= 0:
                C.ABLIM3 = 6500.0
            break
    # 200 CONTINUE
    C.M1FILE[NLMX, ilow] = NLMX + 1
    C.M2FILE[NLMX, ilow] = NLMX
    # -------------------
    # Stark paramereters
    # -------------------
    izzh = 1
    if C.IOPHL1 != 0:
        i = 1
        i1 = max(2, abs(C.IOPHL1))
        for j in range(i1, NLMX + 1):
            # STARK0 assigns scalar dummies XKIJ,WL0,FIJ -> unpack all scalar dummies and write back to array elements
            i, j, izzh, C.XKIJ[i, j], C.WL0[i, j], C.FIJ[i, j] = stark0(
                i, j, izzh, C.XKIJ[i, j], C.WL0[i, j], C.FIJ[i, j])
    if C.IOPHL2 != 0:
        i = 2
        i2 = max(3, abs(C.IOPHL2))
        for j in range(i2, NLMX + 1):
            i, j, izzh, C.XKIJ[i, j], C.WL0[i, j], C.FIJ[i, j] = stark0(
                i, j, izzh, C.XKIJ[i, j], C.WL0[i, j], C.FIJ[i, j])
    return


# ---------------------------------------------------------------------

def wnstor(id):
    """C     =====================
C
C     Stores occupation probabilities for hydrogen levels
C     in common WNCOM for further use
C
    Dummy ID is never modified -> no return.
    Corresponds to tlusty208.f lines 29090-29153

    Method: Hummer-Mihalas occupation probabilities w_n of the hydrogen
    levels, stored for the statistical equilibrium and opacity routines.
    References: Hummer & Mihalas 1988, ApJ 331, 794; Hubeny, Hummer &
    Lanz 1994, A&A 282, 151."""
    # PARAMETER (SIXTH=UN/6.,CCOR=0.09)
    SIXTH = UN / 6.0
    CCOR = 0.09
    # parameter (p1=0.1402,p2=0.1285,p3=un,p4=3.15,p5=4.)
    P1 = 0.1402
    P2 = 0.1285
    P3 = UN
    P4 = 3.15
    P5 = 4.0
    # parameter (tkn=3.01,ckn=5.33333333,cb0=8.59d14,f23=-2./3.)
    TKN = 3.01
    CKN = 5.33333333
    CB0 = 8.59e14
    F23 = -2.0 / 3.0
    if C.IOPTAB < 0:
        return
    cb = CB0 * C.bergfc
    ane = C.ELEC[id]
    a = CCOR * math.exp(SIXTH * math.log(ane)) / math.sqrt(C.TEMP[id])
    z = UN
    x = math.exp(P4 * math.log(UN + P3 * a))
    c1 = P1 * (x + P5 * (z - UN) * a * a * a)
    c2 = P2 * x
    beta0 = cb * z * z * z * math.exp(F23 * math.log(ane))
    for i in range(1, NLMX + 1):
        xn = i
        if xn <= TKN:
            xkn = UN
        else:
            xn1 = UN / (xn + UN)
            xkn = CKN * xn * xn1 * xn1
        beta = beta0 * xkn * C.XI2[i] * C.XI2[i]
        f = (c1 * beta * beta * beta) / (UN + c2 * beta * math.sqrt(beta))
        C.WNHINT[i, id] = f / (UN + f)
    # array WOP - occupation probabilities for explicit levels
    #   (if ifwop>1, occ. probabilities have been initialized
    #      for iron-peak elements and are not updated)
    for ii in range(1, C.NLEVEL + 1):
        if C.ifwop[ii] <= 0:
            C.wop[ii, id] = UN
        elif C.ifwop[ii] == 1:
            ie = C.IEL[ii]
            z = C.IZ[ie]
            # The occupation probability depends on the level only through the binding energy, so the
            # quantum number passed to WN is the effective quantum number n* = Z*sqrt(E_H/E_ion)
            # (fork 29750-29769); for hydrogenic ions it equals the principal quantum number. Levels above threshold / autoionizing (ENION <= 0) do not dissolve.
            if C.ENION[ii] > 0.0:
                xn = z * math.sqrt(EH / C.ENION[ii])
                C.wop[ii, id] = wn(xn, a, ane, z)
            else:
                C.wop[ii, id] = UN
        if C.ifwop[ii] > 1 and C.LTE:
            C.wop[ii, id] = UN
    return


# ---------------------------------------------------------------------

def wn(xn, a, ane, z):
    """c
c     evaluation of the occupation probablities for a hydrogenic ion
c     using eqs (4.26), and (4.39) of Hummer,Mihalas Ap.J. 331, 794, 1988.
c     approximate evaluation of Q(beta) - Hummer
c
c     Input: xn  - real number corresponding to quantum number n
c            a   - correlation parameter
c            ane - electron density
c            z   - ionic charge
c
    Corresponds to tlusty208.f lines 29160-29200"""
    # parameter (p1=0.1402,p2=0.1285,p3=un,p4=3.15,p5=4.)
    P1 = 0.1402
    P2 = 0.1285
    P3 = UN
    P4 = 3.15
    P5 = 4.0
    # parameter (tkn=3.01,ckn=5.33333333,cb0=8.59d14)
    TKN = 3.01
    CKN = 5.33333333
    CB0 = 8.59e14
    # parameter (f23=-2./3.)
    F23 = -2.0 / 3.0
    cb = CB0 * C.bergfc
    # evaluation of k(n)
    if xn <= TKN:
        xkn = UN
    else:
        xn1 = UN / (xn + UN)
        xkn = CKN * xn * xn1 * xn1
    # evaluation of beta
    beta = cb * z * z * z * xkn / (xn * xn * xn * xn) * math.exp(F23 * math.log(ane))
    # approximate expression for Q(beta)
    x = math.exp(P4 * math.log(UN + P3 * a))
    c1 = P1 * (x + P5 * (z - UN) * a * a * a)
    c2 = P2 * x
    f = (c1 * beta * beta * beta) / (UN + c2 * beta * math.sqrt(beta))
    return f / (UN + f)


# ---------------------------------------------------------------------

def dwnfr(mode, n, fre, a, ane, z, fr, dw):
    """C     ==========================================
C
C     Auxiliary routine to compute set of dissolved fractions
C     for all frequencies
C      MODE=0  ->  DW=1
C      MODE>0  ->  DW=1-w
C
    Only array dummy DW is modified -> no return.
    Corresponds to tlusty208.f lines 29207-29250

    Method: dissolved fraction 1-w of a level, from the Hummer-Mihalas
    occupation probability w, evaluated for a set of frequencies with the
    hydrogenic effective quantum number.
    References: Hummer & Mihalas 1988, ApJ 331, 794."""
    # parameter (p1=0.1402,p2=0.1285,p3=un,p4=3.15,p5=4.)
    P1 = 0.1402
    P2 = 0.1285
    P3 = UN
    P4 = 3.15
    P5 = 4.0
    # parameter (tkn=3.01,ckn=5.33333333,cb0=8.59d14,f23=-2./3.)
    TKN = 3.01
    CKN = 5.33333333
    CB0 = 8.59e14
    F23 = -2.0 / 3.0
    # PARAMETER (FRH=3.28805D15,SQFRH=5.734152D7)
    FRH = 3.28805e15  # unused; kept
    SQFRH = 5.734152e7
    # FIX(fork 29848): in the original cb=cb0*berfc, berfc is an undeclared variable
    # (a typo for bergfc; cf. WNSTOR/wn/DWNFR1 which all use bergfc); corrected to bergfc of COMMON /INPPAR/.
    cb = CB0 * C.bergfc
    if mode == 0:
        for ij in range(1, n + 1):
            dw[ij] = UN
    else:
        for ij in range(1, n + 1):
            if fr[ij] < fre:
                xn = SQFRH * z / math.sqrt(fre - fr[ij])
                if xn <= TKN:
                    xkn = UN
                else:
                    xn1 = UN / (xn + UN)
                    xkn = CKN * xn * xn1 * xn1
                beta = cb * z * z * z * xkn / (xn * xn * xn * xn) * math.exp(F23 * math.log(ane))
                x = math.exp(P4 * math.log(UN + P3 * a))
                c1 = P1 * (x + P5 * (z - UN) * a * a * a)
                c2 = P2 * x
                f = (c1 * beta * beta * beta) / (UN + c2 * beta * math.sqrt(beta))
                dw[ij] = UN - f / (UN + f)
            else:
                dw[ij] = UN
    return


# ---------------------------------------------------------------------

def odf1(imode, il, iu, id, odf):
    """C     ===================================
C
C     opacity distribution function for overlapping lines near the series limit
C
C     The lines converge to the edge of the (continuum) transition IL - IU,
C     IL - index of the lower level
C     IU - index of the upper level (usually the ground state of teh next ion)
C     ID - depth index
C
C     Output: ODF - opacity distribution function interpolated to the set of
C                   explicit frequencies
C
    Scalar dummies IMODE,IL,IU,ID are never modified -> no return.
    SAVE FRO,SGFR,ODF0,IODF -> module-level _save_odf1_* (retained between calls).
    Corresponds to tlusty208.f lines 29257-29435"""
    # PARAMETER (FRH=3.28805D15,CQT=1.284523D12)
    FRH = 3.28805e15  # unused; kept
    CQT = 1.284523e12
    # PARAMETER (CCOR=0.09,C00=1.25D-9,CID=0.02654,SIXTH=UN/6.)
    CCOR = 0.09  # unused; kept
    C00 = 1.25e-9
    CID = 0.02654
    SIXTH = UN / 6.0
    # DIMENSION FRO(MFRO),ODF0(MFRO),ABSO0(MFRO),ODF(MFREQ),SGT(MFRO),
    #           ALAM(MFRO),FROD(MFRO),SGFR(MFRO),IODF(MFRO),IODR(MFRO),DWF(MFRO)
    # SAVE FRO,SGFR,ODF0,IODF -> module-level; note that ABSO0 in this routine is a local array
    # (does not include ARRAY1.FOR and has a local DIMENSION), unrelated to ABSO0 of blank COMMON.
    fro = _save_odf1_fro
    sgfr = _save_odf1_sgfr
    odf0 = _save_odf1_odf0
    iodf = _save_odf1_iodf
    abso0 = np.zeros(MFRO + 1)
    sgt = np.zeros(MFRO + 1)
    alam = np.zeros(MFRO + 1)
    frod = np.zeros(MFRO + 1)
    iodr = np.zeros(MFRO + 1, dtype=np.int64)
    dwf = np.zeros(MFRO + 1)
    i = C.NQUANT[il]  # unused afterwards; kept
    kl = C.INDODF[il]
    ielo = C.IEL[il]
    n1h = C.NLAST[ielo]  # unused afterwards; kept
    nq1 = C.NQLODF[il]
    fre = C.ENION[il] / H
    t = C.TEMP[id]
    sqt = math.sqrt(t)
    ane = C.ELEC[id]
    anes = math.exp(SIXTH * math.log(ane))
    f00 = C00 * anes * anes * anes * anes
    dop0 = CQT * sqt
    qz = C.IZ[ielo]  # unused afterwards; kept
    # pseudocontinuum opacity (non-zero in all frequencies);
    # formulated through the dissolved fraction
    itr = C.ITRA[il, iu]
    nfr0 = C.NFRODF[kl]
    if imode == 0:
        for ij in range(1, nfr0 + 1):
            fro[ij] = C.FROS[ij, kl]
            sgfr[ij] = sigk(fro[ij], itr, 1)  # SIGK is a function; does not modify scalar dummies
            alam[ij] = CAS / fro[ij]
    # function D(nu) - dissolved fraction
    # CALL DWNFR(1,NFR0,FRE,ACOR,ANE,QZ,FRO,DWF)  <- this call is commented out in the original
    # TODO(port): hence DWF is never assigned (undefined value in Fortran); here it is all zeros;
    # the ABSO0=SGFR*DWF below is therefore always 0. Translated verbatim, keeping the original state.
    for ij in range(1, nfr0 + 1):
        abso0[ij] = sgfr[ij] * dwf[ij]
    # summation over individual lines
    for j in range(nq1, NLMX + 1):
        xj = j  # unused afterwards; kept
        fxk = f00 * C.XKIJ[kl, j]
        dop = dop0 / C.WL0[kl, j]
        C.DBETA = C.WL0[kl, j] * C.WL0[kl, j] / CAS / fxk
        C.BETAD = dop * C.DBETA
        fid = CID * C.FIJ[kl, j] * C.DBETA
        divstr(1)
        wprob = C.WNHINT[j, id]
        odfhst(nfr0, fxk, fid, wprob, C.WL0[kl, j], alam, sgt)
        for ij in range(1, nfr0 + 1):
            abso0[ij] = abso0[ij] + sgt[ij]
    # opacity distribution function in the internal set of frequencies
    if imode == 0:
        odf0[1] = abso0[1]
        iodf[1] = 1
        for ij in range(2, nfr0 + 1):
            odf0[ij] = abso0[ij]
            iodf[ij] = ij
            if odf0[ij] < odf0[ij - 1]:
                ab = odf0[ij]
                ijodf = iodf[ij]
                for ij0 in range(1, ij):  # DO IJ0=1,IJ-1 (insertion-sort shift back)
                    ij1 = ij - ij0 + 1
                    if odf0[ij1] >= odf0[ij1 - 1]:
                        break  # GO TO 71
                    odf0[ij1] = odf0[ij1 - 1]
                    odf0[ij1 - 1] = ab
                    iodf[ij1] = iodf[ij1 - 1]
                    iodf[ij1 - 1] = ijodf
                # 71 CONTINUE
            if odf0[ij] > 0.001:
                # 603 format(' ij,id,odf0',2i5,1pd10.3)
                print(' ij,id,odf0%5d%5d%10.3E' % (ij, id, odf0[ij]))
    else:
        odf0[1] = abso0[iodf[1]]
        iodr[1] = iodf[1]
        for ij in range(2, nfr0 + 1):
            odf0[ij] = abso0[iodf[ij]]
            iodr[ij] = iodf[ij]
            if odf0[ij] < odf0[ij - 1]:
                ab = odf0[ij]
                ijodf = iodr[ij]
                for ij0 in range(1, ij):  # DO IJ0=1,IJ-1
                    ij1 = ij - ij0 + 1
                    if odf0[ij1] >= odf0[ij1 - 1]:
                        break  # GO TO 86
                    odf0[ij1] = odf0[ij1 - 1]
                    odf0[ij1 - 1] = ab
                    iodr[ij1] = iodr[ij1 - 1]
                    iodr[ij1 - 1] = ijodf
                # 86 CONTINUE
            if odf0[ij] > 0.001:
                # 603 format(' ij,id,odf0',2i5,1pd10.3)
                print(' ij,id,odf0%5d%5d%10.3E' % (ij, id, odf0[ij]))
        for ij in range(1, nfr0 + 1):
            iodf[ij] = iodr[ij]
    # Reinitialization of the internal frequencies set
    frod[1] = fro[1]
    iw = iodf[1]
    if iw > 1 and iw < nfr0:
        w1 = fro[iw - 1] - fro[iw + 1]
    elif iw == 1:
        w1 = fro[1] - fro[2]
    else:
        w1 = fro[nfr0 - 1] - fro[nfr0]
    for ij in range(2, nfr0):  # DO IJ=2,NFR0-1
        iw = iodf[ij]
        if iw > 1 and iw < nfr0:
            w2 = HALF * (fro[iw - 1] - fro[iw + 1])
        elif iw == 1:
            w2 = HALF * (fro[1] - fro[2])
        else:
            w2 = HALF * (fro[nfr0 - 1] - fro[nfr0])
        frod[ij] = frod[ij - 1] - HALF * (w1 + w2)
        w1 = w2
    ij = nfr0
    iw = iodf[ij]
    if iw > 1 and iw < nfr0:
        w2 = fro[iw - 1] - fro[iw + 1]
    elif iw == 1:
        w2 = fro[1] - fro[2]
    else:
        w2 = fro[nfr0 - 1] - fro[nfr0]
    frod[ij] = frod[ij - 1] - HALF * (w1 + w2)
    # Interpolated opacity distribution function to explicit frequencies
    for ij in range(2, C.NFREQ + 1):  # DO 150 IJ=2,NFREQ
        if C.FREQ[ij] > C.FREQ[ij - 1]:
            return
        odf[ij] = 0.0
        if C.FREQ[ij] > frod[1] or C.FREQ[ij] < frod[nfr0]:
            continue  # GO TO 150
        if id == 1:
            if C.FREQ[ij - 1] > frod[1]:
                C.I1ODF[il] = ij
            C.I2ODF[il] = ij
        ij0 = nfr0  # if the loop never triggers GO TO 120, IJ0 keeps the loop's last value NFR0
        for ij1 in range(2, nfr0 + 1):  # DO IJ1=2,NFR0
            ij0 = ij1
            if C.FREQ[ij] >= frod[ij1]:
                break  # GO TO 120
        # 120
        odf[ij] = odf0[ij0 - 1] + (odf0[ij0] - odf0[ij0 - 1]) / (
            frod[ij0] - frod[ij0 - 1]) * (C.FREQ[ij] - frod[ij0 - 1])
    # 150 CONTINUE
    return


