def odfhst(n, fxk, fid, wp, wl, alam, sg):
    """C     ==========================================
C
C     Auxiliary routine for ODF1 (replaces multiple calls to STARKA)
C
    Only array dummy SG is modified -> no return.
    Corresponds to tlusty208.f lines 29441-29494"""
    # PARAMETER (F0=-0.5758228,F1=0.4796232,F2=0.07209481,AL=1.26)
    F0 = -0.5758228
    F1 = 0.4796232
    F2 = 0.07209481
    AL = 1.26
    # PARAMETER (SD=0.5641895,SLO=-2.5,THRA=1.5,BL1=1.14,BL2=11.4)
    SD = 0.5641895
    SLO = -2.5
    THRA = 1.5
    BL1 = 1.14
    BL2 = 11.4
    # PARAMETER (SAC=0.08, THR=THRA*TWO)
    SAC = 0.08
    THR = THRA * TWO
    betad1 = UN / C.BETAD
    fxk1 = UN / fxk
    fidwp = fid * wp
    # for a > 1 Doppler core + asymptotic Holtzmark wing with division
    #           point DIV
    if C.ADH > AL:
        for ij in range(1, n + 1):
            beta = abs(alam[ij] - wl) * fxk1
            xd = beta * betad1
            if xd <= C.DIVH:
                st = SD * math.exp(-xd * xd) * betad1
            else:
                st = THR * math.exp(SLO * math.log(beta))
            sg[ij] = st * fidwp
    else:
        # empirical formula for a < 1
        for ij in range(1, n + 1):
            beta = abs(alam[ij] - wl) * fxk1
            xd = beta * betad1  # unused in this branch; kept
            if beta <= BL1:
                st = SAC
            elif beta < BL2:
                xl = math.log(beta)
                fl = (F0 * xl + F1) * xl
                st = F2 * math.exp(fl)
            else:
                st = THR * math.exp(SLO * math.log(beta))
            sg[ij] = st * fidwp
    return


