def odffr(il, iu):
    """C     =======================
C
C     Internal frequencies set for opacity distribution function
C     for overlapping lines near the series limit
C
C     The lines converge to the edge of the (continuum) transition IL - IU,
C     IL - index of the lower level
C     IU - index of the upper level (usually the ground state of the next ion)
C          or a mean level in the line ODF formalism
C
C     Output: FROS - set of internal frequencies
C                    in common ODFFRQ
C
    Dummies IL,IU are never modified -> no return.
    Corresponds to tlusty208.f lines 29500-29596"""
    # PARAMETER (FRH=3.28805D15,CDOP=2.84511D-7,CDOM=14.)
    FRH = 3.28805e15
    CDOP = 2.84511e-7
    CDOM = 14.0
    # PARAMETER (SIX=6.,SEPT=7.)
    SIX = 6.0
    SEPT = 7.0
    ffro = np.zeros(MFRO + 1)  # DIMENSION FFRO(MFRO)
    ch = C.IZ[C.IEL[il]] * C.IZ[C.IEL[il]]
    frion = ch * FRH
    fre = C.ENION[il] / H
    nf = 1
    nq1 = C.NQUANT[iu]
    xl2 = UN / (C.NQUANT[il] * C.NQUANT[il])
    xu1 = UN / ((C.NQUANT[iu] - 1) * (C.NQUANT[iu] - 1))
    xu2 = UN / (C.NQUANT[iu] * C.NQUANT[iu])
    frc = frion * (xl2 - xu2)
    ffro[nf] = HALF * (frc + frion * (xl2 - xu1))
    kt = C.ITRA[il, iu]
    kl = C.JNDODF[kt]
    dopo = CDOP * math.sqrt(C.TEFF) * frc
    dopm = CDOM * dopo
    fr1 = ffro[1]
    goto10 = False
    for i in range(nq1, NLMX + 1):
        ii = i * i
        fr2 = fre - frion / ii
        df = fr2 - fr1
        if df > dopm:
            for j in range(1, 8):  # DO J=1,7
                nf = nf + 1
                ffro[nf] = fr1 + j * dopo
            df = fr2 - SEPT * dopo - ffro[nf]
            ni = int(df / SIX / dopo)  # Fortran INT: truncation toward zero
            ddf = df / (ni + 1)
            for j in range(1, ni + 1):
                nf = nf + 1
                ffro[nf] = fr1 + SEPT * dopo + j * ddf
            for j in range(7, -1, -1):  # DO J=7,0,-1
                nf = nf + 1
                ffro[nf] = fr2 - j * dopo
            fr1 = fr2
        else:
            ni = int(df / dopo)  # Fortran INT
            ddf = df / (ni + 1)
            for j in range(1, ni + 1):
                nf = nf + 1
                if nf > MFRO - 3:
                    nf = nf - 1
                    goto10 = True
                    break  # GO TO 10
                ffro[nf] = fr1 + j * ddf
            if goto10:
                break  # GO TO 10 (exit the I loop)
            nf = nf + 1
            ffro[nf] = fr2
            fr1 = fr2
    # 10 CONTINUE
    nf = nf + 1
    ffro[nf] = fre * 0.999999999
    C.NFRODF[kl] = nf
    if nf > MFRO:
        quit('too many points for hydrogen ODF - nf.gt.mfro', nf, MFRO)
    for i in range(1, nf + 1):
        C.FROS[i, kl] = ffro[nf - i + 1]
    # Associated weights
    C.WNUS[1, kl] = HALF * (C.FROS[1, kl] - C.FROS[2, kl])
    C.WNUS[nf, kl] = HALF * (C.FROS[nf - 1, kl] - C.FROS[nf, kl])
    for i in range(2, nf):  # DO I=2,NF-1
        C.WNUS[i, kl] = HALF * (C.FROS[i - 1, kl] - C.FROS[i + 1, kl])
    return


