def chckse():
    """C     ==================
C
C     Auxiliary output routine, which enables printing
C     total rates to check statistical equilibrium at each depth.
C
C     Output: unit 16: <OUT> and <IN> rates, and relative difference,
C                      for each level.
C
    Corresponds to tlusty208.f lines 29602-29687"""
    # PARAMETER (MLEVES=mlevel); DIMENSION ROUT(MLEVES,MDEPTH),RIN(MLEVES,MDEPTH)
    rout = np.zeros((MLEVEL + 1, MDEPTH + 1))
    rin = np.zeros((MLEVEL + 1, MDEPTH + 1))
    if C.IOPTAB < 0:
        return
    for id in range(1, C.ND + 1):
        t = C.TEMP[id]
        hkt = HK / t
        tk = hkt / H
        ane = C.ELEC[id]
        sabolf(id)  # SABOLF does not modify scalar dummy ID
        for iat in range(1, C.NATOM + 1):
            n0i = C.N0A[iat]
            nki = C.NKA[iat]
            n1i = nki - 1  # unused afterwards; kept
            for i in range(n0i, nki + 1):
                out = 0.0
                xin = 0.0
                nke = C.NNEXT[C.IEL[i]]
                for it in range(1, C.NTRANS + 1):
                    ii = C.ILOW[it]
                    jj = C.IUP[it]
                    if ii == i:
                        j = jj
                        if C.LINE[it]:
                            aij = (C.COLTAR[it, id] * C.wop[i, id]
                                   + C.RRD[it, id] * C.G[i] / C.G[j] * C.wop[i, id]
                                   * math.exp(hkt * C.FR0[it]))
                        else:
                            corr = UN
                            nke = C.NNEXT[C.IEL[i]]
                            if nke != j:
                                corr = (C.G[nke] / C.G[j]
                                        * math.exp((C.ENION[nke] - C.ENION[j]) * tk))
                            # the original is indeed COLTAR+WOP+RRD*... ("+WOP(I,ID)+" translated verbatim)
                            aij = (C.COLTAR[it, id] + C.wop[i, id]
                                   + C.RRD[it, id] * ane * C.SBF[i] * corr * C.wop[i, id])
                        aji = (C.COLRAT[it, id] + C.RRU[it, id]) * C.wop[j, id]
                        xin = xin + aij * C.POPUL[j, id]
                        out = out + aji
                    elif jj == i:
                        j = ii
                        if C.LINE[it]:
                            aji = (C.COLTAR[it, id] + C.wop[j, id]
                                   + C.RRD[it, id] * C.G[j] / C.G[i] * C.wop[j, id]
                                   * math.exp(hkt * C.FR0[it]))
                        else:
                            corr = UN
                            nke = C.NNEXT[C.IEL[j]]
                            if nke != i:
                                corr = (C.G[nke] / C.G[i]
                                        * math.exp((C.ENION[nke] - C.ENION[i]) * tk))
                            aji = (C.COLTAR[it, id] * C.wop[j, id]
                                   + C.RRD[it, id] * ane * C.SBF[j] * corr * C.wop[j, id])
                        aij = (C.COLRAT[it, id] + C.RRU[it, id]) * C.wop[i, id]
                        xin = xin + aij * C.POPUL[j, id]
                        out = out + aji
                rin[i, id] = xin
                rout[i, id] = out * C.POPUL[i, id]
    _auto_unit(16)  # unit 16 not explicitly OPENed (preconnected)
    for i in range(1, C.NLEVEL + 1):
        if rin[i, C.ND] > 0.0:
            # 300 FORMAT('1 Level:',I5///); '1' is the carriage-control character (page eject),
            # the three / then emit two blank records
            write_line(16, '1 Level:%5d' % i)
            write_line(16, '')
            write_line(16, '')
            for id in range(1, C.ND + 1):
                del_ = (rin[i, id] - rout[i, id]) / rin[i, id]
                # 310 FORMAT(2I5,1P3E16.7,2x,e16.7)
                write_line(16, '%5d%5d%16.7E%16.7E%16.7E  %16.7E'
                           % (i, id, rin[i, id], rout[i, id], del_, C.POPUL[i, id]))
    return


