def accel2():
    """C     =================
C
C     Acceleration of convergence (from Auer 1987, in Numerical
C     Radiative Transfer p. 101)
C
    Corresponds to tlusty208.f lines 29693-29802

    Method: Ng acceleration (Aitken-type extrapolation from three
    consecutive iterates) applied to the structural vector PSI; IACC, IACC0
    and IACD control onset and frequency.
    References: Ng 1974, J. Chem. Phys. 61, 2680; Auer 1987, in Numerical
    Radiative Transfer, p. 101."""
    if C.NITER < C.IACC or C.ITER < C.IACC0:
        return
    ipng = 1
    if C.IACD > 0:
        ipng = imod(C.ITER - C.IACC, C.IACD)
    if not C.LAC2:
        ipt = imod(C.ITER, 3)
        ipt0 = imod(C.IACC, 3)  # unused afterwards; kept
        ipt1 = imod(C.IACC + 1, 3)
        ipt2 = imod(C.IACC + 2, 3)
        if C.ITER == C.IACC0:
            for id in range(1, C.ND + 1):
                for ix in range(1, C.NN + 1):
                    C.PSY3[ix, id] = C.PSY0[ix, id]
        elif ipt == ipt1:
            for id in range(1, C.ND + 1):
                for ix in range(1, C.NN + 1):
                    C.PSY2[ix, id] = C.PSY0[ix, id]
        elif ipt == ipt2:
            for id in range(1, C.ND + 1):
                for ix in range(1, C.NN + 1):
                    C.PSY1[ix, id] = C.PSY0[ix, id]
    elif ipng != 0:
        for id in range(1, C.ND + 1):
            for ix in range(1, C.NN + 1):
                C.PSY3[ix, id] = C.PSY2[ix, id]
        for id in range(1, C.ND + 1):
            for ix in range(1, C.NN + 1):
                C.PSY2[ix, id] = C.PSY1[ix, id]
        for id in range(1, C.ND + 1):
            for ix in range(1, C.NN + 1):
                C.PSY1[ix, id] = C.PSY0[ix, id]
        return
    if C.ITER < C.IACC:
        return
    a1 = 0.0
    b1 = 0.0
    b2 = 0.0
    c1 = 0.0
    c2 = 0.0
    for ix in range(1, C.NN + 1):
        if C.LSNG[ix]:
            for id in range(1, C.ND + 1):
                wt = 0.0
                if C.PSY0[ix, id] != 0.0:
                    wt = 1.0 / abs(C.PSY0[ix, id])
                d0 = C.PSY0[ix, id] - C.PSY1[ix, id]
                d1 = d0 - C.PSY1[ix, id] + C.PSY2[ix, id]
                d2 = d0 - C.PSY2[ix, id] + C.PSY3[ix, id]
                a1 = a1 + wt * d1 * d1
                b1 = b1 + wt * d1 * d2
                b2 = b2 + wt * d2 * d2
                c1 = c1 + wt * d0 * d1
                c2 = c2 + wt * d0 * d2
    ab = b2 * a1 - b1 * b1
    if ab == 0.0:
        # 601 FORMAT(' **** ACCEL2, ITER=',I4,'   AB = ',F7.3)
        print(' **** ACCEL2, ITER=%4d   AB = %7.3f' % (C.ITER, ab))
        _auto_unit(10)
        write_line(10, ' **** ACCEL2, ITER=%4d   AB = %7.3f' % (C.ITER, ab))
        C.IACC = C.IACC + C.IACD
        C.IACC0 = C.IACC - 3
        return
    a = (b2 * c1 - b1 * c2) / ab
    b = (a1 * c2 - b1 * c1) / ab
    for id in range(1, C.ND + 1):
        for ix in range(1, C.NN + 1):
            C.PSY0[ix, id] = ((1.0 - a - b) * C.PSY0[ix, id] + a * C.PSY1[ix, id]
                              + b * C.PSY2[ix, id])
    # 600 FORMAT(' **** ACCEL2, ITER=',I4)
    print(' **** ACCEL2, ITER=%4d' % C.ITER)
    _auto_unit(10)
    write_line(10, ' **** ACCEL2, ITER=%4d' % C.ITER)
    C.LAC2 = True
    C.LRES2 = False
    # call RESOLV after evaluating the accelerated estimate
    resolv()
    C.LRES2 = True
    return


# ---------------------------------------------------------------------

def accelp():
    """C     =================
C
C     Acceleration of convergence for populations
C     (from Auer 1987, in Numerical Radiative Transfer p. 101)
C
    Corresponds to tlusty208.f lines 29809-29911

    Method: Ng acceleration applied to the level populations within the
    lambda iterations.
    References: Ng 1974, J. Chem. Phys. 61, 2680; Auer 1987, in Numerical
    Radiative Transfer, p. 101."""
    # COMMON/POPULS/POPUL1,POPUL2,POPUL3 (MLEVEL,MDEPTH) -- canonical name; see INLINE_COMMONS.md
    if C.NLAMBD < C.IACPP or C.ILAM < C.IACC0P:
        return
    ipng = 1
    if C.IACDP > 0:
        ipng = imod(C.ILAM - C.IACPP, C.IACDP)
    if not C.LAC2P:
        ipt = imod(C.ILAM, 3)
        ipt0 = imod(C.IACPP, 3)  # unused afterwards; kept
        ipt1 = imod(C.IACPP + 1, 3)
        ipt2 = imod(C.IACPP + 2, 3)
        if C.ILAM == C.IACC0P:
            for id in range(1, C.ND + 1):
                for ix in range(1, C.NLEVEL + 1):
                    C.POPUL3[ix, id] = C.POPUL[ix, id]
        elif ipt == ipt1:
            for id in range(1, C.ND + 1):
                for ix in range(1, C.NLEVEL + 1):
                    C.POPUL2[ix, id] = C.POPUL[ix, id]
        elif ipt == ipt2:
            for id in range(1, C.ND + 1):
                for ix in range(1, C.NLEVEL + 1):
                    C.POPUL1[ix, id] = C.POPUL[ix, id]
    elif ipng != 0:
        for id in range(1, C.ND + 1):
            for ix in range(1, C.NLEVEL + 1):
                C.POPUL3[ix, id] = C.POPUL2[ix, id]
        for id in range(1, C.ND + 1):
            for ix in range(1, C.NLEVEL + 1):
                C.POPUL2[ix, id] = C.POPUL1[ix, id]
        for id in range(1, C.ND + 1):
            for ix in range(1, C.NLEVEL + 1):
                C.POPUL1[ix, id] = C.POPUL[ix, id]
        return
    if C.ILAM < C.IACPP:
        return
    a1 = 0.0
    b1 = 0.0
    b2 = 0.0
    c1 = 0.0
    c2 = 0.0
    # TODO(port): unlike ACCEL2, the original code has no WT=0. reset inside the loop;
    # if POPUL(IX,ID)==0 then WT keeps the previous element's value, and is undefined when the first element is 0.
    # Here it is initialized to 0.0 (affects only that pathological case).
    wt = 0.0
    for id in range(1, C.ND + 1):
        for ix in range(1, C.NLEVEL + 1):
            if C.POPUL[ix, id] != 0.0:
                wt = 1.0 / abs(C.POPUL[ix, id])
            d0 = C.POPUL[ix, id] - C.POPUL1[ix, id]
            d1 = d0 - C.POPUL1[ix, id] + C.POPUL2[ix, id]
            d2 = d0 - C.POPUL2[ix, id] + C.POPUL3[ix, id]
            a1 = a1 + wt * d1 * d1
            b1 = b1 + wt * d1 * d2
            b2 = b2 + wt * d2 * d2
            c1 = c1 + wt * d0 * d1
            c2 = c2 + wt * d0 * d2
    ab = b2 * a1 - b1 * b1
    if ab == 0.0:
        # 601 FORMAT(' **** ACCELP, ITER=',I4,'   AB = ',F7.3)
        print(' **** ACCELP, ITER=%4d   AB = %7.3f' % (C.ILAM, ab))
        _auto_unit(10)
        write_line(10, ' **** ACCELP, ITER=%4d   AB = %7.3f' % (C.ILAM, ab))
        C.IACPP = C.IACPP + C.IACDP
        C.IACC0P = C.IACPP - 3
        return
    a = (b2 * c1 - b1 * c2) / ab
    b = (a1 * c2 - b1 * c1) / ab
    for id in range(1, C.ND + 1):
        for ix in range(1, C.NLEVEL + 1):
            C.POPUL[ix, id] = ((1.0 - a - b) * C.POPUL[ix, id] + a * C.POPUL1[ix, id]
                               + b * C.POPUL2[ix, id])
    # 600 FORMAT(' **** ACCELP, ITER=',I4)
    print(' **** ACCELP, ITER=%4d' % C.ILAM)
    _auto_unit(10)
    write_line(10, ' **** ACCELP, ITER=%4d' % C.ILAM)
    C.LAC2P = True
    return


# ---------------------------------------------------------------------

def timing(mod, iter):
    """C     ===========================
C
C     Timing procedure (call machine dependent routine!!)
C
    Dummies MOD, ITER are never modified -> no return.
    DATA T0/0./ SAVE T0 -> module-level _save_timing_t0.
    Corresponds to tlusty208.f lines 29917-29940"""
    global _save_timing_t0
    dummy = np.zeros(3)  # dimension dummy(2), 1-based
    time_ = _etime(dummy)  # TIME=etime(dummy) (machine-dependent; see TODO on _etime)
    dt = time_ - _save_timing_t0
    _save_timing_t0 = time_
    ip = 0      # TODO(port): IP is undefined in Fortran when MOD is not 1/2; taken as 0 here
    rout = ''   # CHARACTER ROUT*20
    if mod == 1:
        ip = iter - 1
        rout = '     FORMAL SOLUTION'
    elif mod == 2:
        ip = iter
        rout = '       LINEARIZATION'
    # 600 FORMAT(2I4,2F11.2,2X,A20)
    _auto_unit(69)  # unit 69 not explicitly OPENed (preconnected)
    write_line(69, '%4d%4d%11.2f%11.2f  %-20s' % (ip, mod, time_, dt, rout))
    return


# ---------------------------------------------------------------------

def quit(text, i1, i2):
    """c
c     stops the program and writes a text
c
    Dummies are never modified -> no return (STOP -> SystemExit).
    Corresponds to tlusty208.f lines 29946-29955"""
    # 10 format(1x,a,2x,2i10)
    print(' %s  %10d%10d' % (text, i1, i2))
    _auto_unit(10)
    write_line(10, ' %s  %10d%10d' % (text, i1, i2))
    raise SystemExit  # STOP


# ---------------------------------------------------------------------

def odfset():
    """C     =================
C
C     Initialization of line ODF's
C
    Corresponds to tlusty208.f lines 29961-30184"""
    # COMMON/STFCR/OFR(MFODF),OW(MFODF),OWSUB(MFODF),
    #         ODFL0(MDODF,MFODF),ODF2(MDEPTH),IFTRA(MTRANS),
    #         IDODF(MDODF),NDODF  -- canonical name; see INLINE_COMMONS.md
    dml = np.zeros(MDEPTH + 1)  # DIMENSION DML(MDEPTH)
    idstd = idiv(C.ND * 2, 3)  # Fortran integer division ND*2/3
    nlaste = C.NFREQ
    itr0 = 0
    for id in range(1, C.ND + 1):
        if C.DM[id] > 0:
            dml[id] = math.log(C.DM[id])
        else:
            dml[id] = id
    if1 = 0  # TODO(port): IF1 is always set to 1 before the first record enters the ITR==ITR0 branch;
    # initialized to 0 here to avoid an undefined Fortran value
    for ion in range(1, C.NION + 1):  # DO 500 ION=1,NION
        ind = C.INODF1[ion]
        if ind <= 0:
            continue  # GO TO 500
        ind2 = C.INODF2[ion]
        if not feq(C.FIODF1[ion], ' '):
            open_unit(ind, C.FIODF1[ion], 'r')  # STATUS='OLD'
        if not feq(C.FIODF2[ion], ' '):
            open_unit(ind2, C.FIODF2[ion], 'r')  # STATUS='OLD'
        # READ(IND,*,END=500) NDODF
        try:
            C.NDODF = int(_ldread(ind, 1)[0])
        except (EOFError, ValueError, IndexError):
            continue  # END=500
        if C.NDODF > MDODF:
            quit('too many depths for an ODF - ndodf.gt.mdodf', C.NDODF, MDODF)
        # READ(IND,*) (IDODF(ID),ID=1,NDODF)
        _v = _ldread(ind, C.NDODF)
        for id in range(1, C.NDODF + 1):
            C.IDODF[id] = int(_v[id - 1])
        irec = 0  # unused afterwards; kept
        while True:  # label 10: read record by record
            # READ(IND,*,END=500) II,JJ,FR,NFRO,FAV
            try:
                _v = _ldread(ind, 5)
            except (EOFError, ValueError, IndexError):
                break  # END=500 -> next ION
            ii = int(_v[0])
            jj = int(_v[1])
            fr = _v[2]  # unused afterwards; kept
            nfro = int(_v[3])
            fav = _v[4]
            if nfro > MFODF:
                quit('too many frequencies for an ODF - nfro.gt.mfodf', nfro, MFODF)
            for ij in range(1, nfro + 1):
                # READ(IND,*) OFR(IJ),OW(IJ),OWSUB(IJ)
                _v = _ldread(ind, 3)
                C.OFR[ij] = _v[0]
                C.OW[ij] = _v[1]
                C.OWSUB[ij] = _v[2]
            ind2 = C.INODF2[ion]
            # READ(IND2,*) ((ODFL0(ID,IF),ID=1,NDODF),IF=1,NFRO)
            _v = _ldread(ind2, C.NDODF * nfro)
            _k = 0
            for if_ in range(1, nfro + 1):
                for id in range(1, C.NDODF + 1):
                    C.ODFL0[id, if_] = _v[_k]
                    _k += 1
            irec = irec + 1
            n0 = C.NFIRST[ion] - 1
            i = ii + n0
            j = jj + n0
            if j > C.NLAST[ion]:
                continue  # GO TO 10
            if i >= C.NLAST[ion]:
                break  # GO TO 500 -> next ION
            itr = C.ITRA[i, j]
            if itr == itr0:
                itr1 = 0
                if if1 == 1:
                    ifij = 0
                    for it in range(1, C.NTRANS + 1):  # DO 30
                        if C.ILOW[it] != i or C.IUP[it] != j:
                            continue  # GO TO 30
                        if it == itr:
                            continue  # GO TO 30
                        ifij = ifij + 1
                        C.IFTRA[it] = ifij
                    if1 = 0
                for it in range(1, C.NTRANS + 1):
                    if C.IFTRA[it] > 0:
                        itr1 = it
                        break  # GO TO 50
                # 50 CONTINUE
                if itr1 == 0:
                    # 601 FORMAT(' CONFLICT IN ODF INPUT; ITR=',4I5)
                    print(' CONFLICT IN ODF INPUT; ITR=%5d%5d%5d%5d' % (itr, n0, ii, jj))
                    raise SystemExit  # STOP
                itr = itr1
                C.IFTRA[itr] = 0
                C.OSC0[itr] = fav
            else:
                itr0 = itr
                if1 = 1
                C.OSC0[itr] = fav
            mode = abs(C.INDEXP[itr])
            if mode == 3 or mode == 4:
                C.LCOMP[itr] = False
                C.INTMOD[itr] = 5
            ifrq0 = C.IFR0[itr]
            ifrq1 = C.IFR1[itr]
            if C.OFR[1] >= C.OFR[nfro]:
                if mode == 3:
                    C.IFR0[itr] = nlaste + 1
                    C.IFR1[itr] = nlaste + nfro
                    for ij in range(1, nfro + 1):
                        C.FREQ[ij + nlaste] = C.OFR[ij]
                        C.W[ij + nlaste] = C.OW[ij]
                    if C.NDODF == 1:
                        for id in range(1, C.ND + 1):
                            for ij in range(1, nfro + 1):
                                C.PRFLIN[id, ij + nlaste] = float(C.ODFL0[1, ij])
                    else:
                        for id in range(1, C.ND + 1):
                            id1 = 1
                            # TODO(port): if the loop below finds no match, ID2 is undefined in Fortran;
                            # here taken as NDODF+1 so the subsequent clamping statement changes it to NDODF
                            id2 = C.NDODF + 1
                            for ido in range(1, C.NDODF):  # DO IDO=1,NDODF-1
                                if id >= C.IDODF[ido] and id <= C.IDODF[ido + 1]:
                                    id1 = ido
                                    id2 = ido + 1
                                    break  # GO TO 140
                            # 140 CONTINUE
                            if id2 > C.NDODF:
                                id2 = C.NDODF
                            if id1 == id2:
                                a1 = 1.0
                                a2 = 0.0
                            else:
                                x = dml[C.IDODF[id2]] - dml[C.IDODF[id1]]
                                a1 = (dml[C.IDODF[id2]] - dml[id]) / x
                                a2 = UN - a1
                            for ij in range(1, nfro + 1):
                                if C.ODFL0[id1, ij] <= 0 or C.ODFL0[id2, ij] <= 0:
                                    C.PRFLIN[id, ij + nlaste] = 0.0
                                else:
                                    x = math.exp(a1 * math.log(C.ODFL0[id1, ij])
                                                 + a2 * math.log(C.ODFL0[id2, ij]))
                                    C.PRFLIN[id, ij + nlaste] = float(x)
                    if C.IPROF[itr] == 0:
                        for id in range(1, C.ND + 1):
                            C.PRFLIN[id, C.IFR1[itr]] = 0.0
                    for ij in range(1, nfro + 1):
                        C.PROF[ij + nlaste] = C.PRFLIN[idstd, ij + nlaste]
                    nlaste = C.IFR1[itr]
            else:
                if mode == 3:
                    C.IFR0[itr] = nlaste + 1
                    C.IFR1[itr] = nlaste + nfro
                    for ij in range(1, nfro + 1):
                        C.FREQ[ij + nlaste] = C.OFR[nfro - ij + 1]
                        C.W[ij + nlaste] = C.OW[nfro - ij + 1]
                    if C.NDODF == 1:
                        for id in range(1, C.ND + 1):
                            for ij in range(1, nfro + 1):
                                C.PRFLIN[id, ij + nlaste] = float(C.ODFL0[1, nfro - ij + 1])
                    else:
                        for id in range(1, C.ND + 1):
                            id1 = 1
                            # TODO(port): as above; if no match, ID2 is undefined in Fortran
                            id2 = C.NDODF + 1
                            for ido in range(1, C.NDODF):  # DO IDO=1,NDODF-1
                                if id >= C.IDODF[ido] and id <= C.IDODF[ido + 1]:
                                    id1 = ido
                                    id2 = ido + 1
                                    break  # GO TO 240
                            # 240 CONTINUE
                            if id2 > C.NDODF:
                                id2 = C.NDODF
                            if id1 == id2:
                                a1 = 1.0
                                a2 = 0.0
                            else:
                                x = dml[C.IDODF[id2]] - dml[C.IDODF[id1]]
                                a1 = (dml[C.IDODF[id2]] - dml[id]) / x
                                a2 = UN - a1
                            for ij in range(1, nfro + 1):
                                ij0 = nfro - ij + 1
                                if C.ODFL0[id1, ij0] <= 0 or C.ODFL0[id2, ij0] <= 0:
                                    C.PRFLIN[id, ij + nlaste] = 0.0
                                else:
                                    x = math.exp(a1 * math.log(C.ODFL0[id1, ij0])
                                                 + a2 * math.log(C.ODFL0[id2, ij0]))
                                    C.PRFLIN[id, ij + nlaste] = float(x)
                    if C.IPROF[itr] == 0:
                        for id in range(1, C.ND + 1):
                            C.PRFLIN[id, C.IFR0[itr]] = 0.0
                    for ij in range(1, nfro + 1):
                        C.PROF[ij + nlaste] = C.PRFLIN[idstd, ij + nlaste]
                    nlaste = C.IFR1[itr]
            if nlaste > MFREQ:
                quit(' too many frequencies in ODFSET - nlaste.gt.mfreq', nlaste, MFREQ)
            if C.INDEXP[itr] != 0:
                # IJALIS assigns scalar dummy IFRQ1 -> unpack all scalar dummies
                itr, ifrq0, ifrq1 = ijalis(itr, ifrq0, ifrq1)
            # GO TO 10
    # 500 CONTINUE
    C.NFREQ = nlaste
    return


# ---------------------------------------------------------------------

def odfhys(dopo):
    """C     =======================
C
C     Initialization of line ODF's for hydrogen
C
    Dummy DOPO is never modified -> no return.
    Corresponds to tlusty208.f lines 30190-30325"""
    # PARAMETER (CCM=UN/2.997925D10,THIRD=UN/3.,FRH=3.28805D15)
    CCM = UN / 2.997925e10
    THIRD = UN / 3.0
    FRH = 3.28805e15
    ffro = np.zeros(MFRO + 1)  # DIMENSION FFRO(MFRO)
    izzh = 1
    if C.ISPODF >= 1:
        for itr in range(1, C.NTRANS + 1):  # DO 200
            jnd = C.JNDODF[itr]
            mode = abs(C.INDEXP[itr])
            if jnd <= 0 or mode != 2:
                continue  # GO TO 200
            C.LINEXP[itr] = False
            C.LCOMP[itr] = False
            C.INTMOD[itr] = 6
            i = C.ILOW[itr]
            j = C.IUP[itr]
            C.NQLODF[i] = abs(C.IPROF[itr])
            if C.NQLODF[i] == 0:
                C.NQLODF[i] = C.NQUANT[j]
            C.OSC0[itr] = 0.0
            is_l = C.NQUANT[i]  # originally named IS, renamed to avoid the Python keyword is
            for k in range(C.NQUANT[j], NLMX + 1):
                # STARK0 assigns scalar dummies XKIJ,WL0,FIJ -> unpack all scalar dummies
                is_l, k, izzh, C.XKIJ[jnd, k], C.WL0[jnd, k], C.FIJ[jnd, k] = stark0(
                    is_l, k, izzh, C.XKIJ[jnd, k], C.WL0[jnd, k], C.FIJ[jnd, k])
                C.OSC0[itr] = C.OSC0[itr] + C.FIJ[jnd, k]
        return
    nlaste = C.NFREQ
    for itr in range(1, C.NTRANS + 1):  # DO 100
        jnd = C.JNDODF[itr]
        mode = abs(C.INDEXP[itr])
        if jnd <= 0 or mode != 2:
            continue  # GO TO 100
        C.LCOMP[itr] = False
        C.INTMOD[itr] = 6
        i = C.ILOW[itr]
        j = C.IUP[itr]
        C.NQLODF[i] = abs(C.IPROF[itr])
        if C.NQLODF[i] == 0:
            C.NQLODF[i] = C.NQUANT[j]
        xj2a = HALF * (C.XI2[C.NQUANT[j]] + C.XI2[C.NQUANT[j] - 1])
        # set up explicit frequencies & weights
        nfro = 0
        for ifq in range(1, 5):
            nfro = nfro + C.KDO[ifq, jnd]
        nfro = nfro - 2
        frion = FRH * C.IZ[C.IEL[i]] * C.IZ[C.IEL[i]]
        fra = frion * (C.XI2[C.NQUANT[i]] - xj2a)
        dopi = dopo * fra * CCM
        frb = 0.99999999 * frion * C.XI2[C.NQUANT[i]]
        ifrq0 = C.IFR0[itr]
        ifrq1 = C.IFR1[itr]
        C.IFR0[itr] = nlaste + 1
        C.IFR1[itr] = nlaste + nfro
        C.I1ODF[i] = C.IFR0[itr]
        C.I2ODF[i] = C.IFR1[itr] - 1
        ffro[1] = 0.99999999 * fra
        ffro[2] = fra
        ij00 = 1
        for ik in range(1, 4):
            for ij in range(2, C.KDO[ik, jnd] + 1):
                ijq = ij00 + ij
                ffro[ijq] = ffro[ijq - 1] + C.XDO[ik, jnd] * dopi
            ij00 = ij00 + C.KDO[ik, jnd] - 1
        nfrb = 0  # TODO(port): if no FFRO<FRB in the loop below, NFRB is undefined in Fortran; taken as 0
        for ij in range(1, ij00 + 1):
            if ffro[ij] < frb:
                nfrb = ij
        if nfrb == ij00:
            ij00 = ij00 + 1
            ffro[nfro] = 0.99999999 * frion * C.XI2[C.NQUANT[i]]
            while ffro[ij00] >= ffro[nfro]:  # do while
                C.XDO[3, jnd] = 0.75 * C.XDO[3, jnd]
                ij00 = ij00 - C.KDO[3, jnd]
                for ij in range(2, C.KDO[3, jnd] + 1):
                    ijq = ij00 + ij
                    ffro[ijq] = ffro[ijq - 1] + C.XDO[3, jnd] * dopi
                ij00 = ij00 + C.KDO[3, jnd]
            tido = (ffro[nfro] - ffro[ij00]) / float(C.KDO[4, jnd] - 1)
            for ij in range(1, C.KDO[4, jnd] - 1):  # DO IJ=1,KDO(4,JND)-2
                ijq = nfro - ij
                ffro[ijq] = ffro[nfro] - float(ij) * tido
        else:
            tido = (frb - ffro[nfrb]) * THIRD
            ffro[nfrb + 1] = ffro[nfrb] + tido
            ffro[nfrb + 2] = frb - tido
            ffro[nfrb + 3] = frb
            nfro = nfrb + 3
            C.IFR1[itr] = nlaste + nfro
            C.I2ODF[i] = C.IFR1[itr] - 1
        for ij in range(1, nfro + 1):
            C.FREQ[nlaste + ij] = ffro[nfro - ij + 1]
        C.W[nlaste + nfro] = HALF * (C.FREQ[nlaste + nfro - 1] - C.FREQ[nlaste + nfro])
        C.W[nlaste + nfro - 1] = C.W[nlaste + nfro]
        for ij in range(2, nfro - 1, 2):  # DO IJ=2,NFRO-2,2
            tido = (C.FREQ[nlaste + ij] - C.FREQ[nlaste + ij + 1]) * THIRD
            C.W[nlaste + ij - 1] = C.W[nlaste + ij - 1] + tido
            C.W[nlaste + ij] = C.W[nlaste + ij] + 4.0 * tido
            C.W[nlaste + ij + 1] = C.W[nlaste + ij + 1] + tido
        nlaste = C.IFR1[itr]
        # set up internal frequencies & Stark parameters
        odffr(i, j)
        C.OSC0[itr] = 0.0
        is_l = C.NQUANT[i]  # originally named IS, renamed to avoid the Python keyword
        for k in range(C.NQUANT[j], NLMX + 1):
            is_l, k, izzh, C.XKIJ[jnd, k], C.WL0[jnd, k], C.FIJ[jnd, k] = stark0(
                is_l, k, izzh, C.XKIJ[jnd, k], C.WL0[jnd, k], C.FIJ[jnd, k])
            C.OSC0[itr] = C.OSC0[itr] + C.FIJ[jnd, k]
        if C.INDEXP[itr] != 0:
            itr, ifrq0, ifrq1 = ijalis(itr, ifrq0, ifrq1)
    # 100 CONTINUE
    C.NFREQ = nlaste
    return


# ---------------------------------------------------------------------

def odfmer():
    """C     =================
C
C     Opacity distribution function for superlines to merged states
C     (calculated only if DT/T>=CHTL, kept constant after).
C
    Corresponds to tlusty208.f lines 30331-30352"""
    CHTL = 1.0e-3  # PARAMETER
    for itr in range(1, C.NTRANS + 1):  # DO 10
        if not C.LINE[itr] or abs(C.INDEXP[itr]) != 2:
            continue  # GO TO 10
        for id in range(1, C.ND + 1):
            if C.INIT == 1 or abs(C.CHANT[id]) >= CHTL:
                odfhyd(id, itr)  # ODFHYD does not modify scalar dummies
    return


# ---------------------------------------------------------------------

def odfhyd(id, itr):
    """C     =========================
C
C     Line ODF's for hydrogen line series
C
    Dummies ID,ITR are never modified -> no return.
    Corresponds to tlusty208.f lines 30359-30454"""
    # PARAMETER (CDOP=TWO*BOLK/HMASS)
    CDOP = TWO * BOLK / HMASS
    # PARAMETER (CA=2.997925D18,CCM=CA/1.D8,FRH=3.28805D15)
    CA = 2.997925e18
    CCM = CA / 1.0e8
    FRH = 3.28805e15
    # PARAMETER (RYDEL=911.764,TTW=2./3.)
    RYDEL = 911.764
    TTW = 2.0 / 3.0
    # PARAMETER (C00=1.25D-9,CID=0.02654)
    C00 = 1.25e-9
    CID = 0.02654
    # DIMENSION SIG,Sgt,ODF(MFRO),IODF(MFRO),YNUS(MFRO),ALAM(MFRO)
    sig = np.zeros(MFRO + 1)
    sgt = np.zeros(MFRO + 1)
    odf = np.zeros(MFRO + 1)
    iodf = np.zeros(MFRO + 1, dtype=np.int64)
    ynus = np.zeros(MFRO + 1)
    alam = np.zeros(MFRO + 1)
    jo = C.JNDODF[itr]
    if C.ISPODF == 0:
        nf = C.NFRODF[jo]
        for ij in range(1, nf + 1):
            iodf[ij] = 0
            sig[ij] = 0.0
