    ir = n
    while True:  # label 10
        if m > 1:
            m = m - 1
            indxt = indx[m]
            q = arrin[indxt]
        else:
            indxt = indx[ir]
            q = arrin[indxt]
            indx[ir] = indx[1]
            ir = ir - 1
            if ir == 1:
                indx[1] = indxt
                return
        i = m
        j = m + m
        while j <= ir:  # IF/GO TO 20 loop of label 20
            if j < ir:
                if arrin[indx[j]] < arrin[indx[j + 1]]:
                    j = j + 1
            if q < arrin[indx[j]]:
                indx[i] = indx[j]
                i = j
                j = j + j
            else:
                j = ir + 1
            # GO TO 20
        indx[i] = indxt
        # GO TO 10


