def irc(n, t, ic, rno, se):
    """IRC CALCULATES THE EXCITATION RATE, SE [cm**3/s], FOR IONIZATION
    OF HYDROGEN ATOMS FROM STATE N DUE TO ELECTRON COLLISIONS, ASSUMING
    THE CONTINUUM STARTS AT LEVEL RNO.
    REF. JOHNSON (1972)

    a modification of Tim Kallman's XSTAR routine

    Corresponds to tlusty208.f lines 37884-37931 (SUBROUTINE IRC)
    Modifies scalar dummy SE → returns all scalar dummies (n, t, ic, rno, se)
    """
    if ic != 1:                          # MAB
        # CALL SZIRC(N,T,IC,rno,SE): SZIRC modifies scalar dummy cii → unpack the return
        n, t, ic, rno, se = szirc(n, t, ic, rno, se)
        return n, t, ic, rno, se

    xo = 1.0 - n * n / rno / rno
    yn = xo * 157803.0 / (t * n * n)
    if n <= 1:
        an = 1.9603 * n * (1.133 / 3.0 / xo ** 3 - 0.4059 / 4.0 / xo ** 4 +
                           0.07014 / 5.0 / xo ** 5)
        bn = 2.0 / 3.0 * n * n / xo * (3.0 + 2.0 / xo - 0.603 / xo / xo)
        rn = 0.45
    elif n == 2:
        an = 1.9603 * n * (1.0785 / 3.0 / xo ** 3 - 0.2319 / 4.0 / xo ** 4 +
                           0.02947 / 5.0 / xo ** 5)
        bn = (4.0 - 18.63 / n + 36.24 / (n * n) - 28.09 / (n * n * n)) / n
        bn = 2.0 / 3.0 * n * n / xo * (3.0 + 2.0 / xo + bn / xo / xo)
        rn = 0.653
    else:
        g0 = (0.9935 + 0.2328 / n - 0.1296 / (n * n)) / 3.0 / xo ** 3
        g1 = -(0.6282 - 0.5598 / n + 0.5299 / (n * n)) / (n * 4.0) / xo ** 4
        g2 = (0.3887 - 1.181 / n + 1.470 / (n * n)) / (n * n * 5.0) / xo ** 5
        an = 1.9603 * n * (g0 + g1 + g2)
        bn = (4.0 - 18.63 / n + 36.24 / (n * n) - 28.09 / (n * n * n)) / n
        bn = (3.0 + 2.0 / xo + bn / xo / xo) * 2.0 * n * n / 3.0 / xo
        rn = 1.94 * n ** (-1.57)

    rn = rn * xo
    zn = rn + yn
    # CALL EXPINX(YN,EY): EXPINX modifies scalar dummy em1 → unpack the return;
    # the second actual argument 0.0 is a placeholder initial value for output dummy EY (the Fortran incoming value is undefined)
    yn, ey = expinx(yn, 0.0)
    zn, ez = expinx(zn, 0.0)             # CALL EXPINX(ZN,EZ)
    se = an * (ey / yn / yn - math.exp(-rn) * ez / zn / zn)
    ey = 1.0 + 1.0 / yn - ey * (2.0 / yn + 1.0)
    ez = math.exp(-rn) * (1.0 + 1.0 / zn - ez * (2.0 / zn + 1.0))
    se = se + (bn - an * math.log(2.0 * n * n / xo)) * (ey - ez)
    se = se * math.sqrt(t) * yn * yn * n * n * 1.095e-10 / xo
    return n, t, ic, rno, se


