def comset():
    """sets up necessary parameters for treating the Compton scattering

    Corresponds to tlusty208.f lines 38051-38214 (SUBROUTINE COMSET)
    """
    XCON = 8.0935e-21            # parameter (xcon=8.0935d-21,YCON=1.68638E-10)
    YCON = 1.68638e-10
    T15 = 1.0e-15                # parameter (t15=1.d-15)
    # local arrays freqi(mfreq), PL(MDEPTH), PLM(MDEPTH)
    freqi = np.zeros(MFREQ + 1)
    pl = np.zeros(MDEPTH + 1)
    plm = np.zeros(MDEPTH + 1)
    # common/auxcbc/, common/comgfs/ declared but unused in this body (variables live in commons.py: C.cden1m etc.)

    # if(icompt.le.0) go to 100
    if C.icompt > 0:
        C.nmuc = 3
        C.nsti = 0
        C.nedd = 3

        # frequency-dependent universal parameters
        for ij in range(1, C.NFREQ + 1):
            C.CDER10[ij] = 0.0
            C.CDER1P[ij] = 0.0
            C.CDER1M[ij] = 0.0
            C.CDER20[ij] = 0.0
            C.CDER2P[ij] = 0.0
            C.CDER2M[ij] = 0.0
            iji = C.NFREQ - C.KIJ[ij] + 1
            C.ijorig[iji] = ij
            freqi[iji] = C.FREQ[ij]
            fr = freqi[iji]
            C.BNUS[iji] = TWO * XCON * fr / (BN * (fr * 1.0e-15) ** 3)

        ij = 1
        C.DLNFR[ij] = math.log(freqi[ij + 1] / freqi[ij])
        for ij in range(2, C.NFREQ):       # 2..nfreq-1
            C.DLNFR[ij] = math.log(freqi[ij + 1] / freqi[ij])
            delp = C.DLNFR[ij]
            delm = C.DLNFR[ij - 1]
            del0 = delp + delm
            cd0 = TWO / del0
            C.CDER2M[ij] = cd0 / delm
            C.CDER2P[ij] = cd0 / delp
            C.CDER20[ij] = -C.CDER2M[ij] - C.CDER2P[ij]

        for ij in range(1, C.NFREQ):       # 1..nfreq-1
            frj0 = freqi[ij]
            frjp = freqi[ij + 1]
            frz = math.sqrt(frj0 * frjp)
            for id in range(1, C.ND + 1):
                # to avoid over/underflow problems:
                if HK * frj0 / C.TEMP[id] < 200.0:
                    fjb0 = UN / (math.exp(HK * frj0 / C.TEMP[id]) - UN)
                else:
                    fjb0 = 0.0
                if HK * frjp / C.TEMP[id] < 200.0:
                    fjbp = UN / (math.exp(HK * frjp / C.TEMP[id]) - UN)
                else:
                    fjbp = 0.0
                fjz0 = fjb0 * (BN * (frj0 * T15) ** 3)
                fjzp = fjbp * (BN * (frjp * T15) ** 3)
                if C.ichcoo == 0:
                    zj0 = HK * frz / C.TEMP[id]
                    dfjz = fjz0 - fjzp
                    dfjb = fjb0 - fjbp
                    fzz = UN + fjbp - 3.0 / zj0
                    aa = dfjz * dfjb
                    bb = dfjz * fzz + fjzp * dfjb
                    cc = fjzp * fzz - dfjz / C.DLNFR[ij] / zj0
                else:
                    e2 = YCON * C.TEMP[id]
                    zxxp = XCON * frjp * (UN + fjbp) - 3.0 * e2
                    zxx0 = XCON * frj0 * (UN + fjb0) - 3.0 * e2
                    dzxx = zxx0 - zxxp
                    dfjb = fjb0 - fjbp
                    dfjz = fjz0 - fjzp
                    aa = dfjz * dzxx
                    bb = dfjz * zxxp + fjzp * dzxx
                    cc = fjzp * zxxp - e2 * dfjz / C.DLNFR[ij]
                # XXX  to avoid division by zero:
                if abs(aa) == 0 and abs(bb) == 0.0:
                    xx1 = 0.0
                elif abs(aa) < 1.0e-7 * abs(bb):
                    xx1 = -cc / bb
                else:
                    dd = bb * bb - 4.0 * aa * cc
                    if dd < 0.0:
                        dd = 0.0
                    dd = math.sqrt(dd)
                    xx1 = (dd - bb) * HALF / aa
                    if C.ichcoo > 0:
                        xx2 = -(dd + bb) * HALF / aa
                        dxx1 = abs(xx1 - HALF)
                        dxx2 = abs(xx2 - HALF)
                        if dxx2 < dxx1:
                            xx1 = xx2
                        if xx1 > 1.0 or xx1 < 0.0:
                            xx1 = HALF
                C.DELJ[ij, id] = xx1

        # angle-dependent universal parameters
        angset()                   # call angset

    # label 100: frequency-dependent universal parameters (always executed)
    for ij in range(1, C.NFREQ + 1):
        # first-order expression
        if C.knish == 0:
            C.SIGEC[ij] = SIGE * (UN - TWO * C.FREQ[ij] * XCON)
        # Use full Klein-Nishina cross section (Rybicki & Lightman 1975):
        else:
            xf = XCON * C.FREQ[ij]
            if xf < 1.0e-1:
                C.SIGEC[ij] = SIGE * (1.0 - xf * (2.0 - xf * (26.0 / 5.0 - xf *
                    (13.3 - xf * (1144.0 / 35.0 - xf * (544.0 / 7.0 - xf *
                    (3784.0 / 21.0 - xf * (6148.0 / 15.0 - xf * (151552.0 / 165.0 -
                    xf * 111872.0 / 55.0)))))))))
            elif xf > 1.0e3:
                C.SIGEC[ij] = SIGE * 3.0 / 8.0 / xf * (math.log(2.0 * xf) + 0.5)
            else:
                C.SIGEC[ij] = SIGE * 0.75 * ((1.0 + xf) / xf ** 3 *
                    (2.0 * xf * (1.0 + xf) / (1.0 + 2.0 * xf) -
                     math.log(1.0 + 2.0 * xf)) +
                    0.5 * math.log(1.0 + 2.0 * xf) / xf -
                    (1.0 + 3.0 * xf) / (1.0 + 2.0 * xf) ** 2)

    if C.icompt <= 0:
        return
    ij = 1
    ijo = C.ijorig[ij]
    for id in range(1, C.ND + 1):
        plm[id] = C.BNUE[ijo] / (math.exp(HK / C.TEMP[id] * C.FREQ[ijo]) - UN)

    for ij in range(2, C.NFREQ + 1):
        ijo = C.ijorig[ij]
        for id in range(1, C.ND + 1):
            # to avoid over/underflow problems:
            if HK / C.TEMP[id] * C.FREQ[ijo] < 200.0:
                pl[id] = C.BNUE[ijo] / (math.exp(HK / C.TEMP[id] * C.FREQ[ijo]) - UN)
            else:
                pl[id] = plm[id]
            plm[id] = pl[id]
    return


# ======================================================================

def angset():
    """sets up angles points and angle-dependent quantities for treating
    the Compton scattering

    Corresponds to tlusty208.f lines 38221-38264 (subroutine angset)
    """
    THREE = 3.0                  # parameter(three=3.d0, five=5.d0, zero=0.d0, tr16=3.d0/16.d0)
    FIVE = 5.0
    ZERO = 0.0
    TR16 = 3.0 / 16.0
    # local arrays amu0(mmuc), wtmu0(mmuc)
    amu0 = np.zeros(MMUC + 1)
    wtmu0 = np.zeros(MMUC + 1)

    # amu=cos(angle between line of sight and normal to slab) grid and
    # gauss-legendre integration weights for the interval mu=[0,1]
    gauleg(ZERO, UN, amu0, wtmu0, C.nmuc, MMUC)  # GAULEG does not modify scalar dummies

    for i in range(1, C.nmuc + 1):
        C.amuc[i] = -amu0[C.nmuc - i + 1]
        C.amuc[i + C.nmuc] = amu0[i]
        C.wtmuc[i] = wtmu0[C.nmuc - i + 1]
        C.wtmuc[i + C.nmuc] = wtmu0[i]
    C.nmuc = 2 * C.nmuc

    for i in range(1, C.nmuc + 1):
        C.amuc1[i] = C.amuc[i] * C.wtmuc[i]
        C.amuc2[i] = C.amuc[i] * C.amuc[i] * C.wtmuc[i]
        C.amuc3[i] = C.amuc[i] * C.amuc[i] * C.amuc[i] * C.wtmuc[i]
        a1 = C.amuc[i]
        a2 = a1 * a1
        a3 = a1 * a2
        for i1 in range(1, C.nmuc + 1):
            b1 = C.amuc[i1]
            b2 = b1 * b1
            b3 = b1 * b2
            trw = TR16 * C.wtmuc[i1]
            C.calph[i, i1] = (THREE * a2 * b2 - a2 - b2 + THREE) * trw
            C.cbeta[i, i1] = (FIVE * (a1 * b1 + a3 * b3) -
                              THREE * (a3 * b1 + a1 * b3)) * trw
            C.cgamm[i, i1] = a1 * b1 * trw
    return


