def rte_sc(dtau, st0, rup, rdown, amu0, ri, ali):
    """formal solver of the radiative transfer equation
    for one frequency, angle, and for completely known source function;
    using short characteristics

    input:    dtau - optical depth increments Delta tau
              st0  - total source function
              rup  - intensity at the upper boundary (id=1)
              rdown- intensity at the lower boundary (id=nd)
              amu0 - cosine of angle of propagation (wrt. the normal)
    output:   ri   - radiation intensity

    Corresponds to tlusty208.f lines 38312-38364 (subroutine rte_sc)
    Does not modify scalar dummies -> no return
    """
    # local arrays dtx1/dtx2/dtx0(mdepth)
    dtx1 = np.zeros(MDEPTH + 1)
    dtx2 = np.zeros(MDEPTH + 1)
    dtx0 = np.zeros(MDEPTH + 1)

    for id in range(1, C.ND):            # 1..nd-1
        dtx1[id] = math.exp(-dtau[id])
        dtx2[id] = (UN - dtx1[id]) / dtau[id]
        dtx0[id] = UN - dtx2[id]

    # incoming intensity
    if amu0 < 0:
        id = 1
        ri[id] = rup
        for id in range(1, C.ND):        # 1..nd-1
            ri[id + 1] = ri[id] * dtx1[id] + st0[id] * (dtx2[id] - dtx1[id]) + \
                st0[id + 1] * dtx0[id]
            ali[id + 1] = dtx0[id]
        ali[1] = 0.0
    # outgoing intensity
    else:
        ri[C.ND] = rdown
        for id in range(C.ND - 1, 0, -1):    # nd-1..1
            ri[id] = ri[id + 1] * dtx1[id] + st0[id] * dtx0[id] + \
                st0[id + 1] * (dtx2[id] - dtx1[id])
            ali[id] = dtx0[id]
        ali[C.ND] = 0.0
    return


