def rtesol(dtau, st0, rup, rdown, amu0, ri, ali):
    """formal solver of the radiative transfer equation
    for one frequency, angle, and for completely known source function;
    by the Discontinuous Finite Element method
    Castor, Dykema, Klein, 1992, ApJ 387, 561.

    Corresponds to tlusty208.f lines 38371-38457 (subroutine rtesol)
    Does not modify scalar dummies -> no return
    """
    ONE = 1.0                    # parameter (one=1.d0)
    # local arrays rim/rip/aim/aip(mdepth)
    rim = np.zeros(MDEPTH + 1)
    rip = np.zeros(MDEPTH + 1)
    aim = np.zeros(MDEPTH + 1)
    aip = np.zeros(MDEPTH + 1)

    # incoming intensity
    if amu0 < 0:
        id = 1
        rip[id] = rup
        dt0 = dtau[id]
        dtaup1 = dt0 + ONE
        dtau2 = dt0 * dt0
        bb = TWO * dtaup1
        cc = dt0 * dtaup1
        aa = dtau2 + bb
        rim[id] = (aa * rip[id] - cc * st0[id] + dt0 * st0[id + 1]) / bb
        for id in range(1, C.ND):        # 1..nd-1
            dt0 = dtau[id]
            dtaup1 = dt0 + ONE
            dtau2 = dt0 * dt0
            bb = TWO * dtaup1
            cc = dt0 * dtaup1
            aa = dtau2 + bb
            rim[id + 1] = (TWO * rim[id] + dt0 * st0[id] + cc * st0[id + 1]) / aa
            rip[id] = (bb * rim[id] + cc * st0[id] - dt0 * st0[id + 1]) / aa
            aim[id + 1] = cc / aa
            aip[id] = (cc + bb * aim[id]) / aa
        for id in range(2, C.ND):        # 2..nd-1
            dtt = UN / (dtau[id - 1] + dtau[id])
            ri[id] = (rim[id] * dtau[id] + rip[id] * dtau[id - 1]) * dtt
            ali[id] = (aim[id] * dtau[id] + aip[id] * dtau[id - 1]) * dtt
        ri[1] = rip[1]
        ri[C.ND] = rim[C.ND]
        ali[1] = aim[1]
        ali[C.ND] = aim[C.ND]
    # outgoing intensity
    else:
        rip[C.ND] = rdown
        id = C.ND - 1
        dt0 = dtau[id]
        dtaup1 = dt0 + ONE
        dtau2 = dt0 * dt0
        bb = TWO * dtaup1
        cc = dt0 * dtaup1
        aa = dtau2 + bb
        rim[id + 1] = (aa * rip[id + 1] - cc * st0[id + 1] + dt0 * st0[id]) / bb
        for id in range(C.ND - 1, 0, -1):    # nd-1..1
            dt0 = dtau[id]
            dtaup1 = dt0 + ONE
            dtau2 = dt0 * dt0
            bb = TWO * dtaup1
            cc = dt0 * dtaup1
            aa = dtau2 + bb
            rim[id] = (TWO * rim[id + 1] + dt0 * st0[id + 1] + cc * st0[id]) / aa
            rip[id + 1] = (bb * rim[id + 1] + cc * st0[id + 1] - dt0 * st0[id]) / aa
            aim[id] = cc / aa
            aip[id + 1] = (cc + bb * aim[id + 1]) / aa
        for id in range(2, C.ND):        # 2..nd-1
            dtt = UN / (dtau[id - 1] + dtau[id])
            ri[id] = (rim[id] * dtau[id - 1] + rip[id] * dtau[id]) * dtt
            ali[id] = (aim[id] * dtau[id - 1] + aip[id] * dtau[id]) * dtt
        ri[1] = rim[1]
        ri[C.ND] = rip[C.ND]
        ali[1] = aim[1]
        ali[C.ND] = aim[C.ND]
    return


