def rtefe2(dtau, s, rup, rdown, ri):
    """formal solver of the radiative transfer equation
    for one frequency, angle, and for completely known source function;
    original Feautrier (second-order) scheme

    Corresponds to tlusty208.f lines 38463-38537 (subroutine rtefe2)
    Does not modify scalar dummies -> no return
    """
    ONE = 1.0                    # parameter (one=1.d0)
    # local arrays a/b/c/d/f/v/z(mdepth)
    a = np.zeros(MDEPTH + 1)
    b = np.zeros(MDEPTH + 1)
    c = np.zeros(MDEPTH + 1)
    d = np.zeros(MDEPTH + 1)
    f = np.zeros(MDEPTH + 1)
    v = np.zeros(MDEPTH + 1)
    z = np.zeros(MDEPTH + 1)

    # set up the global tridiagonal matrix

    # upper boundary condition
    id = 1
    cc = TWO / dtau[id]
    c[id] = cc / dtau[id]
    b[id] = ONE + cc + c[id]
    a[id] = 0.0
    v[id] = s[id] + cc * rup

    # normal depth points
    for id in range(2, C.ND):            # 2..nd-1
        dtinv = TWO / (dtau[id - 1] + dtau[id])
        a[id] = dtinv / dtau[id - 1]
        c[id] = dtinv / dtau[id]
        b[id] = ONE + a[id] + c[id]
        v[id] = s[id]

    # lower boundary condition
    id = C.ND
    aa = TWO / dtau[id - 1]
    a[id] = aa / dtau[id - 1]
    b[id] = ONE + aa + a[id]
    if rdown == 0.0:
        b[id] = ONE + a[id]
    c[id] = 0.0
    v[id] = s[id] + aa * rdown

    # ---------------------------------------------------
    # solution by elimination
    # 1. forward sweep
    f[1] = (b[1] - c[1]) / c[1]
    d[1] = ONE / (ONE + f[1])
    z[1] = v[1] / b[1]

    # ii) normal depth points
    for id in range(2, C.ND):            # 2..nd-1
        f[id] = (b[id] - a[id] - c[id] + a[id] * f[id - 1] * d[id - 1]) / c[id]
        d[id] = ONE / (ONE + f[id])
        z[id] = (v[id] + a[id] * z[id - 1]) * d[id] / c[id]

    # iii) upper boundary (as the original comment says; actually the lower boundary id=nd)
    id = C.ND
    z[id] = (v[id] + a[id] * z[id - 1]) / (b[id] - a[id] * d[id - 1])

    # 2. backward elimination
    ri[C.ND] = z[C.ND]
    for id in range(C.ND - 1, 0, -1):    # nd-1..1
        ri[id] = ri[id + 1] * d[id] + z[id]
    return


