def tlocal(id, tauf, t):
    """local temperature as a a function of optical depth
    for a grey model

    input;   ID   - depth index
             TAUF - current estimate of the flux-mean opacity
    output:  T    - local temperature

    Corresponds to tlusty208.f lines 41596-41647.
    Modifies scalar dummy T; returns (id, tauf, t) per convention.
    """
    # parameter (c1=0.8112,c2=3.966e14,c3=6.745e-10,c4=0.96,
    #            c23=c2*c3,c34=c3*c4)
    c1 = 0.8112
    c2 = 3.966e14
    c3 = 6.745e-10
    c4 = 0.96
    c23 = c2 * c3  # c23 unused in the original code
    c34 = c3 * c4

    if C.TDISK > 0.0:
        t = C.TDISK
        return id, tauf, t

    vis = C.VISCD[id] / (3.0 * C.DM[C.ND])
    extra = 4.0 * C.FAK0 * C.WDIL * (C.TSTAR / C.TEFF)**4
    gj = C.GAMJ[id]
    gh = C.GAMH * 5.7735e-1
    gg = (tauf - C.TAUTHE[id]) * C.fractv + gh + extra

    if C.icompt == 0 or C.icomgr == 0:
        t = (0.75 * C.T4 * (gj * gg + vis / C.ABPLAD[id]))**0.25
        return id, tauf, t

    epsbar = C.ABPLAD[id] / C.ABROSD[id]
    tfor = c1 * C.TEFF * epsbar**(-0.125)
    tf0 = tfor  # tf0 unused in the original code
    # Fortran: if(tauf.gt.un.and.tfor.lt.temp(id).or.tauf.ge.100.)
    # (.AND. binds tighter than .OR., same as Python)
    if (tauf > UN and tfor < C.TEMP[id]) or tauf >= 100.0:
        tfor = 0.0
        b = gg * (c3 - c34)
        b = 0.0  # original code immediately sets b=0 (previous line is dead code; kept as literal translation)
    else:
        b = gg * c3
    a = epsbar / (0.75 * C.T4)
    c = gg * (epsbar * gj + c34 * tfor) + vis / C.ABROSD[id]
    t1 = 0.0  # initial value for output (QUARTC output)
    a, b, c, t1 = quartc(a, b, c, t1)
    t = t1

    return id, tauf, t


def quartc(a, b, c, x):
    """solver for the algebraic equation of the fourth order
    a*x**4 + b*x =c

    solution done by the Newton-Raphson method

    Initial estimate

    Corresponds to tlusty208.f lines 41655-41689.
    Modifies scalar dummy X; returns (a, b, c, x) per convention.
    """
    if a > b:
        x = (c / a)**0.25
    else:
        x = c / b

    it = 0
    dx = 0.0  # TODO(port): in the original, dx undefined when d==0 (stale value); use 0 here
    while True:
        # label 10
        it = it + 1
        ax = a * x**3
        v = c - b * x - x * ax
        d = 4.0 * ax + b
        if d != 0.0:
            dx = v / d
        x = x + dx
        if abs(dx / x) > 1.0e-3:
            if it < 20:
                continue  # GO TO 10
        else:
            if it >= 20:
                # 601 format(' slow convergence of quartic solver'/
                #            ' a,b,c,dx,x = ',1p5e13.4)
                print(' slow convergence of quartic solver')
                print(' a,b,c,dx,x = ',
                      f'{a:13.4e}{b:13.4e}{c:13.4e}{dx:13.4e}{x:13.4e}')
        break  # reaches RETURN
    return a, b, c, x


def newdm():
    """New m-scale, calculated as that corresponding to a new
    tau(Ross)-scale, which is logarithmically equidistant, with
    a generally different step in six different regions:

    1. region between the original tau(1) and T0 (taken as 0.01);
    2. region between T0 and TC0 (taken as 0.01 and 0.1) - denser
       mesh (with number of points N0)
    3. region between TC0 and TC1 (taken as 0.1 and 10.) - the
       central region with densest mesh (N1 points)
    4. region between TC1 and T1 (taken as 10. and 100.) - as dens
       as the second region (N0 points)
    5. the remaining region between T1 and the original last tau
       (more precisely, the last-but-one point TAUROS(ND-1).

    If T1 is greater than the original last tau, the new tau-scale
    is equidistant between T0 and the last tau.

    The procedure also calulates all the necessary state parameters
    for the new depth scale (density, z, pressure, opacities, and
    temperature)

    Corresponds to tlusty208.f lines 41697-41901. No dummies.
    """
    TEN = 10.0  # PARAMETER (TEN=1.D1)
    tau = np.zeros(MDEPTH + 1)
    taul = np.zeros(MDEPTH + 1)
    dm0 = np.zeros(MDEPTH + 1)
    dens0 = np.zeros(MDEPTH + 1)
    abrs0 = np.zeros(MDEPTH + 1)
    abpl0 = np.zeros(MDEPTH + 1)

    n0 = 8
    nc0 = 24                       # DATA N0,NC0 /8,24/
    t0 = -2.0
    tc0 = -1.0
    tc1 = 1.0
    t1 = 2.0                       # DATA T0,TC0,TC1,T1 /-2.D0,-1.D0,1.D0,2.D0/

    imin = 0
    imax = 0  # TODO(port): in the original, IMIN/IMAX undefined if condition unmet (stale value)
    for id in range(1, C.ND + 1):
        dm0[id] = C.DM[id]
        dens0[id] = C.DENS[id]
        abrs0[id] = C.ABROSD[id]
        abpl0[id] = C.ABPLAD[id]
        taul[id] = math.log10(C.TAUROS[id])
        if taul[id] < t0:
            imin = id
        if taul[id] < t1:
            imax = id
    nd1 = C.ND - 1
    nc = 2 * n0 + nc0
    nb = nd1 - nc
    if imax >= nd1:
        ic = 0
    else:
        x = (taul[imin] - taul[1]) / (taul[nd1] - taul[imax])
        x1 = float(nb) / (x + UN)
        ic = int(x1)  # Fortran INT(X1): truncation toward zero
    nb0 = nb - ic

    # New tau-scale
    #
    # First, logarithmically equidistant tau-points between tau(1)
    # (which is the previous TAUROS(1)), and log tau = T0.
    # Their number is NB0.
    dt = (t0 - taul[1]) / float(nb0 - 1)
    tau[1] = taul[1]
    for id in range(2, nb0 + 1):
        tau[id] = tau[id - 1] + dt

    if ic > 0:
        # 2.region - between log tau = T0 and TC0
        dt = (tc0 - t0) / float(n0)
        for i in range(1, n0 + 1):
            tau[nb0 + i] = tau[nb0 + i - 1] + dt

        # 3. The most dense region between TC0 and TC1 (central part)
        nb1 = nb0 + n0
        dt = (tc1 - tc0) / float(nc0)
        for i in range(1, nc0 + 1):
            tau[nb1 + i] = tau[nb1 + i - 1] + dt

        # 4. The part similar to that between T0 and TC0, this time
        #    betwen TC1 and T1
        nb2 = nb1 + nc0
        dt = (t1 - tc1) / float(n0)
        for i in range(1, n0 + 1):
            tau[nb2 + i] = tau[nb2 + i - 1] + dt

        # 5. The remainig part between T1 and the last-but-one tau
        nb3 = nb2 + n0
        dt = (taul[nd1] - t1) / float(ic)
        for i in range(1, ic + 1):
            tau[nb3 + i] = tau[nb3 + i - 1] + dt
        tau[C.ND] = taul[C.ND]

    # The case where the last tau is smaller than T1; in this case
    # the points are logarithmically equidistant between T0 and the
    # last-but-one tau
    else:
        dt = (taul[nd1] - t0) / float(nc)
        for i in range(1, nc + 1):
            tau[nb0 + i] = tau[nb0 + i - 1] + dt
        tau[C.ND] = taul[C.ND]

    # ---------------------------------------
    # Final new Rosseland optical depth scale
    for id in range(1, C.ND + 1):
        tau[id] = TEN**tau[id]

    # Interpolation from the old to the new tau(Ross) scale to
    # get the new m-scale, density and Planck mean opacity
    interp(C.TAUROS, dm0, tau, C.DM, C.ND, C.ND, 2, 1, 1)
    interp(dm0, dens0, C.DM, C.DENS, C.ND, C.ND, 2, 1, 1)
    interp(dm0, abrs0, C.DM, C.ABROSD, C.ND, C.ND, 2, 1, 1)
    interp(dm0, abpl0, C.DM, C.ABPLAD, C.ND, C.ND, 2, 1, 1)

    # New Rosseland opacity and functions theta and tauthe
    amuv0 = C.dmvisc**(C.zeta0 + UN)
    amuv1 = UN - amuv0
    for id in range(1, C.ND + 1):
        if C.DM[id] <= C.dmvisc * C.DM[C.ND]:
            C.VISCD[id] = ((UN - C.fractv) * (C.zeta1 + UN)
                           / C.dmvisc**(C.zeta1 + UN)
                           * (C.DM[id] / C.DM[C.ND])**C.zeta1)
            C.THETA[id] = ((UN - C.fractv)
                           * (C.DM[id] / C.dmvisc / C.DM[C.ND])**(C.zeta1 + UN))
        else:
            C.VISCD[id] = (C.fractv * (C.zeta0 + UN) / amuv1
                           * (C.DM[id] / C.DM[C.ND])**C.zeta0)
            C.THETA[id] = ((UN - C.fractv)
                           + C.fractv * ((C.DM[id] / C.DM[C.ND])**(C.zeta0 + UN)
                                         - amuv0) / amuv1)
        C.GAMJ[id] = UN
        if id == 1:
            C.TAUROS[id] = C.DM[id] * C.ABROSD[id]
            C.TAUTHE[id] = C.TAUROS[id] * C.THETA[id] / (C.zeta1 + TWO)
            C.anerel = C.ELEC[id] / (C.DENS[id] / C.WMM[id] + C.ELEC[id])
        else:
            ddm = C.DM[id] - C.DM[id - 1]
            C.TAUROS[id] = (C.TAUROS[id - 1]
                            + ddm * HALF * (C.ABROSD[id - 1] + C.ABROSD[id]))
            zetad = C.zeta0
            if C.DM[id] <= C.dmvisc * C.DM[C.ND]:
                zetad = C.zeta1
            a0 = ((C.ABROSD[id - 1] * C.DM[id] - C.ABROSD[id] * C.DM[id - 1])
                  / ddm / (zetad + TWO))
            a1 = (C.ABROSD[id] - C.ABROSD[id - 1]) / ddm / (zetad + 3.0)
            C.TAUTHE[id] = (C.TAUTHE[id - 1]
                            + a0 * (C.THETA[id] * C.DM[id]
                                    - C.THETA[id - 1] * C.DM[id - 1])
                            + a1 * (C.THETA[id] * C.DM[id]**2
                                    - C.THETA[id - 1] * C.DM[id - 1]**2))
        taur = C.TAUROS[id]
        id, taur, _itgr = temper(id, taur, 1)  # CALL TEMPER(ID,TAUR,1)

    # Next step - simultaneous solution of the hydrostatic
    # equilibrium and the z-m relation
    if C.NCONIT >= 0:
        hesolv()

    # New temperature and mean opacities for the current density
    # and pressure
    for id in range(1, C.ND + 1):
        taur = C.TAUROS[id]
        id, taur, _itgr = temper(id, taur, 1)  # CALL TEMPER(ID,TAUR,1)

    # Once again - simultaneous solution of the hydrostatic
    # equilibrium and the z-m relation
    if C.NCONIT >= 0:
        hesolv()

    if C.IPRING >= 1:
        # 601 FORMAT(1H1,' NEW DEPTH GRID ESTABLISHED, NEW MODEL:'/
        #            ' --------------------------------------'/
        #  ' ID    DM     TAUROSS   TEMP     NE       P',
        #  8X,'ZD     ROSS.MEAN  PLANCK'/)
        print('\f NEW DEPTH GRID ESTABLISHED, NEW MODEL:')
        print(' --------------------------------------')
        print(' ID    DM     TAUROSS   TEMP     NE       P'
              '        ZD     ROSS.MEAN  PLANCK')
        print()
        for id in range(1, C.ND + 1):
            # 602 FORMAT(1H ,I3,1P2D9.2,0PF8.0,1P3D9.2,2X,2D9.2)
            print(f' {id:3d}{C.DM[id]:9.2e}{C.TAUROS[id]:9.2e}'
                  f'{C.TEMP[id]:8.0f}{C.ELEC[id]:9.2e}{C.PTOTAL[id]:9.2e}'
                  f'{C.ZD[id]:9.2e}  {C.ABROSD[id]:9.2e}{C.ABPLAD[id]:9.2e}')

    return


def newdmt():
    """New m-scale, calculated as that corresponding to the new
    grid better representing temperature variations

    Corresponds to tlusty208.f lines 41908-42022. No dummies.
    """
    dm0 = np.zeros(MDEPTH + 1)
    dm11 = np.zeros(MDEPTH + 1)
    dens0 = np.zeros(MDEPTH + 1)
    zd0 = np.zeros(MDEPTH + 1)
    t0 = np.zeros(MDEPTH + 1)
    t1 = np.zeros(MDEPTH + 1)
    elec0 = np.zeros(MDEPTH + 1)
    pt0 = np.zeros(MDEPTH + 1)
    abrs0 = np.zeros(MDEPTH + 1)
    abpl0 = np.zeros(MDEPTH + 1)

    for id in range(1, C.ND + 1):
        dm0[id] = math.log10(C.DM[id])
        t0[id] = math.log10(C.TAUROS[id])
        elec0[id] = C.ELEC[id]
        dens0[id] = C.DENS[id]
        pt0[id] = C.PTOTAL[id]
        zd0[id] = C.ZD[id]
        abrs0[id] = C.ABROSD[id]
        abpl0[id] = C.ABPLAD[id]
    nd1 = C.ND - 1
    gridp(dm0, t0, dm11, t1, nd1)
    dm11[C.ND] = dm0[C.ND]
    t1[C.ND] = t0[C.ND]
    for id in range(1, C.ND + 1):
        C.DM[id] = math.exp(2.3025851 * dm11[id])
        C.TAUROS[id] = math.exp(2.3025851 * t1[id])
    interp(dm0, elec0, dm11, C.ELEC, C.ND, C.ND, 2, 0, 1)
    interp(dm0, dens0, dm11, C.DENS, C.ND, C.ND, 2, 0, 1)
    interp(dm0, pt0, dm11, C.PTOTAL, C.ND, C.ND, 2, 0, 1)
    interp(dm0, zd0, dm11, C.ZD, C.ND, C.ND, 2, 0, 0)
    interp(dm0, abrs0, dm11, C.ABROSD, C.ND, C.ND, 2, 0, 1)
    interp(dm0, abpl0, dm11, C.ABPLAD, C.ND, C.ND, 2, 0, 1)
    for id in range(1, C.ND + 1):
        C.VSND2[id] = C.PTOTAL[id] / C.DENS[id]

    # New Rosseland opacity and functions theta and tauthe
    amuv0 = C.dmvisc**(C.zeta0 + UN)
    amuv1 = UN - amuv0
    for id in range(1, C.ND + 1):
        if C.DM[id] <= C.dmvisc * C.DM[C.ND]:
            C.VISCD[id] = ((UN - C.fractv) * (C.zeta1 + UN)
                           / C.dmvisc**(C.zeta1 + UN)
                           * (C.DM[id] / C.DM[C.ND])**C.zeta1)
            C.THETA[id] = ((UN - C.fractv)
                           * (C.DM[id] / C.dmvisc / C.DM[C.ND])**(C.zeta1 + UN))
        else:
            C.VISCD[id] = (C.fractv * (C.zeta0 + UN) / amuv1
                           * (C.DM[id] / C.DM[C.ND])**C.zeta0)
            C.THETA[id] = ((UN - C.fractv)
                           + C.fractv * ((C.DM[id] / C.DM[C.ND])**(C.zeta0 + UN)
                                         - amuv0) / amuv1)
        C.GAMJ[id] = UN
        if id == 1:
            C.TAUROS[id] = C.DM[id] * C.ABROSD[id]
            C.TAUTHE[id] = C.TAUROS[id] * C.THETA[id] / (C.zeta1 + TWO)
            C.anerel = C.ELEC[id] / (C.DENS[id] / C.WMM[id] + C.ELEC[id])
        else:
            ddm = C.DM[id] - C.DM[id - 1]
            C.TAUROS[id] = (C.TAUROS[id - 1]
                            + ddm * HALF * (C.ABROSD[id - 1] + C.ABROSD[id]))
            zetad = C.zeta0
            if C.DM[id] <= C.dmvisc * C.DM[C.ND]:
                zetad = C.zeta1
            a0 = ((C.ABROSD[id - 1] * C.DM[id] - C.ABROSD[id] * C.DM[id - 1])
                  / ddm / (zetad + TWO))
            a1 = (C.ABROSD[id] - C.ABROSD[id - 1]) / ddm / (zetad + 3.0)
            C.TAUTHE[id] = (C.TAUTHE[id - 1]
                            + a0 * (C.THETA[id] * C.DM[id]
                                    - C.THETA[id - 1] * C.DM[id - 1])
                            + a1 * (C.THETA[id] * C.DM[id]**2
                                    - C.THETA[id - 1] * C.DM[id - 1]**2))
        taur = C.TAUROS[id]
        id, taur, _itgr = temper(id, taur, 1)  # CALL TEMPER(ID,TAUR,1)

    # Next step - simultaneous solution of the hydrostatic
    # equilibrium and the z-m relation
    if C.NCONIT >= 0:
        hesolv()

    # New temperature and mean opacities for the current density
    # and pressure
    for id in range(1, C.ND + 1):
        taur = C.TAUROS[id]
        id, taur, _itgr = temper(id, taur, 1)  # CALL TEMPER(ID,TAUR,1)

    # Once again - simultaneous solution of the hydrostatic
    # equilibrium and the z-m relation
    if C.NCONIT >= 0:
        hesolv()

    if C.IPRING >= 1:
        # 601 FORMAT(1H1,' NEW DEPTH GRID ESTABLISHED, NEW MODEL:'/
        #            ' --------------------------------------'/
        #  ' ID    DM     TAUROSS   TEMP     NE       P',
        #  8X,'ZD     ROSS.MEAN  PLANCK'/)
        print('\f NEW DEPTH GRID ESTABLISHED, NEW MODEL:')
        print(' --------------------------------------')
        print(' ID    DM     TAUROSS   TEMP     NE       P'
              '        ZD     ROSS.MEAN  PLANCK')
        print()
        for id in range(1, C.ND + 1):
            # 602 FORMAT(1H ,I3,1P2D9.2,0PF8.0,1P3D9.2,2X,2D9.2)
            print(f' {id:3d}{C.DM[id]:9.2e}{C.TAUROS[id]:9.2e}'
                  f'{C.TEMP[id]:8.0f}{C.ELEC[id]:9.2e}{C.PTOTAL[id]:9.2e}'
                  f'{C.ZD[id]:9.2e}  {C.ABROSD[id]:9.2e}{C.ABPLAD[id]:9.2e}')

    return


def gridp(x, y, xnew, ynew, n):
    """evaluation of new grid points for a function; grid points
    determined by dividing the curve Y=f(x) into n-1 equal segments;
    the x-coordinates of the endpoints of the individual segments
    define new grid points

    Corresponds to tlusty208.f lines 42029-42082. No scalar dummies modified; no return.
    """
    z = np.zeros(MDEPTH + 1)

    # original segments - lengths (Z), and directional cosines (CD);
    # ZTOT - total length of the curve;
    # Z0 - length of a new segment
    ztot = 0.0
    for i in range(2, n + 1):
        z[i - 1] = math.sqrt((x[i] - x[i - 1])**2 + (y[i] - y[i - 1])**2)
        ztot = ztot + z[i - 1]
    z0 = ztot / (n - 1)

    iseg = 1
    xlast = x[iseg]
    ylast = y[iseg]
    zrest = z[iseg]
    zrem = z0
    ip = 1
    xnew[ip] = x[1]
    ynew[ip] = y[1]

    while True:
        # label 20
        if zrem < zrest:
            zrest = zrest - zrem
            xlast = xlast + zrem * (x[iseg + 1] - x[iseg]) / z[iseg]
            ylast = ylast + zrem * (y[iseg + 1] - y[iseg]) / z[iseg]
            ip = ip + 1
            xnew[ip] = xlast
            ynew[ip] = ylast
            zrem = z0
            if ip >= n - 1:
                break  # GO TO 50
        else:
            zrem = zrem - zrest
            iseg = iseg + 1
            xlast = x[iseg]
            ylast = y[iseg]
            zrest = z[iseg]
        # GO TO 20 -> continue loop
    # label 50
    xnew[n] = x[n]
    ynew[n] = y[n]
    return


def hesolv():
    """Solution of the coupled system of hydrostatic equilibrium equation
    and the z-m relation; with a given (generally depth-dependent) sound
    speed, defined as total pressure/density.
    Numerical solution by a Newton-Raphson method

    Input:  P     - initial total pressure
            VSND2 - sound speed squared
            HG1   - gas pressure scale height at the surface
            RR1   - ratio of radiation and gas pressure scale heights
                    at the surface

    Corresponds to tlusty208.f lines 42089-42300. No dummies.
    """
    p = np.zeros(MDEPTH + 1)
    b = np.zeros((2 + 1, 2 + 1))
    c = np.zeros((2 + 1, 2 + 1))
    vl = np.zeros(2 + 1)
    d = np.zeros((2 + 1, 2 + 1, MDEPTH + 1))
    anu = np.zeros((2 + 1, MDEPTH + 1))

    ERROR = 1.0e-4  # DATA ERROR /1.D-4/

    # Density for a given total pressure and sound speed
    for id in range(1, C.ND + 1):
        p[id] = C.PTOTAL[id]
        C.VSND2[id] = p[id] / C.DENS[id]

    # Consistent z-values
    # c     ZD(ND)=ZND
    # c     DO IID=1,ND-1
    # c        ID=ND-IID
    # c        ZD(ID)=ZD(ID+1)+HALF*(DM(ID+1)-DM(ID))*(UN/DENS(ID)+
    # c    *                   UN/DENS(ID+1))
    # c     END DO

    # Basic Newton-Raphson iteration loop
    iterh = 0
    an = 0.0
    ane = 0.0  # initial value for output (RHONEN output)
    while True:
        # label 30
        iterh = iterh + 1

        # -------------------
        # Forward elimination
        # -------------------
        #
        # Upper boundary condition
        id = 1
        x = C.ZD[1] / C.HG1 - C.RR1
        if x < 3.0:
            if x < 0.0:
                x = 0.0
            f1 = 1.772453851e0 * math.exp(x * x) * erfcx(x)
        else:
            f1 = (UN - HALF / x / x) / x
        bet0 = HALF / C.DENS[id] / p[id]
        betp = HALF / C.DENS[id + 1] / p[id + 1]
        gama = UN / (C.DM[id + 1] - C.DM[id])
        b[1, 1] = f1
        b[1, 2] = TWO * (x * f1 - UN) * p[1] / C.HG1
        b[2, 1] = bet0
        b[2, 2] = gama
        c[1, 1] = 0.0
        c[1, 2] = 0.0
        c[2, 1] = -betp
        c[2, 2] = gama
        vl[1] = C.DM[id] * 2.0 * C.VSND2[id] / C.HG1 - p[id] * f1
        vl[2] = bet0 * p[id] + betp * p[id + 1] - gama * (C.ZD[id] - C.ZD[id + 1])
        anu[1, id] = 0.0
        anu[2, id] = 0.0
        matinv(b, 2, 2)
        for i in range(1, 3):
            for j in range(1, 3):
                s = 0.0
                for k in range(1, 3):
                    s = s + b[i, k] * c[k, j]
                d[i, j, id] = s
                anu[i, id] = anu[i, id] + b[i, j] * vl[j]

        # Normal depth points  1 < ID < ND
        for id in range(2, C.ND):
            bet0 = betp
            betp = HALF / C.DENS[id + 1] / p[id + 1]
            gama = UN / (C.DM[id + 1] - C.DM[id])
            dmd = HALF * (C.DM[id + 1] - C.DM[id - 1])
            aa = UN / (C.DM[id] - C.DM[id - 1]) / dmd
            cc = gama / dmd
            bb = aa + cc
            bq = C.QGRAV / p[id] / C.DENS[id]
            b[1, 1] = bb + bq - aa * d[1, 1, id - 1]
            b[1, 2] = -aa * d[1, 2, id - 1]
            b[2, 1] = bet0
            b[2, 2] = gama
            c[1, 1] = cc
            c[1, 2] = 0.0
            c[2, 1] = -betp
            c[2, 2] = gama
            vl[1] = (aa * p[id - 1] + cc * p[id + 1] - (bb - bq) * p[id]
                     + aa * anu[1, id - 1])
            vl[2] = bet0 * p[id] + betp * p[id + 1] - gama * (C.ZD[id] - C.ZD[id + 1])
            matinv(b, 2, 2)
            anu[1, id] = 0.0
            anu[2, id] = 0.0
            for i in range(1, 3):
                for j in range(1, 3):
                    s = 0.0
                    for k in range(1, 3):
                        s = s + b[i, k] * c[k, j]
                    d[i, j, id] = s
                    anu[i, id] = anu[i, id] + b[i, j] * vl[j]

        # Lower boundary condition
        id = C.ND
        aa = TWO / (C.DM[id] - C.DM[id - 1])**2
        bq = C.QGRAV / p[id] / C.DENS[id]
        b[1, 1] = aa + bq - aa * d[1, 1, id - 1]
        b[1, 2] = -aa * d[1, 2, id - 1]
        b[2, 1] = 0.0
        b[2, 2] = UN
        vl[1] = C.QGRAV / C.DENS[id] + aa * (p[id - 1] - p[id] + anu[1, id - 1])
        vl[2] = 0.0
        matinv(b, 2, 2)
        anu[1, id] = 0.0
        anu[2, id] = 0.0
        for i in range(1, 3):
            for j in range(1, 3):
                s = 0.0
                for k in range(1, 3):
                    s = s + b[i, k] * c[k, j]
                d[i, j, id] = s
                anu[i, id] = anu[i, id] + b[i, j] * vl[j]

        # ------------
        # Backsolution
        # ------------
        p[id] = p[id] + anu[1, id]
        C.ZD[id] = C.ZND
        chmaxx = abs(anu[1, id] / p[id])
        for iid in range(1, C.ND):
            id = C.ND - iid
            for i in range(1, 3):
                for j in range(1, 3):
                    anu[i, id] = anu[i, id] + d[i, j, id] * anu[j, id + 1]
            ch1 = anu[1, id] / p[id]
            ch2 = anu[2, id] / C.ZD[id]
            if abs(ch1) > chmaxx:
                chmaxx = abs(ch1)
            if abs(ch2) > chmaxx:
                chmaxx = abs(ch2)
            if ch1 < -0.9e0:
                ch1 = -0.9e0
            if ch1 > 9.0:
                ch1 = 9.0
            p[id] = p[id] * (UN + ch1)

        # Recalculate density for the new total pressure
        for id in range(1, C.ND + 1):
            C.DENS[id] = p[id] / C.VSND2[id]

        # New  z-values
        C.ZD[C.ND] = C.ZND
        for iid in range(1, C.ND):
            id = C.ND - iid
            C.ZD[id] = (C.ZD[id + 1] + HALF * (C.DM[id + 1] - C.DM[id])
                        * (UN / C.DENS[id] + UN / C.DENS[id + 1]))

        # Convergence criterion for the Newton-Raphson method
        if C.IPRING >= 1:
            # 601 FORMAT(/' solution of hydrostatic eq. + z-m relation:',
            #            'iter = ',I3,' max.rel.chan. =',1PD10.2)
            print()
            print(' solution of hydrostatic eq. + z-m relation:'
                  f'iter = {iterh:3d} max.rel.chan. ={chmaxx:10.2e}')
        if chmaxx > ERROR and iterh < 10:
            continue  # GO TO 30
        break

    for id in range(1, C.ND + 1):
        x = C.PGS[id] / C.PTOTAL[id]
        C.PTOTAL[id] = p[id]
        C.PGS[id] = x * p[id]

    # Recalculation of the populations
    if C.IH2P >= 0:
        id = 1
        C.anerel = C.ELEC[id] / (C.DENS[id] / C.WMM[id] + C.ELEC[id])
        for id in range(1, C.ND + 1):
            id, _t, _rho, an, ane = rhonen(id, C.TEMP[id], C.DENS[id], an, ane)
            C.ELEC[id] = ane
            wnstor(id)
            steqeq(id, C.POP, 1)
    return


def hesol6():
    """Solution of the coupled system of
    1) hydrostatic equilibrium equation;
    2) definitions of Ptotal, Pgas and rho;
    3) state equation
    4) z-m relation
    with a given temperature and radiation pressure
    Numerical solution by a Newton-Raphson method

    Corresponds to tlusty208.f lines 42307-42684. No dummies.
    """
    # PARAMETER (MP=6,NP=6,IP=1,IG=2,IR=3,IN=4,IE=5,IZ=6)
    # PARAMETER (NITERH=15)
    mp = 6
    np_ = 6   # NP; avoid shadowing the numpy alias np
    ip = 1
    ig = 2
    ir = 3
    in_ = 4   # IN; in is a Python keyword
    ie = 5
    iz = 6
    niterh = 15

    p = np.zeros(MDEPTH + 1)
    antt = np.zeros(MDEPTH + 1)
    chng = np.zeros(MDEPTH + 1)
    vec = np.zeros((mp + 1, MDEPTH + 1))
    vec1 = np.zeros((mp + 1, MDEPTH + 1))
    vec2 = np.zeros((mp + 1, MDEPTH + 1))
    vec3 = np.zeros((mp + 1, MDEPTH + 1))
    sol = np.zeros(mp + 1)
    err = np.zeros(mp + 1)
    chn = np.zeros(mp + 1)
    a = np.zeros((mp + 1, mp + 1))
    b = np.zeros((mp + 1, mp + 1))
    c = np.zeros((mp + 1, mp + 1))
    vl = np.zeros(mp + 1)
    d = np.zeros((mp + 1, mp + 1, MDEPTH + 1))
    anu = np.zeros((mp + 1, MDEPTH + 1))
    anerl = np.zeros(MDEPTH + 1)

    ERROR = 1.0e-4  # DATA ERROR /1.D-4/

    # radiation pressure scale feight at the surface
    id = 1
    if C.ITER == 0:
        C.HR1 = SIG4P * C.TEFF**4 * PCK * C.ABROSD[id] / C.QGRAV
    else:
        grd = 0.0  # TODO(port): in the original GRD is uninitialized before accumulation (relies on zero init)
        if C.NFREQE > 0:
            for ij in range(1, C.NFREQE + 1):
                ijt = C.IJFR[ij]
                if not C.LSKIP[id, ijt]:
                    fluxw = C.W[ijt] * (C.FH[ijt] * C.RADEX[ij, id]
                                        - C.HEXTRD[ijt])
                    grd = grd + fluxw * C.ABSOE1[ij]
        C.HR1 = PCK / C.QGRAV * (grd + C.FPRD[id]) / C.DENS[id]
    for id in range(1, C.ND + 1):
        antt[id] = C.DENS[id] / C.WMM[id] + C.ELEC[id]
        C.PGS[id] = antt[id] * BOLK * C.TEMP[id]
        C.PTOTAL[id] = C.PRADT[id] + C.PGS[id]

    # Basic Newton-Raphson iteration loop
    iterh = 0
    lac2h = False
    iach = 6
    iacdh = 4
    iach0 = iach - 3
    while True:
        # label 10
        iterh = iterh + 1

        # -------------------
        # Forward elimination
        # -------------------
        for id in range(1, C.ND + 1):
            antt[id] = C.DENS[id] / C.WMM[id] + C.ELEC[id]
            C.PGS[id] = antt[id] * BOLK * C.TEMP[id]
            C.PTOTAL[id] = C.PRADT[id] + C.PGS[id]
            p[id] = C.PTOTAL[id]
            vec[ip, id] = C.PTOTAL[id]
            vec[ig, id] = C.PGS[id]
            vec[ir, id] = C.DENS[id]
            vec[in_, id] = antt[id]
            vec[ie, id] = C.ELEC[id]
            vec[iz, id] = C.ZD[id]

            for i in range(1, np_ + 1):
                vl[i] = 0.0
                for j in range(1, np_ + 1):
                    b[i, j] = 0.0
                    a[i, j] = 0.0
                    c[i, j] = 0.0

            if id == 1:
                C.HG1 = math.sqrt(TWO * C.PGS[id] / C.DENS[id] / C.QGRAV)
                x = (C.ZD[id] - C.HR1) / C.HG1
                if x < 3.0:
                    if x < 0.0:
                        x = 0.0
                    f1 = 8.86226925e-1 * math.exp(x * x) * erfcx(x)
                else:
                    f1 = HALF * (UN - HALF / x / x) / x
                x1 = x * 1.01
                f1d = 0.0
                if x1 < 3.0:
                    f1d = 8.86226925e-1 * math.exp(x1 * x1) * erfcx(x1)
                else:
                    f1d = HALF * (UN - HALF / x1 / x1) / x1
                if x > 0.0:
                    f1d = (f1d - f1) * 100.0 / x
                b[ig, ig] = C.DENS[id] * C.HG1 * HALF / C.PGS[id] * (f1 - f1d * x)
                b[ig, ir] = C.HG1 * HALF * (f1 + f1d * x)
                b[ig, iz] = C.DENS[id] * f1d
                vl[ig] = C.DM[id] - C.DENS[id] * C.HG1 * f1
                b[ip, ip] = UN
                b[ip, ig] = -UN
                vl[ip] = C.PRADT[id] + C.PGS[id] - p[id]
            else:
                dmm = UN / (C.DM[id] - C.DM[id - 1])
                qg = HALF * C.QGRAV
                b[ip, ip] = dmm
                b[ip, iz] = -qg
                a[ip, ip] = dmm
                a[ip, iz] = qg
                vl[ip] = qg * (C.ZD[id] + C.ZD[id - 1]) - (p[id] - p[id - 1]) * dmm
                b[ig, ip] = UN
                b[ig, ig] = -UN
                vl[ig] = C.PRADT[id] + C.PGS[id] - p[id]

            b[ir, ir] = UN
            b[ir, in_] = -C.WMM[id]
            b[ir, ie] = C.WMM[id]
            vl[ir] = C.WMM[id] * (antt[id] - C.ELEC[id]) - C.DENS[id]

            b[in_, ig] = UN
            b[in_, in_] = -BOLK * C.TEMP[id]
            vl[in_] = antt[id] * BOLK * C.TEMP[id] - C.PGS[id]

            t = C.TEMP[id]
            an = antt[id]
            anerl[id] = C.ELEC[id] / an
            b[ie, ie] = UN
            b[ie, in_] = -anerl[id]
            vl[ie] = anerl[id] * antt[id] - C.ELEC[id]

            if id < C.ND:
                dmp = (C.DM[id + 1] - C.DM[id]) * HALF
                b[iz, ir] = dmp / C.DENS[id]**2
                b[iz, iz] = UN
                c[iz, ir] = -dmp / C.DENS[id + 1]**2
                c[iz, iz] = UN
                vl[iz] = (C.ZD[id + 1] - C.ZD[id] + dmp / C.DENS[id]
                          + dmp / C.DENS[id + 1])
            else:
                b[iz, iz] = UN
                vl[iz] = 0.0

            if id > 1:
                b[ip, ir] = (b[ip, ir]
                             - a[ip, ip] * d[ip, ir, id - 1]
                             - a[ip, iz] * d[iz, ir, id - 1])
                b[ip, iz] = (b[ip, iz]
                             - a[ip, ip] * d[ip, iz, id - 1]
                             - a[ip, iz] * d[iz, iz, id - 1])
                vl[ip] = (vl[ip] + a[ip, ip] * anu[ip, id - 1]
                          + a[ip, iz] * anu[iz, id - 1])

            matinv(b, np_, mp)

            for i in range(1, np_ + 1):
                sum_ = 0.0
                for j in range(1, np_ + 1):
                    sum_ = sum_ + b[i, j] * vl[j]
                anu[i, id] = sum_
            if id < C.ND:
                for i in range(1, np_ + 1):
                    d[i, ir, id] = b[i, iz] * c[iz, ir]
                    d[i, iz, id] = b[i, iz] * c[iz, iz]

        # -------------------
        # backsubstitution
        # -------------------
        chanm = 0.0
        for id in range(C.ND, 0, -1):
            chng[id] = 0.0
            if id == C.ND:
                for i in range(1, np_ + 1):
                    sol[i] = anu[i, id]
            else:
                for i in range(1, np_ + 1):
                    anu[i, id] = (anu[i, id] + d[i, ir, id] * anu[ir, id + 1]
                                  + d[i, iz, id] * anu[iz, id + 1])
                    sol[i] = anu[i, id]
            for i in range(1, np_ + 1):
                chan = 0.0
                if vec[i, id] != 0.0:
                    chan = sol[i] / vec[i, id]
                chn[i] = chan
                if abs(chan) > chanm:
                    chanm = abs(chan)
                if abs(chan) > chng[id]:
                    chng[id] = abs(chan)
                if chan < -0.99:
                    chan = -0.99
                if chan > 99.00:
                    chan = 99.00
                vec[i, id] = vec[i, id] * (UN + chan)

            C.PTOTAL[id] = vec[ip, id]
            p[id] = C.PTOTAL[id]
            C.PGS[id] = vec[ig, id]
            C.DENS[id] = vec[ir, id]
            antt[id] = vec[in_, id]
            C.ELEC[id] = vec[ie, id]
            C.ZD[id] = vec[iz, id]

            if id == 1:
                C.HG1 = math.sqrt(TWO * C.PGS[id] / C.DENS[id] / C.QGRAV)
                x = (C.ZD[id] - C.HR1) / C.HG1
                if x < 3.0:
                    if x < 0.0:
                        x = 0.0
                    f1 = 8.86226925e-1 * math.exp(x * x) * erfcx(x)
                else:
                    f1 = HALF * (UN - HALF / x / x) / x
                err[ip] = (C.DENS[id] * C.HG1 * f1 - C.DM[id]) / C.DM[id]
            elif id < C.ND:
                err[ip] = ((p[id + 1] - p[id]) / (C.DM[id + 1] - C.DM[id])
                           * TWO / C.QGRAV / (C.ZD[id + 1] + C.ZD[id]) - UN)
            else:
                err[ip] = 0.0
            if p[id] != 0.0:
                err[ig] = (C.PRADT[id] + C.PGS[id] - p[id]) / p[id]
            if C.DENS[id] != 0.0:
                err[ir] = ((C.DENS[id] - (antt[id] - C.ELEC[id]) * C.WMM[id])
                           / C.DENS[id])
            if C.PGS[id] != 0.0:
                err[in_] = (C.PGS[id] - antt[id] * BOLK * C.TEMP[id]) / C.PGS[id]
            if C.ELEC[id] != 0.0:
                err[ie] = (C.ELEC[id] - anerl[id] * antt[id]) / C.ELEC[id]
            if id < C.ND:
                err[iz] = ((C.ZD[id] - C.ZD[id + 1]) * TWO
                           / (C.DM[id + 1] - C.DM[id])
                           / (UN / C.DENS[id] + UN / C.DENS[id + 1]) - UN)
            else:
                err[iz] = C.ZD[id]

        # acceleration
        _goto100 = False
        if niterh < iach or iterh < iach0:
            _goto100 = True  # GO TO 100
        if not _goto100:
            ipngh = 1
            if iacdh > 0:
                ipngh = imod(iterh - iach, iacdh)
            if not lac2h:
                ipt = imod(iterh, 3)
                ipt0 = imod(iach, 3)  # ipt0 unused in the original code
                ipt1 = imod(iach + 1, 3)
                ipt2 = imod(iach + 2, 3)
                if iterh == iach0:
                    for id in range(1, C.ND + 1):
                        for ix in range(1, np_ + 1):
                            vec3[ix, id] = vec[ix, id]
                elif ipt == ipt1:
                    for id in range(1, C.ND + 1):
                        for ix in range(1, np_ + 1):
                            vec2[ix, id] = vec[ix, id]
                elif ipt == ipt2:
                    for id in range(1, C.ND + 1):
                        for ix in range(1, np_ + 1):
                            vec1[ix, id] = vec[ix, id]
            elif ipngh != 0:
                for id in range(1, C.ND + 1):
                    for ix in range(1, np_ + 1):
                        vec3[ix, id] = vec2[ix, id]
                for id in range(1, C.ND + 1):
                    for ix in range(1, np_ + 1):
                        vec2[ix, id] = vec1[ix, id]
                for id in range(1, C.ND + 1):
                    for ix in range(1, np_ + 1):
                        vec1[ix, id] = vec[ix, id]
                _goto100 = True  # GO TO 100

            if not _goto100:
                if iterh < iach:
                    _goto100 = True  # GO TO 100
                else:
                    a1 = 0.0
                    b1 = 0.0
                    b2 = 0.0
                    c1 = 0.0
                    c2 = 0.0
                    for ix in range(1, np_ + 1):
                        for id in range(1, C.ND + 1):
                            wt = 0.0
                            if vec[ix, id] != 0.0:
                                wt = 1.0 / abs(vec[ix, id])
                            d0 = vec[ix, id] - vec1[ix, id]
                            d1 = d0 - vec1[ix, id] + vec2[ix, id]
                            d2 = d0 - vec2[ix, id] + vec3[ix, id]
                            a1 = a1 + wt * d1 * d1
                            b1 = b1 + wt * d1 * d2
                            b2 = b2 + wt * d2 * d2
                            c1 = c1 + wt * d0 * d1
                            c2 = c2 + wt * d0 * d2
                    ab = b2 * a1 - b1 * b1
                    if ab == 0.0:
                        iach = iach + iacdh
                        iach0 = iach - 3
                        # GO TO 100
                    else:
                        aa = (b2 * c1 - b1 * c2) / ab
                        bb = (a1 * c2 - b1 * c1) / ab
                        for id in range(1, C.ND + 1):
                            for ix in range(1, np_ + 1):
                                vec[ix, id] = ((UN - aa - bb) * vec[ix, id]
                                               + aa * vec1[ix, id]
                                               + bb * vec2[ix, id])
                        lac2h = True
        # label 100

        for id in range(1, C.ND + 1):
            C.PTOTAL[id] = vec[ip, id]
            p[id] = C.PTOTAL[id]
            C.PGS[id] = vec[ig, id]
            C.DENS[id] = vec[ir, id]
            antt[id] = vec[in_, id]
            C.ELEC[id] = vec[ie, id]
            C.ZD[id] = vec[iz, id]

            if id == 1:
                C.HG1 = math.sqrt(TWO * C.PGS[id] / C.DENS[id] / C.QGRAV)
                x = (C.ZD[id] - C.HR1) / C.HG1
                if x < 3.0:
                    if x < 0.0:
                        x = 0.0
                    f1 = 8.86226925e-1 * math.exp(x * x) * erfcx(x)
                else:
                    f1 = HALF * (UN - HALF / x / x) / x
                err[ip] = (C.DENS[id] * C.HG1 * f1 - C.DM[id]) / C.DM[id]
            elif id < C.ND:
                err[ip] = ((p[id] - p[id - 1]) / (C.DM[id] - C.DM[id - 1])
                           * TWO / C.QGRAV / (C.ZD[id] + C.ZD[id - 1]) - UN)
            if p[id] != 0.0:
                err[ig] = (C.PRADT[id] + C.PGS[id] - p[id]) / p[id]
            if C.DENS[id] != 0.0:
                err[ir] = ((C.DENS[id] - (antt[id] - C.ELEC[id]) * C.WMM[id])
                           / C.DENS[id])
            if C.PGS[id] != 0.0:
                err[in_] = (C.PGS[id] - antt[id] * BOLK * C.TEMP[id]) / C.PGS[id]
            if C.ELEC[id] != 0.0:
                err[ie] = (C.ELEC[id] - anerl[id] * antt[id]) / C.ELEC[id]
            if id > 1:
                err[iz] = ((C.ZD[id - 1] - C.ZD[id]) * TWO
                           / (C.DM[id] - C.DM[id - 1])
                           / (UN / C.DENS[id - 1] + UN / C.DENS[id]) - UN)
            else:
                err[iz] = 0.0

        # Convergence criterion for the Newton-Raphson method
        if chanm > ERROR and iterh < niterh:
            continue  # GO TO 10
        break

    return


def psolve():
    """"formal" solution of the second-order equation for the total
    pressure  -  d**2 P/d m**2 = Q/DENS;
    with known density
    the resulting tridiagonal system is solved by the standard
    elimination

    Corresponds to tlusty208.f lines 42692-42736. No dummies.
    """
    d = np.zeros(MDEPTH + 1)
    anu = np.zeros(MDEPTH + 1)

    # forward elimination
    id = 1
    b = 1.0
    vl = C.PTOTAL[id]
    d[id] = 0.0
    anu[id] = vl / b
    for id in range(2, C.ND):
        dmd = HALF * (C.DM[id + 1] - C.DM[id - 1])
        a = UN / dmd / (C.DM[id] - C.DM[id - 1])
        c = UN / dmd / (C.DM[id + 1] - C.DM[id])
        b = a + c - a * d[id - 1]
        vl = C.QGRAV / C.DENS[id]
        d[id] = c / b
        anu[id] = (vl + a * anu[id - 1]) / b
    id = C.ND
    a = TWO / (C.DM[id] - C.DM[id - 1])**2
    b = a - a * d[id - 1]
    vl = C.QGRAV / C.DENS[id]
    anu[id] = (vl + a * anu[id - 1]) / b
    C.PTOTAL[C.ND] = anu[C.ND]

    # backsubstitution
    for iid in range(1, C.ND):
        id = C.ND - iid
        C.PTOTAL[id] = anu[id] + d[id] * C.PTOTAL[id + 1]
    return


def zmrho(r, hg):
    """Initial estimate of DM, DENS, and ZD
    by an approximate solution of the hydrostatic equilibrium
    equation
    Both gas and radiation pressure contribute;

    Input: R     - ration of radiation to gas pressure scale heights
           HG    - gas pressure scale height
           DM1   - mass at the first depth point
           DMTOT - mass at the last depth point (central plane)

    Corresponds to tlusty208.f lines 42743-42849. No scalar dummies modified; no return.
    (DM1, DMTOT, ND are COMMON variables, accessed/modified via C.)
    """
    pisq = 1.77245385090551e0
    pisq2 = pisq * HALF  # PARAMETER (PISQ=...,pisq2=pisq*half)

    # Mass-depth grid - logarithmicaly equidistant
    if C.ND > MDEPTH:
        C.ND = MDEPTH

    if C.DM1 > 0:
        C.DM[C.ND] = C.DMTOT
        C.DM[C.ND - 1] = 0.99e0 * C.DMTOT
        dml = math.log(C.DM[C.ND - 1] / C.DM1) / (C.ND - 2)
        dml1 = math.log(C.DM1)
        for id in range(1, C.ND):
            C.DM[id] = math.exp(dml1 + (id - 1) * dml)
    elif C.DM1 < -1.0e-20 and C.DM1 > -1.0e-10:
        C.DM[C.ND] = C.DMTOT
        C.DM1 = abs(C.DM1 * 1.0e20)
        dml = math.log(C.DM[C.ND] / C.DM1) / (C.ND - 1)
        dml1 = math.log(C.DM1)
        for id in range(1, C.ND):
            C.DM[id] = math.exp(dml1 + (id - 1) * dml)
    elif C.DM1 > -1.0e-10:
        if imod(C.ND, 2) == 0:
            C.ND = C.ND - 1
        dmha = C.DMTOT * HALF
        C.DM1 = abs(C.DM1 * 1.0e10)
        ndha = idiv(C.ND, 2)  # Fortran integer division nd/2
        dml = math.log(dmha / C.DM1) / ndha
        dml1 = math.log(C.DM1)
        C.DM[C.ND] = C.DMTOT
        for id in range(1, ndha + 1):
            C.DM[id] = math.exp(dml1 + (id - 1) * dml)
            C.DM[C.ND - id] = C.DM[C.ND] - math.exp(dml1 + id * dml)
        # Determination of the total pressure scale height - function BETAH
        # HH - total pressure scale height
    # end if
    hh = betah(r) * r
    dmh = pisq / 2.0 * math.exp(-r * (hh - r)) * erfcx(hh - r) / hh
    rho0 = C.DM[C.ND] / hh / hg

    # Approximate solution of the hydrostatic equilibrium
    for id in range(1, C.ND + 1):
        dmrel = C.DM[id] / C.DM[C.ND]
        if dmrel <= dmh:
            x = r + erfcin(dmrel * 2.0 / pisq * hh * math.exp(r * (hh - r)))
            rho = math.exp(-(x - r) * (x - r) - (hh - r) * r)
        elif dmrel < UN:
            hsq = math.sqrt(hh * (hh - r))
            x = erfcin(2.0 / pisq * hsq * (dmrel - dmh) + erfcx(hsq)) * hh / hsq
            rho = math.exp(-x * x * (UN - r / hh))
        else:
            x = 0.0
            rho = UN
        C.DENS[id] = rho0 * rho
        C.ZD[id] = x * hg

    if C.DM1 < -1.0e-10:
        C.DM[C.ND] = C.DMTOT
        C.DM[C.ND - 1] = 0.99e0 * C.DMTOT
        C.DM1 = abs(C.DM1)
        dml = math.log(C.DM[C.ND - 1] / C.DM1) / (C.ND - 2)
        dml1 = math.log(C.DM1)
        for id in range(1, C.ND):
            C.DM[id] = math.exp(dml1 + (id - 1) * dml)

        hr = r * hg
        hg2 = hg * pisq2
        hrg = hr + hg2
        dmh = hg2 / hrg
        rho0 = C.DMTOT / hrg
        for id in range(1, C.ND + 1):
            dmrel = C.DM[id] / C.DM[C.ND]
            if dmrel >= dmh:
                C.ZD[id] = hrg * (UN - dmrel)
                C.DENS[id] = rho0
            else:
                C.ZD[id] = hr + hg * erfcin(dmrel * hrg / hg2)
                x = (C.ZD[id] - hr) / hg
                C.DENS[id] = rho0 * math.exp(-x * x)
    return


def betah(r):
    """Determination of the total pressure scale height
    Solution of the transcendental equation by the Newton-Raphson method

    Corresponds to tlusty208.f lines 42856-42888. FUNCTION; returns the function value.
    """
    # PARAMETER (UN=1.D0, PISQ=1.77245385090551D0)
    # -- UN is the same as UN=1.0 in params.py, used directly; PISQ is a local constant
    pisq = 1.77245385090551e0
    if r < 0.88:
        bet0 = pisq / 2.0 / r
    else:
        bet0 = UN + UN / 3.0 / r / r

    iter = 0
    beta = bet0
    while True:
        # label 10
        iter = iter + 1
        b1 = beta - UN
        rb1 = r * b1
        bsq = math.sqrt(beta * b1)
        erf1 = erfcx(r * bsq)
        erf2 = erfcx(rb1)
        rhs = bsq / b1 * (UN - erf1) + math.exp(-r * rb1) * erf2
        dp = (r / pisq * (2.0 - math.exp(-r * beta * rb1))
              + (UN - erf1) / 2.0 / b1 / bsq
              + r * r * math.exp(-r * rb1) * erf2)
        dbeta = (rhs - 2.0 / pisq * beta * r) / dp
        del_ = dbeta / beta  # DEL; del is a Python keyword
        beta = beta + dbeta
        if abs(del_) > 1.0e-5 and iter <= 10:
            continue  # GO TO 10
        break
    return beta


def erfcin(x):
    """Approximate inverse complementary error function inverfc(x)

    Corresponds to tlusty208.f lines 42894-42913. FUNCTION; returns the function value.
    """
    pisq = 1.77245385090551e0
    pisq2 = pisq / 2.0  # parameter (pisq=..., pisq2=pisq/2.d0)
    xl = -math.log(x)
    rel = 0.88623e0 + xl * (7.4871471e-3 - xl * 1.7726701e-4)
    e = math.sqrt(-math.log(x * (2.0 - x))) * rel
    iterr = 0
    while True:
        # label 10
        iterr = iterr + 1
        dele = (erfcx(e) - x) * pisq2 * math.exp(e * e)
        err = abs(dele / e)
        e = e + dele
        if err > 1.0e-6 and iterr < 10:
            continue  # GO TO 10
        break
    return e


def radtot():
    """Evaluation of integrated radiative intensities and moments

    Corresponds to tlusty208.f lines 42920-43024. No dummies.
    Note: EXTJ, EXTH of /SURFEX/ are in the COMMON declaration but unused by this subroutine.
    """
    sumpl = np.zeros(MDEPTH + 1)

    # zero the quantities
    for id in range(1, C.ND + 1):
        C.ABROSD[id] = 0.0
        C.SUMDPL[id] = 0.0
        C.ABPLAD[id] = 0.0
        sumpl[id] = 0.0
        C.TOTJ[id] = 0.0
        C.TOTH[id] = 0.0
        C.TOTK[id] = 0.0
        C.RDOPAC[id] = 0.0
        C.FLOPAC[id] = 0.0
        if id < C.ND:
            C.DELDM[id] = HALF * (C.DM[id + 1] - C.DM[id])
            C.DELDMZ[id] = C.DELDM[id]
            if C.IZSCAL == 1:
                C.DELDMZ[id] = HALF * (C.ZD[id] - C.ZD[id + 1])
    C.DEDM1 = C.DM[1] / C.DENS[1]

    # loop over frequencies
    tdpini()
    opaini(1)
    for ij in range(1, C.NFREQ + 1):
        fr = C.FREQ[ij]
        opacf1(ij)
        rtefr1(ij)
        ww = C.W[ij]
        for id in range(1, C.ND + 1):
            plan = C.XKFB[id] / C.XKF1[id] * ww
            dplan = plan / C.XKF1[id] * C.FREQ[ij] * C.HKT21[id]
            if C.IOPTAB >= 0:
                C.ABROSD[id] = C.ABROSD[id] + dplan / C.ABSO1[id]
                C.ABPLAD[id] = C.ABPLAD[id] + plan * (C.ABSO1[id] - C.SCAT1[id])
                C.RDOPAC[id] = (C.RDOPAC[id]
                                + ww * C.RAD1[id] * (C.ABSO1[id] - C.SCAT1[id]))
            else:
                ar = (C.ABSO1[id] - C.SCAT1[id]) * C.DENS[id]
                C.ABROSD[id] = C.ABROSD[id] + dplan / (C.ABSO1[id] * C.DENS[id])
                C.ABPLAD[id] = C.ABPLAD[id] + plan * ar
                C.RDOPAC[id] = C.RDOPAC[id] + ww * C.RAD1[id] * ar
            C.SUMDPL[id] = C.SUMDPL[id] + dplan
            sumpl[id] = sumpl[id] + plan
            C.TOTJ[id] = C.TOTJ[id] + ww * C.RAD1[id]
            C.TOTK[id] = C.TOTK[id] + ww * C.RAD1[id] * C.FAK1[id]
            if id < C.ND:
                flux1 = C.RAD1[id + 1] * C.FAK1[id + 1] - C.RAD1[id] * C.FAK1[id]
                C.TOTH[id + 1] = C.TOTH[id + 1] + ww * flux1 / C.DT[id]
        wf = ww * (C.FH[ij] * C.RAD1[1] - C.HEXTRD[ij])
        C.TOTH[1] = C.TOTH[1] + wf
        if C.IOPTAB >= 0:
            C.FLOPAC[1] = C.FLOPAC[1] + wf * C.ABSO1[1] / C.DENS[1]
        else:
            C.FLOPAC[1] = C.FLOPAC[1] + wf * C.ABSO1[1]

    # Rosseland and Planck mean opacities
    for id in range(1, C.ND + 1):
        C.ABROSD[id] = C.SUMDPL[id] / C.ABROSD[id]
        C.ABPLAD[id] = C.ABPLAD[id] / sumpl[id]

    # Rosseland optical depth scale; flux mean
    id = 1
    C.TAUROS[id] = HALF * C.DEDM1 * C.ABROSD[id]
    for id in range(2, C.ND + 1):
        dtaur = (C.DELDM[id - 1] * (C.ABROSD[id] * C.DENS1[id]
                                    + C.ABROSD[id - 1] * C.DENS1[id - 1]))
        C.TAUROS[id] = C.TAUROS[id - 1] + dtaur
        C.FLOPAC[id] = (C.TOTK[id] - C.TOTK[id - 1]) / (C.DM[id] - C.DM[id - 1])

    # final Rosseland and Planck mean opacities
    for id in range(1, C.ND + 1):
        C.ABROSD[id] = C.ABROSD[id] / C.DENS[id]
        C.ABPLAD[id] = C.ABPLAD[id] / C.DENS[id]

    return


def coolrt():
    """Evaluation of cooling and heating rates for each ion

    Corresponds to tlusty208.f lines 43031-43133. No dummies.
    """
    pi4 = 4.0 * 3.14159265e0  # parameter (pi4=4.*3.14159265d0)
    clht1 = np.zeros(MDEPTH + 1)
    clht2 = np.zeros(MDEPTH + 1)
    clht3 = np.zeros(MDEPTH + 1)
    clrat = np.zeros((MION + 1, MDEPTH + 1))
    htrat = np.zeros((MION + 1, MDEPTH + 1))

    for id in range(1, C.ND + 1):
        for ion in range(1, C.NION + 1):
            clrat[ion, id] = 0.0
            htrat[ion, id] = 0.0
        clht1[id] = 0.0
        clht2[id] = 0.0
        clht3[id] = 0.0

    for ij in range(1, C.NFREQ + 1):
        if C.IJX[ij] != -1:
            opacfa(ij)
            rtefr1(ij)
            for id in range(1, C.ND + 1):
                for ion in range(1, C.NION + 1):
                    clrat[ion, id] = clrat[ion, id] + C.W[ij] * C.EMISTI[ion, id]
                    htrat[ion, id] = (htrat[ion, id]
                                      + C.W[ij] * C.ABSOTI[ion, id] * C.RAD1[id])
                em = C.EMIS1[id] + C.SCAT1[id] * C.RAD1[id]
                clht2[id] = clht2[id] + C.W[ij] * (em - C.ABSO1[id] * C.RAD1[id])
                clht3[id] = clht3[id] + C.W[ij] * C.EMIS1[id]

            if C.IPOPAC == 1:
                if ij <= C.NFREQC:
                    # 685 format(i5,1pe15.7/(1p8e10.3))
                    write_line(85, f'{ij:5d}{C.FREQ[ij]:15.7e}')
                    _vals = [C.ABSOC1[id] / C.DENS[id]
                             for id in range(1, C.ND + 1)]
                    for _k in range(0, len(_vals), 8):
                        write_line(85, ''.join(f'{v:10.3e}'
                                               for v in _vals[_k:_k + 8]))
            if C.IPOPAC == 2:
                if ij <= C.NFREQC:
                    # 686 format(i5,1pe15.7)
                    write_line(87, f'{ij:5d}{C.FREQ[ij]:15.7e}')
                    taud = C.ABSO1[1] * C.DEDM1
                    for id in range(1, C.ND + 1):
                        if id > 1:
                            taud = (taud + C.DELDMZ[id - 1]
                                    * (C.ABSOT[id - 1] + C.ABSOT[id]))
                    # TODO(port): taud unused after computation (as in the original; apparently unfinished code)

    if C.ICOOLP <= 0:
        return

    for id in range(1, C.ND + 1):
        for ion in range(1, C.NION + 1):
            clht1[id] = clht1[id] + clrat[ion, id] - htrat[ion, id]
        # 1060 FORMAT(I5,1P3E14.6)
        write_line(86, f'{id:5d}{clht1[id] * pi4:14.6e}'
                       f'{clht2[id] * pi4:14.6e}{clht3[id] * pi4:14.6e}')

    if C.ICOOLP < 2:
        return

    for id in range(1, C.ND + 1):
        # 1071 FORMAT(i5/(1P6E13.5))
        write_line(87, f'{id:5d}')
        _vals = [(clrat[ion, id] - htrat[ion, id]) * pi4
                 for ion in range(1, C.NION + 1)]
        for _k in range(0, len(_vals), 6):
            write_line(87, ''.join(f'{v:13.5e}' for v in _vals[_k:_k + 6]))

    if C.ICOOLP < 10:
        return
    # 1070 FORMAT(2I5)
    write_line(87, f'{C.ND:5d}{C.NION:5d}')
    iofe2 = 0
    for ion in range(1, C.NION + 1):
        nn1 = C.NFIRST[ion]
        iat2 = C.IATM[nn1]
        if C.NUMAT[iat2] == 26 and C.IZ[ion] == 2:
            iofe2 = ion
    funits[8].seek(0)  # REWIND 8
    ndr = int(read_line(8).split()[0])  # READ(8,*) NDR
    _l = read_line(8).split()           # READ(8,*) TTR,RSR
    ttr = float(_l[0])
    rsr = float(_l[1])
    for id in range(C.ND, 0, -1):
        rsr = float(read_line(8).split()[0])  # READ(8,*) RSR
        # 1071 FORMAT(i5/(1P6E13.5))
        # TODO(port): original writes real RSR with i5 (format/type mismatch); truncated to int here as literal translation
        write_line(88, f'{int(rsr):5d}')
        write_line(88, f'{clrat[iofe2, id]:13.5e}')

    return


def opacfa(ij):
    """Absorption, emission, and scattering coefficients
    at frequency IJ and for all depths

    Saves additionally contributions per ion (for computing
     ionic cooling and heating rates, see routine COOLRT)

    Input: IJ   opacity and emissivity is calculated for the
                frequency points with index IJ
    Output: ABSO1 -  array of absorption coefficient
            EMIS1 -  array of emission coefficient
            SCAT1 -  array of scattering coefficient (all scattering
                      mechanisms except electron scattering)

    Corresponds to tlusty208.f lines 43141-43463. No scalar dummies modified; no return.
    """
    C14 = 2.99793e14
    CFF1 = 1.3727e-25  # PARAMETER (C14=..., CFF1=...); CFF1 unused in the original code

    # initialize
    if C.icompt > 0:
        for id in range(1, C.ND + 1):
            C.ELSCAT[id] = C.ELEC[id] * C.SIGEC[ij]

    for id in range(1, C.ND + 1):
        C.ABSO1[id] = C.ELSCAT[id]
        C.EMIS1[id] = 0.0
        C.SCAT1[id] = C.ELSCAT[id]
        C.ABSOC1[id] = C.ABSO1[id]
        C.EMISC1[id] = 0.0
        for ion in range(1, C.NION + 1):
            C.ABSOTI[ion, id] = 0.0
            C.EMISTI[ion, id] = 0.0

    # basic frequency- and depth-dependent quantities
    fr = C.FREQ[ij]
    frinv = UN / fr
    fr3inv = frinv * frinv * frinv
    lfre = fr > C.frtabm
    for id in range(1, C.ND + 1):
        C.XKF[id] = math.exp(-C.HKT1[id] * fr)
        C.XKF1[id] = UN - C.XKF[id]
        C.XKFB[id] = C.XKF[id] * C.BNUE[ij]

    # ********  1a. bound-free contribution - without dielectronic rec.
    if C.IFDIEL == 0:
        for ibft in range(1, C.NTRANC + 1):
            itr = C.ITRBF[ibft]
            sg = cross(ibft, ij)  # CROSS is a FUNCTION (tlusty208.f line 35158)
            ii = C.ILOW[itr]
            jj = C.IUP[itr]  # jj unused in the original code
            iad = C.iadop[C.IATM[ii]]
            if sg > 0.0 and (iad == 0 or (iad > 0 and lfre)):
                izz = C.IZ[C.IEL[ii]]
                imer = C.IMRG[ii]
                for id in range(1, C.ND + 1):
                    sgd = sg
                    if C.MCDW[itr] > 0:
                        _fr, _fr0, id, _izz, dw1 = \
                            dwnfr2(fr, C.FR0[itr], id, izz, 0.0)
                        C.DWF1[C.MCDW[itr], id] = dw1
                        sgd = sg * dw1
                    if C.ifwop[ii] < 0:
                        _fi, _f3, _im, id, sgme1 = \
                            sgmer1(frinv, fr3inv, imer, id, 0.0)
                        C.SGMG[imer, id] = sgme1
                        sgd = sgme1
                    emisbf = sgd * C.EMTRA[itr, id]
                    C.ABSO1[id] = C.ABSO1[id] + sgd * C.ABTRA[itr, id]
                    C.EMIS1[id] = C.EMIS1[id] + emisbf
                    C.ABSOTI[C.IEL[ii], id] = (C.ABSOTI[C.IEL[ii], id]
                                               + sgd * C.ABTRA[itr, id])
                    C.EMISTI[C.IEL[ii], id] = C.EMISTI[C.IEL[ii], id] + emisbf
    else:
        # ********  1b. bound-free contribution - with dielectronic rec.
        sg = 0.0  # TODO(port): in branch 1b the original never assigns SG
                  # before if(sg.gt.0...) (stale value from previous loop); use 0 here
        for ibft in range(1, C.NTRANC + 1):
            itr = C.ITRBF[ibft]
            ii = C.ILOW[itr]
            jj = C.IUP[itr]  # jj unused in the original code
            iad = C.iadop[C.IATM[ii]]
            if sg > 0.0 and (iad == 0 or (iad > 0 and lfre)):
                izz = C.IZ[C.IEL[ii]]
                imer = C.IMRG[ii]
                for id in range(1, C.ND + 1):
                    sg = crossd(ibft, ij, id)  # CROSSD is a FUNCTION (line 35181)
                    if sg > 0.0:
                        sgd = sg
                        if C.MCDW[itr] > 0:
                            _fr, _fr0, id, _izz, dw1 = \
                                dwnfr2(fr, C.FR0[itr], id, izz, 0.0)
                            C.DWF1[C.MCDW[itr], id] = dw1
                            sgd = sg * dw1
                        if C.ifwop[ii] < 0:
                            _fi, _f3, _im, id, sgme1 = \
                                sgmer1(frinv, fr3inv, imer, id, 0.0)
                            C.SGMG[imer, id] = sgme1
                            sgd = sgme1
                        emisbf = sgd * C.EMTRA[itr, id]
                        C.ABSO1[id] = C.ABSO1[id] + sgd * C.ABTRA[itr, id]
                        C.EMIS1[id] = C.EMIS1[id] + emisbf
                        C.ABSOTI[C.IEL[ii], id] = (C.ABSOTI[C.IEL[ii], id]
                                                   + sgd * C.ABTRA[itr, id])
                        C.EMISTI[C.IEL[ii], id] = (C.EMISTI[C.IEL[ii], id]
                                                   + emisbf)

    # ******** 2. free-free contribution
    for ion in range(1, C.NION + 1):
        it = C.ITRA[C.NNEXT[ion], C.NNEXT[ion]]
        iad = C.iadop[C.IATM[C.NNEXT[ion]]]
        if iad > 0 and not lfre:
            continue  # GO TO 40

        # hydrogenic with Gaunt factor = 1
        if it == 1:
            for id in range(1, C.ND + 1):
                sf1 = C.SFF3[ion, id] * fr3inv
                sf2 = C.SFF2[ion, id]
                if fr < C.FF[ion]:
                    sf2 = UN / C.XKF[id]
                absoff = sf1 * sf2
                C.ABSO1[id] = C.ABSO1[id] + absoff
                C.EMIS1[id] = C.EMIS1[id] + absoff
                C.ABSOTI[ion, id] = C.ABSOTI[ion, id] + absoff
                C.EMISTI[ion, id] = C.EMISTI[ion, id] + absoff

        # hydrogenic with exact Gaunt factor
        elif it == 2:
            for id in range(1, C.ND + 1):
                sf1 = C.SFF3[ion, id] * fr3inv
                sf2 = C.SFF2[ion, id]
                if fr < C.FF[ion]:
                    sf2 = UN / C.XKF[id]
                x = C14 * C.CHARG2[ion] / fr
                sf2 = sf2 - UN + gfree1(id, x)
                absoff = sf1 * sf2
                C.ABSO1[id] = C.ABSO1[id] + absoff
                C.EMIS1[id] = C.EMIS1[id] + absoff
                C.ABSOTI[ion, id] = C.ABSOTI[ion, id] + absoff
                C.EMISTI[ion, id] = C.EMISTI[ion, id] + absoff

        # H minus free-free opacity
        elif it == 3:
            for id in range(1, C.ND + 1):
                absoff = (sffhmi(C.POPUL[C.NFIRST[C.IELH], id], fr, C.TEMP[id])
                          * C.ELEC[id])
                C.ABSO1[id] = C.ABSO1[id] + absoff
                C.EMIS1[id] = C.EMIS1[id] + absoff
                C.ABSOTI[ion, id] = C.ABSOTI[ion, id] + absoff
                C.EMISTI[ion, id] = C.EMISTI[ion, id] + absoff

        # special evaluation of the cross-section
        elif it < 0:
            for id in range(1, C.ND + 1):
                absoff = (ffcros(ion, it, C.TEMP[id], fr)
                          * C.POPUL[C.NNEXT[ion], id] * C.ELEC[id])
                C.ABSO1[id] = C.ABSO1[id] + absoff
                C.EMIS1[id] = C.EMIS1[id] + absoff
                C.ABSOTI[ion, id] = C.ABSOTI[ion, id] + absoff
                C.EMISTI[ion, id] = C.EMISTI[ion, id] + absoff
        # label 40

    # ********  3. - additional continuum opacity (OPADD)
    if C.IOPADD != 0:
        icall = 1
        for id in range(1, C.ND + 1):
            opadd(0, icall, ij, id)
            C.ABSO1[id] = C.ABSO1[id] + C.ABAD
            C.EMIS1[id] = C.EMIS1[id] + C.EMAD
            C.SCAT1[id] = C.SCAT1[id] + C.SCAD
            C.ABSOTI[C.IELH, id] = C.ABSOTI[C.IELH, id] + C.ABAD
            C.EMISTI[C.IELH, id] = C.EMISTI[C.IELH, id] + C.EMAD

    for id in range(1, C.ND + 1):
        C.ABSOC1[id] = C.ABSO1[id]
        C.EMISC1[id] = C.EMIS1[id]
    if C.ICOOLP != 0:  # negation of IF(ICOOLP.EQ.0) GO TO 500

        # ********  4. - opacity and emissivity in lines
        if C.ISPODF == 0:
            if C.IJLIN[ij] > 0:
                # the "primary" line at the given frequency
                itr = C.IJLIN[ij]
                iad = C.iadop[C.IATM[C.ILOW[itr]]]
                if iad == 0 or (lfre and iad > 0):
                    ion = C.IEL[C.ILOW[itr]]
                    for id in range(1, C.ND + 1):
                        sg = C.PRFLIN[id, ij]
                        C.ABSO1[id] = C.ABSO1[id] + sg * C.ABTRA[itr, id]
                        C.EMIS1[id] = C.EMIS1[id] + sg * C.EMTRA[itr, id]
                        C.ABSOTI[ion, id] = (C.ABSOTI[ion, id]
                                             + sg * C.ABTRA[itr, id])
                        C.EMISTI[ion, id] = (C.EMISTI[ion, id]
                                             + sg * C.EMTRA[itr, id])
            if C.NLINES[ij] > 0:  # negation of IF(NLINES(IJ).LE.0) GO TO 200
                # the "overlapping" lines at the given frequency
                for ilint in range(1, C.NLINES[ij] + 1):  # DO 100
                    itr = C.ITRLIN[ilint, ij]
                    iad = C.iadop[C.IATM[C.ILOW[itr]]]
                    if iad > 0 and not lfre:
                        continue  # GO TO 100
                    if C.LINEXP[itr]:
                        continue  # GO TO 100
                    ij0 = C.IFR0[itr]
                    for ijt in range(C.IFR0[itr], C.IFR1[itr] + 1):
                        if C.FREQ[ijt] <= fr:
                            ij0 = ijt
                            break  # GO TO 70
                    # label 70
                    ij1 = ij0 - 1
                    a1 = (fr - C.FREQ[ij0]) / (C.FREQ[ij1] - C.FREQ[ij0])
                    a2 = UN - a1
                    ion = C.IEL[C.ILOW[itr]]
                    for id in range(1, C.ND + 1):
                        sg = a1 * C.PRFLIN[id, ij1] + a2 * C.PRFLIN[id, ij0]
                        C.ABSO1[id] = C.ABSO1[id] + sg * C.ABTRA[itr, id]
                        C.EMIS1[id] = C.EMIS1[id] + sg * C.EMTRA[itr, id]
                        C.ABSOTI[ion, id] = (C.ABSOTI[ion, id]
                                             + sg * C.ABTRA[itr, id])
                        C.EMISTI[ion, id] = (C.EMISTI[ion, id]
                                             + sg * C.EMTRA[itr, id])
                    # label 100
            # label 200

        # Opacity sampling option
        else:
            if C.NLINES[ij] > 0:  # negation of IF(NLINES(IJ).LE.0) GO TO 400
                for ilint in range(1, C.NLINES[ij] + 1):  # DO 300
                    itr = C.ITRLIN[ilint, ij]
                    iad = C.iadop[C.IATM[C.ILOW[itr]]]
                    if iad > 0 and not lfre:
                        continue  # GO TO 300
                    ion = C.IEL[C.ILOW[itr]]
                    kj = ij - C.IFR0[itr] + C.KFR0[itr]
                    indxpa = abs(C.INDEXP[itr])  # IABS → abs
                    if indxpa != 3 and indxpa != 4:
                        for id in range(1, C.ND + 1):
                            sg = C.PRFLIN[id, kj]
                            C.ABSO1[id] = C.ABSO1[id] + sg * C.ABTRA[itr, id]
                            C.EMIS1[id] = C.EMIS1[id] + sg * C.EMTRA[itr, id]
                            C.ABSOTI[ion, id] = (C.ABSOTI[ion, id]
                                                 + sg * C.ABTRA[itr, id])
                            C.EMISTI[ion, id] = (C.EMISTI[ion, id]
                                                 + sg * C.EMTRA[itr, id])
                    else:
                        for id in range(1, C.ND + 1):
                            kjd = C.JIDI[id]
                            sg = math.exp(C.XJID[id] * C.SIGFE[kjd, kj]
                                          + (UN - C.XJID[id])
                                          * C.SIGFE[kjd + 1, kj])
                            C.ABSO1[id] = C.ABSO1[id] + sg * C.ABTRA[itr, id]
                            C.EMIS1[id] = C.EMIS1[id] + sg * C.EMTRA[itr, id]
                            C.ABSOTI[ion, id] = (C.ABSOTI[ion, id]
                                                 + sg * C.ABTRA[itr, id])
                            C.EMISTI[ion, id] = (C.EMISTI[ion, id]
                                                 + sg * C.EMTRA[itr, id])
                    # label 300
            # label 400
    # label 500

    # ----------------------------
    # total opacity and emissivity
    # ----------------------------
    for id in range(1, C.ND + 1):
        C.ABSO1[id] = C.ABSO1[id] - C.EMIS1[id] * C.XKF[id]
        C.ABSOC1[id] = C.ABSOC1[id] - C.EMISC1[id] * C.XKF[id]
        for ion in range(1, C.NION + 1):
            C.ABSOTI[ion, id] = C.ABSOTI[ion, id] - C.EMISTI[ion, id] * C.XKF[id]
        C.EMIS1[id] = C.EMIS1[id] * C.XKFB[id]
        C.EMISC1[id] = C.EMISC1[id] * C.XKFB[id]
        for ion in range(1, C.NION + 1):
            C.EMISTI[ion, id] = C.EMISTI[ion, id] * C.XKFB[id]
        C.ABSOT[id] = C.ABSO1[id]
    if C.IZSCAL == 0:
        for id in range(1, C.ND + 1):
            C.ABSOT[id] = C.ABSO1[id] * C.DENS1[id]

    if C.IFPRD > 0:
        prd(ij)

    return


def visini():
    """Auxiliary procedure for RESOLV
    initialization of necessary quantities for treating the viscosity
    in disks

    Corresponds to tlusty208.f lines 43470-43576. No dummies.
    """
    amuv0 = C.dmvisc**(C.zeta0 + UN)
    amuv1 = UN - amuv0
    gp = 0.0
    gn = UN  # gp/gn unused in the original code after assignment
    if C.INMP > 0:
        gp = UN
        gn = 0.0

    if C.ivisc <= 1:
        x = 0.0
        for id in range(1, C.ND + 1):
            dmd = C.DM[1]
            if id > 1:
                dmd = (C.DM[id] + C.DM[id - 1]) * HALF
            if C.DM[id] <= C.dmvisc * C.DM[C.ND]:
                C.VISCD[id] = ((UN - C.fractv) * (C.zeta1 + UN)
                               / C.dmvisc**(C.zeta1 + UN)
                               * (C.DM[id] / C.DM[C.ND])**C.zeta1)
                C.THETAV[id] = ((UN - C.fractv)
                                * (dmd / C.dmvisc / C.DM[C.ND])**(C.zeta1 + UN))
            else:
                C.VISCD[id] = (C.fractv * (C.zeta0 + UN) / amuv1
                               * (C.DM[id] / C.DM[C.ND])**C.zeta0)
                C.THETAV[id] = ((UN - C.fractv)
                                + C.fractv * ((dmd / C.DM[C.ND])**(C.zeta0 + UN)
                                              - amuv0) / amuv1)
            C.TVISC[id] = C.EDISC * C.VISCD[id] * C.DENS[id]
            C.DTVIST[id] = 0.0
            C.DTVISR[id] = C.EDISC * C.VISCD[id] * C.WMM[id]
            C.DTVISN[id] = 0.0
            if id > 1:
                x = (x + HALF * (C.TVISC[id] / C.DENS[id]
                                 + C.TVISC[id - 1] / C.DENS[id - 1])
                     * (C.DM[id] - C.DM[id - 1]))
        vtot = x
        x = 0.0
        if C.ITER == C.NITER:
            # 600 format(/'    ID    DM          TVISC   THETAV(orig)   THETAV',
            #            '      VISCD       ALPHA'/)
            print()
            print('    ID    DM          TVISC   THETAV(orig)   THETAV'
                  '      VISCD       ALPHA')
            print()
        for id in range(1, C.ND + 1):
            an = C.DENS[id] / C.WMM[id] + C.ELEC[id]
            C.PGS[id] = BOLK * C.TEMP[id] * an
            if id > 1:
                x = (x + HALF * (C.TVISC[id] / C.DENS[id]
                                 + C.TVISC[id - 1] / C.DENS[id - 1])
                     * (C.DM[id] - C.DM[id - 1]))
            alp = C.TVISC[id] / C.omeg32 / C.PGS[id] * 12.5664
            # 601 format(i5,1p6e12.4)
            _l601 = (f'{id:5d}'
                     + ''.join(f'{v:12.4e}' for v in
                               (C.DM[id], C.TVISC[id], C.THETAV[id],
                                x / vtot, C.VISCD[id], alp)))
            if C.ITER == C.NITER:
                print(_l601)
            write_line(96, _l601)
            if id == C.ND:
                write_line(96, f'{id:5d}'
                           + ''.join(f'{v:12.4e}' for v in
                                     (C.EDISC, C.VISCD[id], C.DENS[id],
                                      C.PGS[id], C.omeg32)))
    elif C.ivisc == 2:
        x = 0.0
        C.THETAV[1] = 0.0
        for id in range(1, C.ND + 1):
            an = C.DENS[id] / C.WMM[id] + C.ELEC[id]
            C.PGS[id] = BOLK * C.TEMP[id] * an
            C.TVISC[id] = C.omeg32 * C.alphav * C.PGS[id] / 12.5664
            C.DTVIST[id] = C.TVISC[id] / C.TEMP[id]
            C.DTVISN[id] = C.TVISC[id] / an
            C.DTVISR[id] = 0.0
            if id > 1:
                # c  X=X+HALF*(TVISC(ID)+TVISC(ID-1))*(DM(ID)-DM(ID-1))
                x = (x + HALF * (C.TVISC[id] / C.DENS[id]
                                 + C.TVISC[id - 1] / C.DENS[id - 1])
                     * (C.DM[id] - C.DM[id - 1]))
        vtot = x
        x = 0.0
        # 602 format(/'    ID    DM          TVISC     THETAV        PGAS',
        #            '       VISCD       ALPHA'/)
        print()
        print('    ID    DM          TVISC     THETAV        PGAS'
              '       VISCD       ALPHA')
        print()
        for id in range(1, C.ND + 1):
            if id > 1:
                # c  X=X+HALF*(TVISC(ID)+TVISC(ID-1))*(DM(ID)-DM(ID-1))
                x = (x + HALF * (C.TVISC[id] / C.DENS[id]
                                 + C.TVISC[id - 1] / C.DENS[id - 1])
                     * (C.DM[id] - C.DM[id - 1]))
            C.THETAV[id] = x / vtot
            C.VISCD[id] = C.TVISC[id] / C.DENS[id] / C.EDISC
            # 601 format(i5,1p6e12.4)
            _l601 = (f'{id:5d}'
                     + ''.join(f'{v:12.4e}' for v in
                               (C.DM[id], C.TVISC[id], C.THETAV[id],
                                C.PGS[id], C.VISCD[id], C.alphav)))
            print(_l601)
            write_line(96, _l601)
            if id == C.ND:
                write_line(96, f'{id:5d}'
                           + ''.join(f'{v:12.4e}' for v in
                                     (C.EDISC, C.VISCD[id], C.DENS[id],
                                      C.PGS[id], C.omeg32)))
    return


def dmeval():
    """Auxiliary procedure for RESOLV  - for disks
    recomputation of the m-scale in the case where z-scale is the
    basic scale

    Corresponds to tlusty208.f lines 43583-43651. No dummies.
    """
    dma = np.zeros(MDEPTH + 1)
    dmb = np.zeros(MDEPTH + 1)

    # total pressure and gas pressure
    for id in range(1, C.ND + 1):
        pturb = HALF * C.DENS[id] * C.VTURB[id] * C.VTURB[id]
        pgs0 = (C.DENS[id] / C.WMM[id] + C.ELEC[id]) * BOLK * C.TEMP[id]
        C.PGS[id] = pgs0
        ptotl0 = C.PGS[id] + C.PRADT[id] + pturb
        C.PTOTAL[id] = ptotl0

    # mass at the first depth point
    id = 1
    grd = 0.0
    for ij in range(1, C.NFREQE + 1):
        ijt = C.IJFR[ij]
        fluxw = C.W[ijt] * C.FH[ijt] * C.RADEX[ij, id]
        grd = grd + fluxw * C.ABSOEX[ij, id]
    # Note: HG1/HR1 here are local quantities (DMEVAL does not declare /PRSAUX/)
    hg1 = math.sqrt(TWO * C.PGS[1] / C.DENS[1] / C.QGRAV)
    hr1 = PCK / C.QGRAV * (grd + C.FPRD[1]) / C.DENS[1]
    if C.ITER == 1:
        C.pgas0 = C.PGS[1]
    x = (C.ZD[1] - hr1) / hg1
    if x < 3.0:
        if x < 0.0:
            x = 0.0
        f1 = 8.86226925e-1 * math.exp(x * x) * erfcx(x)
    else:
        f1 = HALF * (UN - HALF / x / x) / x

    dma[1] = hg1 * C.DENS[1] * f1
    dmb[1] = dma[1]

    # recompute the DM scale
    # 600 format(/'   ID          ZD         DM(old)  DMA     DMB'/)
    print()
    print('   ID          ZD         DM(old)  DMA     DMB')
    print()
    for id in range(1, C.ND + 1):
        if id > 1:
            dmb[id] = C.DM[id]
            dma[id] = (dma[id - 1] - (C.ZD[id] - C.ZD[id - 1]) * TWO
                       / (UN / C.DENS[id] + UN / C.DENS[id - 1]))
            dmb[id] = (dmb[id - 1] - (C.ZD[id] - C.ZD[id - 1])
                       * (C.DENS[id] + C.DENS[id - 1]) * HALF)
        # 601 format(i5,1p4e12.4)
        print(f'{id:5d}'
              + ''.join(f'{v:12.4e}' for v in
                        (C.ZD[id], C.DM[id], dma[id], dmb[id])))
        # c       DM(ID)=DMB(ID)
        C.DM[id] = dma[id]
    C.DMTOT = C.DM[C.ND]
    C.EDISC = SIG4P * C.TEFF**4 / C.DMTOT
    return


def greyd():
    """(no header comment in the original code, only a separator line)
    Corresponds to tlusty208.f lines 43658-43723. No dummies.
    """
    ERRM0 = 1.0e-3
    NTRM = 50  # PARAMETER (ERRM0=1.E-3, NTRM=50)

    chi0 = 20.0
    if C.TEFF > 10000.0:
        xion = 2.0
    elif C.TEFF < 6000.0:
        xion = 1.0
    else:
        xion = 1.0 + (C.TEFF - 6000.0) / 4000.0
    C.anerel = 1.0 - 1.0 / xion

    dmp = 0.0
    id = 1
    c1 = BOLK * xion / C.WMM[id]
    c2 = 3.1415926 / 2.0 / C.QGRAV
    c3 = math.sqrt(c1 * c2)
    c4 = C.wbarm * C.omeg32 / C.alphav
    c5 = c4 / c1
    c6 = c1 / C.wbarm / C.omeg32  # c6 unused in the original code after assignment

    itrm = 0
    an = 0.0
    ane = 0.0        # initial value for output (RHONEN output)
    opros = 0.0
    oppla = 0.0      # initial value for output (MEANOP output)
    while True:
        # label 10
        itrm = itrm + 1
        c1 = BOLK * xion / C.WMM[id]
        c3 = math.sqrt(c1 * c2)
        c5 = c4 / c1
        t = (0.375 * C.TEFF**4 * chi0 * c5)**0.2
        dm0 = c5 / t
        rho = dm0 / math.sqrt(t) / c3
        C.TEMP[id] = t
        C.DENS[id] = rho
        id, t, rho, an, ane = rhonen(id, t, rho, an, ane)
        C.ELEC[id] = ane
        xion = an / (an - ane)
        wnstor(id)
        steqeq(id, C.POP, 1)

        # evaluation of the Rosseland and Planck mean opacities
        # for the new values of temperature, electron density, and
        # populations (OPROS - Rosseland opacity per 1 cm**3; OPPLA - Planck
        # mean opacity per 1 cm**3)
        # OPACF0 uses dummy ID as a DO loop variable in the opacity
        # sampling branch (tlusty208.f lines 33707/33713) -> unpack all
        # scalar dummies per convention; NFRQ unmodified, use a temp var
        id, _nfrq = opacf0(id, C.NFREQ)
        t, opros, oppla = meanop(t, C.ABSO, C.SCAT, opros, oppla)
        abros = opros / C.DENS[id]
        abpla = oppla / C.DENS[id]
        if abpla < C.ABPMIN:
            abpla = C.ABPMIN
        chi0 = (abros + chi0) / 2.0
        # 601 FORMAT(i5,1p8e9.2)
        print(f'{itrm:5d}'
              + ''.join(f'{v:9.2e}' for v in
                        (t, dm0, rho, chi0, abros, chi0 * dm0, xion, ane)))
        errm = abs(dm0 - dmp) / dm0
        dmp = dm0
        if errm > ERRM0 and itrm < NTRM:
            continue  # GO TO 10
        break

    C.DMTOT = dm0
    return


def rhonen(id, t, rho, an, ane):
    """iterative determination of N and Ne from given T and RHO

    Input:  T   - temperature
            RHO - mass density
    Output: AN  - total particle density
            ANE - elctron density
            ENRG- internal energy
            ENTT- entropy

    Corresponds to tlusty208.f lines 43729-43770.
    Modifies scalar dummies AN, ANE; returns (id, t, rho, an, ane) per convention.
    """
    it = 0
    # anerel is not declared in any COMMON (an implicit local in each Fortran
    # subroutine, relying on static-storage stale values) -> read via getattr(C, 'anerel', 0)
    if id == 1 and getattr(C, 'anerel', 0) == 0.0:
        C.anerel = 0.5
        if t < 9000.0:
            C.anerel = 0.4
        if t < 8000.0:
            C.anerel = 0.1
        if t < 7000.0:
            C.anerel = 0.01
        if t < 6000.0:
            C.anerel = 0.001
        if t < 5500.0:
            C.anerel = 0.0001
        if t < 5000.0:
            C.anerel = 1.0e-5
        if t < 4000.0:
            C.anerel = 1.0e-6
    wm = C.WMM[id] * (UN - getattr(C, 'anerel', 0)) / HMASS
    wm0 = wm
    enrgi = 0.0
    entt = 0.0  # Fortran actual argument uninitialized; Python needs an initial value (ELDENS output)
    while True:
        # label 10
        it = it + 1
        an = rho / wm / HMASS
        ane0 = getattr(C, 'anerel', 0) * an
        wm0 = wm
        id, t, an, ane, enrgi, entt, wm, _ipri = \
            eldens(id, t, an, ane, enrgi, entt, wm, 0)
        C.anerel = ane / an
        if (abs((ane - ane0) / ane0) < 1.0e-5
                and abs((wm - wm0) / wm0) < 1.0e-5):
            break  # GO TO 20
        if it < 30:
            continue  # GO TO 10
        break  # fall through to label 20 after 30 iterations
    # label 20
    return id, t, rho, an, ane


def quasim(ij):
    """quasi-molecular opacity for Lyman alpha, beta, gamma

    Corresponds to tlusty208.f lines 43777-43833. No scalar dummies modified; no return.
    """
    sgd = np.zeros(MDEPTH + 1)

    if C.iquasi <= 0:
        return
    fr = C.FREQ[ij]
    wlam = 2.997925e18 / fr
    if wlam < 911.0 or wlam > 1727.0:
        return
    ii = C.NFIRST[C.IELH]

    for jup in range(2, C.iquasi + 2):
        jj = ii + 1
        itr = C.ITRA[ii, jj]
        sg = 0.0  # initial value for output (ALLARD output dummy prof)
        for id in range(1, C.ND + 1):
            anp = C.POPUL[C.NNEXT[C.IELH], id]
            t = C.TEMP[id]
            if C.tqmprf > 0.0:
                t = C.tqmprf
            wlam, t, _hn, anp, sg, _iq, jup = \
                allard(wlam, t, C.POPUL[ii, id], anp, sg, 1, jup)
            sgd[id] = sg
        if C.IJLIN[ij] != itr:
            sg0 = 0.0
            for ilint in range(1, C.NLINES[ij] + 1):
                itt = C.ITRLIN[ilint, ij]
                if itt == itr:
                    ij0 = C.IFR0[itr]
                    for ijt in range(C.IFR0[itr], C.IFR1[itr] + 1):
                        if C.FREQ[ijt] <= fr:
                            ij0 = ijt
                            break  # GO TO 20
                    # label 20
                    ij1 = ij0 - 1
                    a1 = (fr - C.FREQ[ij0]) / (C.FREQ[ij1] - C.FREQ[ij0])
                    a2 = UN - a1
                    for id in range(1, C.ND + 1):
                        sg0 = a1 * C.PRFLIN[id, ij1] + a2 * C.PRFLIN[id, ij0]
                    # TODO(port): sg0 unused after computation (as in the original)
        for id in range(1, C.ND + 1):
            C.ABSO1[id] = C.ABSO1[id] + sgd[id] * C.ABTRA[itr, id]
            C.EMIS1[id] = C.EMIS1[id] + sgd[id] * C.EMTRA[itr, id]

    return


def getlal():
    """getlal reads in the profile functions for Lyman alpha, beta, gamma,
    and Balmer alpha, including the quasi-molecular satellites;
    valid for first and second order in neutral and ionized H density
    modified routine provided originally by D. Koester

    Corresponds to tlusty208.f lines 43838-43944. No dummies.
    TODO(port): free-format READ parsed as "one record per line"; if a record
    in the data file spans multiple lines, extra handling is needed.
    """
    NXMAX = 1400
    NNMAX = 5
    NTAMAX = 6  # parameter (NXMAX=1400,NNMAX=5,NTAMAX=6)

    # Lyman alpha
    C.nxalp = 0
    C.nunalp = 67
    if C.nunalp > 0:
        # open(unit=nunalp,file='./data/laquasi.dat',status='old')
        open_unit(C.nunalp, './data/laquasi.dat', 'r')
        # read(nunalp,*) nxalp,stnnea,stncha,vneua,vchaa
        _l = read_line(C.nunalp).split()
        C.nxalp = int(_l[0])
        C.stnnea = float(_l[1])
        C.stncha = float(_l[2])
        C.vneua = float(_l[3])
        C.vchaa = float(_l[4])
        for i in range(1, C.nxalp + 1):
            # read(nunalp,*) xlalp(i),(plalp(i,j),j=1,NNMAX)
            _l = read_line(C.nunalp).split()
            C.xlalp[i] = float(_l[0])
            for j in range(1, NNMAX + 1):
                C.plalp[i, j] = float(_l[j])
        close_unit(C.nunalp)
        C.stnnea = 10.0**C.stnnea
        C.stncha = 10.0**C.stncha
        C.iwarna = 0
    elif C.nunalp < 0:
        # input of temperature-dependent profile
        nualp = -C.nunalp
        C.ntalpd = int(read_line(nualp).split()[0])  # read(nualp,*) ntalpd
        for it in range(1, C.ntalpd + 1):
            C.talpd[it] = float(read_line(nualp).split()[0])
            # read(nualp,*) nxalpd(it),stnead(it),stnchd(it),vneuad(it),
            #               vchaad(it)
            _l = read_line(nualp).split()
            C.nxalpd[it] = int(_l[0])
            C.stnead[it] = float(_l[1])
            C.stnchd[it] = float(_l[2])
            C.vneuad[it] = float(_l[3])
            C.vchaad[it] = float(_l[4])
            for i in range(1, C.nxalpd[it] + 1):
                # read(nualp,*) xlalpd(i,it),(plalpd(i,j,it),j=1,NNMAX)
                _l = read_line(nualp).split()
                C.xlalpd[i, it] = float(_l[0])
                for j in range(1, NNMAX + 1):
                    C.plalpd[i, j, it] = float(_l[j])
            C.stnead[it] = 10.0**C.stnead[it]
            C.stnchd[it] = 10.0**C.stnchd[it]
        close_unit(nualp)

    # Lyman beta
    C.nxbet = 0
    if C.nunbet > 0:
        C.nunbet = 67
        # open(unit=nunbet,file='./data/lbquasi.dat',status='old')
        open_unit(C.nunbet, './data/lbquasi.dat', 'r')
        _l = read_line(C.nunbet).split()
        C.nxbet = int(_l[0])
        C.stnneb = float(_l[1])
        C.stnchb = float(_l[2])
        C.vneub = float(_l[3])
        C.vchab = float(_l[4])
        for i in range(1, C.nxbet + 1):
            _l = read_line(C.nunbet).split()
            C.xlbet[i] = float(_l[0])
            for j in range(1, NNMAX + 1):
                C.plbet[i, j] = float(_l[j])
        close_unit(C.nunbet)
        C.stnneb = 10.0**C.stnneb
        C.stnchb = 10.0**C.stnchb
        C.iwarnb = 0

    # Lyman gamma
    C.nxgam = 0
    if C.nungam > 0:
        C.nungam = 67
        # open(unit=nungam,file='./data/lgquasi.dat',status='old')
        open_unit(C.nungam, './data/lgquasi.dat', 'r')
        _l = read_line(C.nungam).split()
        C.nxgam = int(_l[0])
        C.stnneg = float(_l[1])
        C.stnchg = float(_l[2])
        C.vneug = float(_l[3])
        C.vchag = float(_l[4])
        for i in range(1, C.nxgam + 1):
            _l = read_line(C.nungam).split()
            C.xlgam[i] = float(_l[0])
            for j in range(1, NNMAX + 1):
                C.plgam[i, j] = float(_l[j])
        close_unit(C.nungam)
        C.stnneg = 10.0**C.stnneg
        C.stnchg = 10.0**C.stnchg
        C.iwarng = 0

    # Balmer alpha
    C.nxbal = 0
    if C.nunbal > 0:
        C.nunbal = 67
        # TODO(port): the original has open(unit=nunalp,file='./data/lhquasi.dat')
        # here (opens nunalp instead of nunbal, likely a typo); translated literally
        open_unit(C.nunalp, './data/lhquasi.dat', 'r')
        _l = read_line(C.nunbal).split()
        C.nxbal = int(_l[0])
        C.stnnec = float(_l[1])
        C.stnchc = float(_l[2])
        C.vneuc = float(_l[3])
        C.vchac = float(_l[4])
        for i in range(1, C.nxbal + 1):
            _l = read_line(C.nunbal).split()
            C.xlbal[i] = float(_l[0])
            for j in range(1, NNMAX + 1):
                C.plbal[i, j] = float(_l[j])
        close_unit(C.nunbal)
        C.stnnec = 10.0**C.stnnec
        C.stnchc = 10.0**C.stnchc
        C.iwarnc = 0
    return


def allard(xl, t, hneutr, hcharg, prof, iq, jq):
    """quasi-molecular opacity for Lyman alpha, beta, and Balmer alpha
    modified routine provided originally by D. Koester

    Input:  xl:  wavelength in [A]
            hneutr:  neutral H particle density [cm-3]
            hcharg: ionized H particle density [cm-3]
            iq:   quantum number of the lower level
            jq:   quantum number of the upper level;
                  =2  -  Lyman alpha
                  =3  -  Lyman beta
    Output: prof:  Lyman alpha line profile, normalized to 1.0e8
            if integrated over A;
            It then renormalized by multiplying by
            8.853e-29*lambda_0^2*f_ij

    Corresponds to tlusty208.f lines 43951-44167.
    Modifies scalar dummy prof; returns (xl, t, hneutr, hcharg, prof, iq, jq) per convention.
    """
    NXMAX = 1400
    NNMAX = 5
    NTAMAX = 6  # parameter (NXMAX=1400,NNMAX=5,NTAMAX=6)
    xnorma = 8.8528e-29 * 1215.6 * 1215.6 * 0.41618
    xnormb = 8.8528e-29 * 1025.73 * 1025.7 * 0.0791
    xnormg = 8.8528e-29 * 972.53 * 972.53 * 0.0290
    xnormc = 8.8528e-29 * 6562.0 * 6562.0 * 0.6407  # parameter (...)

    prof = 0.0

    # Lyman alpha
    if iq == 1 and jq == 2:
        if C.nunalp < 0:
            xl, t, hneutr, hcharg, prof = allardt(xl, t, hneutr, hcharg, prof)
        else:
            if xl < C.xlalp[1] or xl > C.xlalp[C.nxalp]:
                return xl, t, hneutr, hcharg, prof, iq, jq
            vn1 = hneutr / C.stnnea
            vn2 = hcharg / C.stncha
            vns = vn1 * C.vneua + vn2 * C.vchaa
            if C.iwarna == 0:
                if vn1 * C.vneua > 0.3 or vn2 * C.vchaa > 0.3:
                    print('          warning: density too high for'
                          ' Lyman alpha expansion')
                    C.iwarna = 1
            vn11 = vn1 * vn1
            vn22 = vn2 * vn2
            vn12 = vn1 * vn2
            xnorm = 1.0 / (1.0 + vns + 0.5 * vns * vns)

            jl = 0
            ju = C.nxalp + 1
            while ju - jl > 1:
                # label 10
                jm = idiv(ju + jl, 2)  # Fortran integer division (ju+jl)/2
                # .EQV. → ==
                if (C.xlalp[C.nxalp] > C.xlalp[1]) == (xl > C.xlalp[jm]):
                    jl = jm
                else:
                    ju = jm
                # GO TO 10 -> continue loop
            j = jl

            if j == 0:
                j = 1
            if j == C.nxalp:
                j = j - 1
            a1 = (xl - C.xlalp[j]) / (C.xlalp[j + 1] - C.xlalp[j])
            p1 = vn1 * ((1.0 - a1) * C.plalp[j, 1] + a1 * C.plalp[j + 1, 1])
            p11 = vn11 * ((1.0 - a1) * C.plalp[j, 2] + a1 * C.plalp[j + 1, 2])
            p2 = vn2 * ((1.0 - a1) * C.plalp[j, 3] + a1 * C.plalp[j + 1, 3])
            p22 = vn22 * ((1.0 - a1) * C.plalp[j, 4] + a1 * C.plalp[j + 1, 4])
            p12 = vn12 * ((1.0 - a1) * C.plalp[j, 5] + a1 * C.plalp[j + 1, 5])
            prof = (p1 + p2 + p11 + p22 + p12) * xnorm * xnorma
            return xl, t, hneutr, hcharg, prof, iq, jq

    # Lyman beta
    if iq == 1 and jq == 3:
        if C.nxbet == 0:
            return xl, t, hneutr, hcharg, prof, iq, jq
        if xl < C.xlbet[1] or xl > C.xlbet[C.nxbet]:
            return xl, t, hneutr, hcharg, prof, iq, jq
        vn1 = hneutr / C.stnneb
        vn2 = hcharg / C.stnchb
        vns = vn1 * C.vneub + vn2 * C.vchab
        if C.iwarnb == 0:
            if vn1 * C.vneub > 0.3 or vn2 * C.vchab > 0.3:
                print('          warning: density too high for'
                      ' Lyman beta expansion')
                C.iwarnb = 1
        vn11 = vn1 * vn1
        vn22 = vn2 * vn2
        vn12 = vn1 * vn2
        xnorm = 1.0 / (1.0 + vns + 0.5 * vns * vns)

        jl = 0
        ju = C.nxbet + 1
        while ju - jl > 1:
            # label 20
            jm = idiv(ju + jl, 2)
            if (C.xlbet[C.nxbet] > C.xlbet[1]) == (xl > C.xlbet[jm]):
                jl = jm
            else:
                ju = jm
            # GO TO 20 -> continue loop
        j = jl

        if j == 0:
            j = 1
        if j == C.nxbet:
            j = j - 1
        a1 = (xl - C.xlbet[j]) / (C.xlbet[j + 1] - C.xlbet[j])
        p1 = vn1 * ((1.0 - a1) * C.plbet[j, 1] + a1 * C.plbet[j + 1, 1])
        p11 = vn11 * ((1.0 - a1) * C.plbet[j, 2] + a1 * C.plbet[j + 1, 2])
        p2 = vn2 * ((1.0 - a1) * C.plbet[j, 3] + a1 * C.plbet[j + 1, 3])
        p22 = vn22 * ((1.0 - a1) * C.plbet[j, 4] + a1 * C.plbet[j + 1, 4])
        p12 = vn12 * ((1.0 - a1) * C.plbet[j, 5] + a1 * C.plbet[j + 1, 5])
        prof = (p1 + p2 + p11 + p22 + p12) * xnorm * xnormb
        return xl, t, hneutr, hcharg, prof, iq, jq

    # Lyman gamma
    if iq == 1 and jq == 4:
        if C.nxgam == 0:
            return xl, t, hneutr, hcharg, prof, iq, jq
        if xl < C.xlgam[1] or xl > C.xlgam[C.nxgam]:
            return xl, t, hneutr, hcharg, prof, iq, jq
        vn1 = hneutr / C.stnneg
        vn2 = hcharg / C.stnchg
        vns = vn1 * C.vneug + vn2 * C.vchag
        if C.iwarng == 0:
            if vn1 * C.vneug > 0.3 or vn2 * C.vchag > 0.3:
                print('          warning: density too high for'
                      ' Lyman gamma expansion')
                C.iwarng = 1
        vn11 = vn1 * vn1
        vn22 = vn2 * vn2
        vn12 = vn1 * vn2
        xnorm = 1.0 / (1.0 + vns + 0.5 * vns * vns)

        jl = 0
        ju = C.nxgam + 1
        while ju - jl > 1:
            # label 30
            jm = idiv(ju + jl, 2)
