def allardt(xl, t, hneutr, hcharg, prof):
    """quasi-molecular opacity for Lyman alpha, with T-dependent
    profile

    Input:  xl:  wavelength in [A]
            hneutr:  neutral H particle density [cm-3]
            hcharg: ionized H particle density [cm-3]
    Output: prof:  Lyman alpha line profile, normalized to 1.0e8
            if integrated over A;
            It then renormalized by multiplying by
            8.853e-29*lambda_0^2*f_ij

    Corresponds to tlusty208.f lines 44173-44330.
    Modifies scalar dummy prof; returns (xl, t, hneutr, hcharg, prof) per convention.
    """
    NXMAX = 1400
    NNMAX = 5
    NTAMAX = 6  # parameter (NXMAX=1400,NNMAX=5,NTAMAX=6)
    xnorma = 8.8528e-29 * 1215.6 * 1215.6 * 0.41618  # parameter (xnorma=...)

    prof = 0.0

    # find the two partial tables close to actual T
    it0 = 0
    for it in range(1, C.ntalpd + 1):
        it0 = it
        if t < C.talpd[it]:
            it0 = it - 1
            break  # GO TO 10
    # label 10
    if it0 == 0:
        it0 = 1
        single = True  # GO TO 20
    elif it0 >= C.ntalpd:
        it0 = C.ntalpd
        single = True  # GO TO 20
    else:
        single = False  # GO TO 30

    if single:
        # label 20 - use only a single temperature sub-table
        if xl < C.xlalpd[1, it0] or xl > C.xlalpd[C.nxalpd[it0], it0]:
            return xl, t, hneutr, hcharg, prof
        vn1 = hneutr / C.stnead[it0]
        vn2 = hcharg / C.stnchd[it0]
        vns = vn1 * C.vneuad[it0] + vn2 * C.vchaad[it0]
        vn11 = vn1 * vn1
        vn22 = vn2 * vn2
        vn12 = vn1 * vn2
        xnorm = 1.0 / (1.0 + vns + 0.5 * vns * vns)

        jl = 0
        ju = C.nxalpd[it0] + 1
