    a1 = ((xl - C.xlalpd[j, it0])
          / (C.xlalpd[j + 1, it0] - C.xlalpd[j, it0]))
    p1 = vn1 * ((1.0 - a1) * C.plalpd[j, 1, it0]
                + a1 * C.plalpd[j + 1, 1, it0])
    p11 = vn11 * ((1.0 - a1) * C.plalpd[j, 2, it0]
                  + a1 * C.plalpd[j + 1, 2, it0])
    p2 = vn2 * ((1.0 - a1) * C.plalpd[j, 3, it0]
                + a1 * C.plalpd[j + 1, 3, it0])
    p22 = vn22 * ((1.0 - a1) * C.plalpd[j, 4, it0]
                  + a1 * C.plalpd[j + 1, 4, it0])
    p12 = vn12 * ((1.0 - a1) * C.plalpd[j, 5, it0]
                  + a1 * C.plalpd[j + 1, 5, it0])
    prof0 = (p1 + p2 + p11 + p22 + p12) * xnorm * xnorma

