#   other  : IOPLYM, icentr, icbegp (int scalars; these three are not declared in any
#            COMMON in the Fortran source - implicitly shared; read via getattr(C, 'name', 0),
#            written via C.name=...)


def rybene():
    """
    complementing partial matrices of complete linearization
    corresponding to the contribution of ALI frequencies and the
    convection to the radiative/convective equilibrium equation in
    the Rybicki formalism

    Corresponds to tlusty208.f lines 47236-47438
    """
    # COMMON/CUBCON/ACNV,BCNV,DEL,GRDADB,DELMDE,RHO,FLXTOT,GRAVD
    # COMMON/RYBMTX/RA,RB,RC,VR,UA,UB,UC,VA,VB,VC,WR,WM
    # common/deridt/dert

    # contribution from the radiative equilibrium part of the energy eq.
    flxto0 = SIG4P * C.TEFF ** 4
    for id in range(1, C.ND + 1):
        C.WR[id] = C.WR[id] + C.FCOOL[id]
        if C.IDISK == 1:
            C.WR[id] = C.WR[id] - C.REINT[id] * C.TVISC[id]
        if C.REINT[id] > 0.0:
            if id > 1:
                C.WM[id, id - 1] = (C.WM[id, id - 1]
                                    + C.AREIT[id] * C.DENS[id] * C.REINT[id])
            C.WM[id, id] = C.WM[id, id] + C.REIT[id] * C.DENS[id] * C.REINT[id]
            if C.IDISK == 1:
                C.WM[id, id] = C.WM[id, id] + C.DTVIST[id] * C.REINT[id]
            if id < C.ND:
                C.WM[id, id + 1] = (C.WM[id, id + 1]
                                    + C.CREIT[id] * C.DENS[id] * C.REINT[id])

        if C.IDISK == 0:
            C.FLXTOT = flxto0
            C.GRAVD = C.GRAV
        else:
            C.FLXTOT = flxto0 * (1.0 - C.THETAV[id])
            C.GRAVD = C.QGRAV * C.ZD[id]

        if C.REDIF[id] > 0:
            C.WR[id] = C.WR[id] + C.FLXTOT * C.REDIF[id]
            if id > 1:
                C.WM[id, id - 1] = (C.WM[id, id - 1]
                                    + C.REDTM[id] * C.REDIF[id])
            C.WM[id, id] = C.WM[id, id] + C.REDT[id] * C.REDIF[id]
            if id < C.ND:
                C.WM[id, id + 1] = (C.WM[id, id + 1]
                                    + C.REDTP[id] * C.REDIF[id])

    # contribution from convection
    if C.HMIX0 <= 0.0 or C.ICONV <= 0:
        return
    if C.dert == 0.0:
        C.dert = 0.01
    for id in range(C.IDCONZ, C.ND + 1):        # DO 10 ID=idconz,ND
        t = C.TEMP[id]
        p = C.PTOTAL[id]
        tm = C.TEMP[id - 1]
        pm = C.PTOTAL[id - 1]
        pr0 = 0.0
        # icentr is not declared in any COMMON (implicitly shared); read via getattr with default 0
        if getattr(C, 'icentr', 0) == 0 or id == C.ND:
            t0 = math.sqrt(t * tm)
            p0 = math.sqrt(p * pm)
            ab0 = math.sqrt(C.ABROSD[id] * C.ABROSD[id - 1])
            pr0 = math.sqrt(C.PRADT[id] * C.PRADT[id - 1]) * PCK
            dlp = UN / math.log(p / pm)
            dlt = math.log(t / tm) * dlp
            C.DELTA[id] = dlt
            ddt0 = dlp / t
            ddtm = -dlp / tm
            # CONVEC modifies scalar dummy arguments FLXCNV,VCONV → returns all scalar dummy arguments;
            # expression actual argument P0-pr0 received into a discard name; FLXCNV/VCON uninitialized in the original code, pass 0.0
            id, t0, p0, _pg, pr0, ab0, dlt, flxcnv, vcon = convec(
                id, t0, p0, p0 - pr0, pr0, ab0, dlt, 0.0, 0.0)
            C.FLXC[id] = flxcnv
            dhcdd = 0.0
            if C.DELMDE > 0.0:
                bb = C.BCNV * HALF
                cord = UN - bb / math.sqrt(bb * bb + (dlt - C.GRDADB))
                dhcdd = 1.5e0 / C.DELMDE * flxcnv * cord
            # icbegp is not declared in any COMMON (implicitly shared); read via getattr with default 0
            if id < getattr(C, 'icbegp', 0) - 2:
                C.FLXC[id] = 0.0
                continue                            # GO TO 10
            t1 = (UN + C.dert) * t0
            id, t1, p0, _pg, pr0, ab0, dlt, flxc1, vcon = convec(
                id, t1, p0, p0 - pr0, pr0, ab0, dlt, 0.0, 0.0)
            dhcdt0 = (flxc1 - flxcnv) * HALF / C.dert
            dhcdt = dhcdt0 / t + dhcdd * ddt0
            dhcdtm = dhcdt0 / tm + dhcdd * ddtm
        else:
            dlm = math.log(p / pm)
            dlp = math.log(C.PTOTAL[id + 1] / p)
            dl0 = dlm + dlp
            palf = dlp / dlm / dl0
            pgam = dlm / dlp / dl0
            dlt = (palf * math.log(t / tm)
                   + pgam * math.log(C.TEMP[id + 1] / t))
            C.DELTA[id] = dlt
            ddtm = -palf / tm
            ddtp = pgam / C.TEMP[id + 1]
            ddt0 = (palf - pgam) / t
            pr0 = math.sqrt(C.PRADT[id] * C.PRADT[id - 1]) * PCK
            id, t, p, _pg, pr0, _ab0, dlt, flxcnv, vcon = convec(
                id, t, p, p - pr0, pr0, C.ABROSD[id], dlt, 0.0, 0.0)
            C.FLXC[id] = flxcnv
            dhcdd = 0.0
            if C.DELMDE > 0.0:
                bb = C.BCNV * HALF
                cord = UN - bb / math.sqrt(bb * bb + (dlt - C.GRDADB))
                dhcdd = 1.5e0 / C.DELMDE * flxcnv * cord
            # icbegp is not declared in any COMMON (implicitly shared); read via getattr with default 0
            if id < getattr(C, 'icbegp', 0) - 2:
                C.FLXC[id] = 0.0
                continue                            # GO TO 10
            t1 = (UN + C.dert) * t
            id, t1, p, _pg, pr0, _ab0, dlt, flxc1, vcon = convec(
                id, t1, p, p - pr0, pr0, C.ABROSD[id], dlt, 0.0, 0.0)
            dhcdt0 = (flxc1 - flxcnv) * HALF / C.dert
            dhcdt = dhcdt0 / t + dhcdd * ddt0
            dhcdtm = dhcdd * ddtm
            dhcdtp = dhcdd * ddtp

        # additional terms in matrix WM

        # **  1. differential equation form
        if C.REDIF[id] > 0:
            C.WM[id, id - 1] = C.WM[id, id - 1] + dhcdtm * C.REDIF[id]
            C.WM[id, id] = C.WM[id, id] + dhcdt * C.REDIF[id]
            C.WR[id] = C.WR[id] - C.FLXC[id] * C.REDIF[id]
            if getattr(C, 'icentr', 0) != 0 and id < C.ND:
                C.WM[id, id + 1] = C.WM[id, id + 1] + dhcdtp * C.REDIF[id]

        # **  2. integral equation form
        if C.REINT[id] > 0.0:
            if id < C.ND:
                tp = C.TEMP[id + 1]
                ptp = C.PTOTAL[id + 1]
                t0 = math.sqrt(t * tp)
                p0 = math.sqrt(p * ptp)
                pr0 = math.sqrt(C.PRADT[id] * C.PRADT[id - 1]) * PCK
                ab0 = math.sqrt(C.ABROSD[id] * C.ABROSD[id + 1])
                dlp = UN / math.log(ptp / p)
                dlt = math.log(tp / t) * dlp
                ddtp0 = dlp / tp
                ddtpm = -dlp / t
                id, t0, p0, _pg, pr0, ab0, dlt, flxcnv, vcon = convec(
                    id, t0, p0, p0 - pr0, pr0, ab0, dlt, 0.0, 0.0)
                dhcddp = 0.0
                if C.DELMDE > 0.0:
                    dhcddp = 1.5e0 / C.DELMDE * flxcnv
                t1 = 1.001e0 * t0
                id, t1, p0, _pg, pr0, ab0, dlt, flxc1, vcon = convec(
                    id, t1, p0, p0 - pr0, pr0, ab0, dlt, 0.0, 0.0)
                dhcdt0 = (flxc1 - flxcnv) * 500.0
                dhcdtp = dhcdt0 / tp + dhcddp * ddtp0
                dhcdtu = dhcdt0 / t + dhcddp * ddtpm

                # additional terms in matrices A and B (the row corresponding to
                # energy balance, i.e. T) due to convection
                delm = (C.DM[id + 1] - C.DM[id - 1]) * HALF
                rdelm = C.DENS[id] / delm * C.REINT[id]
                if C.ICONV > 0:
                    C.WM[id, id - 1] = C.WM[id, id - 1] - rdelm * dhcdtm
                    C.WM[id, id] = C.WM[id, id] + rdelm * (dhcdtp - dhcdtu)
                    C.WM[id, id + 1] = C.WM[id, id + 1] + rdelm * dhcdtp
                C.WR[id] = C.WR[id] - rdelm * (flxcnv - C.FLXC[id])
            else:
                tp = C.TEMP[id - 2]
                ptp = C.PTOTAL[id - 2]
                t0 = math.sqrt(t * tp)
                p0 = math.sqrt(p * ptp)
                pr0 = math.sqrt(C.PRADT[id] * C.PRADT[id - 1]) * PCK
                ab0 = math.sqrt(C.ABROSD[id] * C.ABROSD[id - 2])
                dlp = UN / math.log(ptp / p)
                dlt = math.log(tp / t) * dlp
                ddtp0 = dlp / tp
                ddtpm = -dlp / t
                id, t0, p0, _pg, pr0, ab0, dlt, flxcnv, vcon = convec(
                    id, t0, p0, p0 - pr0, pr0, ab0, dlt, 0.0, 0.0)
                if flxcnv <= 0.0:
                    continue                        # GO TO 10
                dhcddp = 0.0
                if C.DELMDE > 0.0:
                    dhcddp = 1.5e0 / C.DELMDE * flxcnv
                t1 = 1.001e0 * t0
                id, t1, p0, _pg, pr0, ab0, dlt, flxc1, vcon = convec(
                    id, t1, p0, p0 - pr0, pr0, ab0, dlt, 0.0, 0.0)
                dhcdtp = ((flxc1 - flxcnv) * 1.0e3 / t0 * HALF
                          + dhcddp * ddtp0)

                # additional terms in matrices A and B (the row corresponding to
                # energy balance, i.e. T) due to convection
                delm = (C.DM[id] - C.DM[id - 2]) * HALF
                rdelm = C.DENS[id] / delm * C.REINT[id]
                delhc = C.WMM[id] / delm * (flxcnv - C.FLXC[id])  # computed but unused in the original code
                C.WM[id, id - 1] = C.WM[id, id - 1] + rdelm * (dhcdt - dhcdtp)
                C.WM[id, id] = C.WM[id, id] + rdelm * dhcdt
                C.WR[id] = C.WR[id] - rdelm * (C.FLXC[id] - flxcnv)
    # 10 CONTINUE
    return


def rybchn(changt):
    """
    handling relative changes in the Rybicki formalism

    Corresponds to tlusty208.f lines 47444-47604

    Method: relative-change diagnostics within the Rybicki scheme, in which
    the transfer equations of the selected (Rybicki-set) transitions are
    linearized together with the structural equations.
    References: Rybicki 1971, JQSRT 11, 589; Hubeny & Lanz 1995, ApJ 439,
    875.
    """
    # common/grdpra/GRD(MDEPTH),pra(mdepth),pgs0(mdepth),ANTP(MDEPTH)
    # common/rybpgs/CS(MDEPTH),PRAD2D(MDEPTH),F1HE
    # DIMENSION CHANGT(MDEPTH),TMPOLD(MDEPTH)
    tmpold = np.zeros(MDEPTH + 1)
    # scalar output dummy arguments of ELDENS (ANE/ENRG/ENTT/WM undefined before the call in the original code, take 0.0)
    ane = 0.0
    enrg = 0.0
    entt = 0.0
    wm = 0.0

    chmx = 0.0
    chn = 0.0
    jjr = 0
    dplp = C.DPSILT - UN
    dplm = UN / C.DPSILT - UN
    nre = C.NFREQE + 1
    if C.ITER == 1:
        # 800 FORMAT(' RELATIVE CHANGES OF VECTOR PSI'/
        #  '  ITER  ID    TEMP        NE       POP     RAD      MAXIMUM',
        #  '   ilev   ifr',/)
        write_line(9, ' RELATIVE CHANGES OF VECTOR PSI')
        write_line(9, '  ITER  ID    TEMP        NE       POP     RAD'
                      '      MAXIMUM   ilev   ifr')
        write_line(9, '')
    for id in range(C.ND, 0, -1):
        cht = changt[id] / C.TEMP[id]
        chan = cht
        if chan <= dplm:
            chan = dplm
        if chan > dplp:
            chan = dplp
        tmpold[id] = C.TEMP[id]
        C.TEMP[id] = C.TEMP[id] * (chan + UN)
        C.PSI0[nre] = C.TEMP[id]
        C.PSY0[nre, id] = C.PSI0[nre]
        # 801 FORMAT(2I5,1P5D10.2,2I5)
        # original actual-argument list ITER,ID,CHT,chn,chN,CHN,chT,jjr,jjr (case-insensitive)
        write_line(9, '%5d%5d%10.2e%10.2e%10.2e%10.2e%10.2e%5d%5d'
                   % (C.ITER, id, cht, chn, chn, chn, cht, jjr, jjr))
        if abs(cht) > chmx:
            chmx = abs(cht)

    if C.IOPTAB > -2:                               # otherwise GO TO 10
        if C.NRETC < 0:
            for id in range(-C.NRETC, 0, -1):
                C.TEMP[id] = C.TEMP[id + 1]
                C.PSY0[nre, id] = C.PSY0[nre, id + 1]

        if C.IDISK == 0:
            if C.IFPRAD > 0:
                for id in range(1, C.ND + 1):
                    t = C.TEMP[id]
                    dtod = C.TEMP[id] / tmpold[id] - UN
                    if dtod > 0.2:
                        dtod = 0.2
                    if dtod < -0.2:
                        dtod = -0.2
                    gfac = UN + 4.0 * dtod
                    if C.IDISK == 0:
                        if id == 1:
                            C.PGS[id] = C.DM[id] * (C.GRAV - C.GRD[id] * gfac)
                        else:
                            C.PGS[id] = (C.PGS[id - 1]
                                         + C.GRAV * (C.DM[id] - C.DM[id - 1])
                                         - PCK * C.GRD[id] * gfac)
                    # if(iprybc.gt.0)
                    # write(6,603) iter,id,grd(id),gfac,pgs(id),dtod,temp(id)
                    # 603  format(2i5,1p6e13.5)
                    an = C.PGS[id] / BOLK / t
                    # ELDENS modifies scalar dummy arguments → returns all scalar dummy arguments
                    id, t, an, ane, enrg, entt, wm, _ipri = eldens(
                        id, t, an, ane, enrg, entt, wm, 1)
                    rho = C.WMM[id] * (an - ane)
                    C.DENS[id] = rho
                    C.ELEC[id] = ane
            else:
                for id in range(1, C.ND + 1):
                    t = C.TEMP[id]
                    C.PGS[id] = C.DM[id] * C.GRAV
                    an = C.PGS[id] / BOLK / t
                    id, t, an, ane, enrg, entt, wm, _ipri = eldens(
                        id, t, an, ane, enrg, entt, wm, 1)
                    rho = C.WMM[id] * (an - ane)
                    C.DENS[id] = rho
                    C.ELEC[id] = ane
        else:
            pgpre = C.PGS[1]                        # computed but unused in the original code
            id = 1                                  # dead assignment, immediately reset by the DO on the next line
            for id in range(2, C.ND + 1):
                pgpre = C.PGS[id]                   # computed but unused in the original code
                dtod = C.TEMP[id] / tmpold[id] - UN
                if dtod > 0.2:
                    dtod = 0.2
                if dtod < -0.2:
                    dtod = -0.2
                gfac = UN + 4.0 * dtod
                grv = ((C.DM[id] - C.DM[id - 1]) * C.QGRAV
                       * (C.ZD[id] + C.ZD[id - 1]) * HALF)
                C.PGS[id] = C.PGS[id - 1] - PCK * C.GRD[id] * gfac + grv
                C.pgs0[id] = C.PGS[id]
            C.pgs0[1] = C.PGS[1]

            itpg = 0
            while True:                             # label 5 loop
                z1 = C.ZD[1]
                itpg = itpg + 1
                pgset(1)

                for id in range(1, C.ND + 1):
                    t = C.TEMP[id]
                    an = C.ANTP[id]
                    id, t, an, ane, enrg, entt, wm, _ipri = eldens(
                        id, t, an, ane, enrg, entt, wm, 1)
                    rho = C.WMM[id] * (an - ane)
                    C.DENS[id] = rho
                    C.ELEC[id] = ane
                    C.PGS[id] = BOLK * t * an
                    C.pgs0[id] = C.PGS[id]

                # recomputing the z-distance
                for id in range(C.ND - 1, 0, -1):
                    ddp = (C.DM[id + 1] - C.DM[id]) * HALF
                    C.ZD[id] = (C.ZD[id + 1] + ddp / C.DENS[id + 1]
                                + ddp / C.DENS[id])

                if abs((C.ZD[1] - z1) / z1) < 1.0e-3 or itpg > 5:
                    break                           # GO TO 8

                for id in range(1, C.ND + 1):
                    C.CS[id] = C.PGS[id] / C.DENS[id] / C.TEMP[id]

                hr1 = C.GRD[1] / C.QGRAV
                hg1 = math.sqrt(TWO * C.CS[1] * C.TEMP[1] / C.QGRAV)
                x = (C.ZD[1] - hr1) / hg1
                if x < 3.0:
                    if x < 0.0:
                        x = 0.0
                    C.F1HE = 8.86226925e-1 * math.exp(x * x) * erfcx(x)
                else:
                    C.F1HE = HALF * (UN - HALF / x / x) / x
                if abs((C.ZD[1] - z1) / z1) < 1.0e-4 or itpg > 5:
                    break                           # GO TO 8
                # GO TO 5 → continue while loop
            # label 8
    # label 10

    # STOP if changes become too large
    if C.ITER != 1 and not (abs(chmx) <= 1.0e16):  # FIX(fork): NaN-aware divergence guard recast in negated form
        # 610 FORMAT(' **** STOP in RYBSOL after ITER',I4,/,
        #  ' Max change:',1PE12.2)
        print(' **** STOP in RYBSOL after ITER%4d' % C.ITER)
        print(' Max change:%12.2e' % chmx)
        write_line(10, ' **** STOP in RYBSOL after ITER%4d' % C.ITER)
        write_line(10, ' Max change:%12.2e' % chmx)
        raise SystemExit                            # STOP

    # Python addition: record the maximum relative change of this iteration for the progress display in main()
    C.CHMX = chmx
    # Finally, set up quantity LFIN that indicates whether or not
    # this iteration of complete linearization is the last one
    C.LFIN = abs(chmx) <= C.CHMAX or C.ITER >= C.NITER
    return


def tridag(a, b, c, r, u, n):
    """
    solution of the tridiagonal system

    from Numerical recipes, Sect 2.4

    Corresponds to tlusty208.f lines 47610-47631
    """
    # DIMENSION A(N),B(N),C(N),R(N),U(N),GAM(N)
    gam = np.zeros(n + 1)
    bet = b[1]
    u[1] = r[1] / bet
    for j in range(2, n + 1):
        gam[j] = c[j - 1] / bet
        bet = b[j] - a[j] * gam[j]
        u[j] = (r[j] - a[j] * u[j - 1]) / bet
    for j in range(n - 1, 0, -1):
        u[j] = u[j] - gam[j + 1] * u[j + 1]
    return


def opactr(ij):
    """
    Absorption and emission coefficients and their derivatives
    for the use by Rybicki variant (RYBSOL)

    This procedure is very similar to OPACT1, the only difference is
    the evaluation of derivatives

    Input:
     IJ    - depth index
    Output:
     ABSO1 - array of absorption coefficient
     EMIS1 - array of emission coefficient
     SCAT1 - array of scattering coefficient
     Dxxy  - array of derivatives of xx (=AB for absorption, =EM for
             emission, =SC for scattering) coefficient wrt T

    Corresponds to tlusty208.f lines 47638-47817
    """
    DELT = 1.0e-2                               # PARAMETER (DELT=1.D-2)
    # common/dsctva/dsct1(mdepth),dscn1(mdepth)
    # common/hmolab/anh2(mdepth),anhm(mdepth)
    # common/grdpra/GRD(MDEPTH),pra(mdepth),pgs0(mdepth),ANTP(MDEPTH)
    absopp = np.zeros((MFREQ + 1, MDEPTH + 1))
    scatpp = np.zeros((MFREQ + 1, MDEPTH + 1))
    emispp = np.zeros((MFREQ + 1, MDEPTH + 1))
    aes = np.zeros((MLEVEL + 1, MLEVEL + 1))
    bes = np.zeros(MLEVEL + 1)
    elec0 = np.zeros(MDEPTH + 1)
    dens0 = np.zeros(MDEPTH + 1)
    an0 = np.zeros(MDEPTH + 1)
    bfabs = np.zeros((MLEVEL + 1, MDEPTH + 1))
    elerat = np.zeros(MDEPTH + 1)
    popul0 = np.zeros((MLEVEL + 1, MDEPTH + 1))
    poplte = np.zeros(MLEVEL + 1)
    # scalar output dummy arguments of ELDENS (undefined before the call in the original code, take 0.0)
    ane = 0.0
    enrg = 0.0
    entt = 0.0
    wm = 0.0
    # TODO(port): the original code uses local quantity T at lines 47801/47812,
    # but T is only assigned in the IJ==1 branch; for IJ>1 T is a Fortran undefined value (initialized to 0.0 here).
    t = 0.0

    # compute opacities at T+DELTA(T) - for derivatives
    if ij == 1:
        # first, save absolute b-factors (for evaluating
        # derivatives w.r.t. T)
        if not C.LTE:
            lte0 = C.LTE
            for id in range(1, C.ND + 1):
                wnstor(id)
                sabolf(id)
                ratmal(id, aes, bes)
                levsol(aes, bes, poplte, C.iifor, C.NLEVEL, 0)
                elerat[id] = C.ELEC[id] / (C.DENS[id] / C.WMM[id]
                                           + C.ELEC[id])
                for i in range(1, C.NLEVEL + 1):
                    popul0[i, id] = C.POPUL[i, id]
                    bfabs[i, id] = 1.0
                    if poplte[i] > 0.0:
                        bfabs[i, id] = C.POPUL[i, id] / poplte[i]
            C.LTE = lte0

        # opacities at T+DELTA(T) - for derivatives
        # for that, one needs also to estimate ELEC and DENS for T+DELTA(T)
        for id in range(1, C.ND + 1):
            C.TEMP[id] = C.TEMP[id] * (UN + DELT)
            elec0[id] = C.ELEC[id]
            dens0[id] = C.DENS[id]
            an0[id] = C.DENS[id] / C.WMM[id] + C.ELEC[id]
        tdpini()
        for id in range(1, C.ND + 1):
            t = C.TEMP[id]
            if C.IFPRAD > 0:
                if C.IDISK == 0:
                    if id == 1:
                        C.PGS[id] = (C.DM[id]
                                     * (C.GRAV - C.GRD[id] * (UN + 4.0 * DELT)))
                    else:
                        C.PGS[id] = (C.PGS[id - 1]
                                     + C.GRAV * (C.DM[id] - C.DM[id - 1])
                                     - PCK * C.GRD[id] * (UN + 4.0 * DELT))

        for id in range(1, C.ND + 1):
            t = C.TEMP[id]
            an = C.PGS[id] / BOLK / t
            if C.IDISK > 0:
                an = C.ANTP[id]
            # IF(LTE) THEN  (the ELSE branch is commented out in the original code; structure kept in literal translation)
            id, t, an, ane, enrg, entt, wm, _ipri = eldens(
                id, t, an, ane, enrg, entt, wm, 1)
            # ELSE
            #   ANE=AN*ELERAT(ID)
            # END IF
            rho = C.WMM[id] * (an - ane)
            C.DENS[id] = rho
            C.ELEC[id] = ane
            wnstor(id)
            if C.LTE or C.IFMOL > 0:
                steqeq(id, C.POP, 1)
            else:
                sabolf(id)
                ratmal(id, aes, bes)
                levsol(aes, bes, poplte, C.iifor, C.NLEVEL, 0)
                for i in range(1, C.NLEVEL + 1):
                    C.POPUL[i, id] = poplte[i] * bfabs[i, id]
        opaini(1)
        # IOPLYM is not declared in any COMMON (implicitly shared): read via getattr with default 0,
        # written via C.IOPLYM=...
        ioply0 = getattr(C, 'IOPLYM', 0)
        C.IOPLYM = 0
        for ijp in range(1, C.NFREQ + 1):
            opacf1(ijp)
            for id in range(1, C.ND + 1):
                absopp[ijp, id] = C.ABSO1[id] / C.DENS[id]
                emispp[ijp, id] = C.EMIS1[id] / C.DENS[id]
                scatpp[ijp, id] = C.SCAT1[id] / C.DENS[id]
        C.IOPLYM = ioply0

        # reset the original structural parameters
        for id in range(1, C.ND + 1):
            C.TEMP[id] = C.TEMP[id] / (UN + DELT)
        tdpini()

        if C.IDISK == 0:
            for id in range(1, C.ND + 1):
                C.ELEC[id] = elec0[id]
                C.DENS[id] = dens0[id]
                t = C.TEMP[id]
                an = dens0[id] / C.WMM[id] + elec0[id]
                C.PGS[id] = an * BOLK * t
        else:
            pgset(1)
            for id in range(1, C.ND + 1):
                t = C.TEMP[id]
                an = C.ANTP[id]
                id, t, an, ane, enrg, entt, wm, _ipri = eldens(
                    id, t, an, ane, enrg, entt, wm, 1)
                rho = C.WMM[id] * (an - ane)
                C.DENS[id] = rho
                C.ELEC[id] = ane
                C.PGS[id] = an * BOLK * t
        for id in range(1, C.ND + 1):
            wnstor(id)
            steqeq(id, C.POP, 1)
            # DO I=1,NLEVEL       (commented out here in the original code)
            #    POPUL(I,ID)=POPUL0(I,ID)
            # END DO
        opaini(1)

    # opacity at the original T, and derivatives
    opacf1(ij)
    for id in range(1, C.ND + 1):
        C.ABSO1[id] = C.ABSO1[id] / C.DENS[id]
        C.SCAT1[id] = C.SCAT1[id] / C.DENS[id]
        C.EMIS1[id] = C.EMIS1[id] / C.DENS[id]
        C.DABT1[id] = (absopp[ij, id] - C.ABSO1[id]) / t / DELT
        C.dsct1[id] = (scatpp[ij, id] - C.SCAT1[id]) / t / DELT
        C.XKF[id] = math.exp(-C.HKT1[id] * C.FREQ[ij])
        C.XKF1[id] = UN - C.XKF[id]
        C.XKFB[id] = C.XKF[id] * C.BNUE[ij]
        if C.LTE or C.IFMOL > 0:
            plan = C.XKFB[id] / C.XKF1[id]
            dplan = plan / C.XKF1[id] * C.HKT1[id] * C.FREQ[ij] / C.TEMP[id]
            C.DEMT1[id] = ((C.DABT1[id] - C.dsct1[id]) * plan
                           + (C.ABSO1[id] - C.SCAT1[id]) * dplan)
        else:
            C.DEMT1[id] = (emispp[ij, id] - C.EMIS1[id]) / t / DELT
    return


def rybheq():
    """
    (no header comment in the original code)

    Corresponds to tlusty208.f lines 47823-47964
    """
    # common/grdpra/GRD(MDEPTH),pra(mdepth),pgs0(mdepth),ANTP(MDEPTH)
    # common/rybpgs/CS(MDEPTH),PRAD2D(MDEPTH),F1HE
    pradfc = np.zeros(MDEPTH + 1)
    ane = 0.0                                     # ELDENS scalar output dummy argument
    enrg = 0.0
    entt = 0.0
    wm = 0.0

    for id in range(1, C.ND + 1):
        C.GRD[id] = 0.0
        C.pra[id] = 0.0
        C.PRADT[id] = 0.0
        pradfc[id] = 0.0
    prd0 = 0.0

    if C.IFPRAD > 0:
        opaini(1)
        for ij in range(1, C.NFREQ + 1):
            opacf1(ij)
            rtefr1(ij)
            if not C.LSKIP[1, ij]:
                C.GRD[1] = (C.GRD[1]
                            + C.W[ij] * C.ABSO1[1] * C.FH[ij] * C.RAD1[1])
            for id in range(2, C.ND + 1):
                if not C.LSKIP[id, ij]:
                    C.GRD[id] = (C.GRD[id] + (C.RAD1[id] * C.FAK1[id]
                                 - C.RAD1[id - 1] * C.FAK1[id - 1]) * C.W[ij])
                    C.pra[id] = C.pra[id] + C.RAD1[id] * C.FAK1[id] * C.W[ij]
            C.pra[1] = (C.pra[1] + C.RAD1[1] * C.FAK1[1] * C.W[ij]
                        - C.ABSO1[1] * C.W[ij]
                        * (C.RAD1[1] * C.FH[ij] - C.HEXTRD[ij]))
        if C.IDISK == 0:
            C.GRD[1] = PCK * C.GRD[1] / C.DENS[1]
        else:
            C.GRD[1] = PCK * C.GRD[2]
        prd0 = prd0 * C.DENS[1] * C.DM[1] * PCK   # PRD0 is always 0 in the original code

        for id in range(1, C.ND + 1):
            C.pra[id] = C.pra[id] * PCK
            C.PRADT[id] = C.pra[id]
            pradfc[id] = C.pra[id] / (2.5213e-15 * C.TEMP[id] ** 4)

        for id in range(2, C.ND):
            dmm = UN / (C.DM[id] - C.DM[id - 1])
            dmp = UN / (C.DM[id + 1] - C.DM[id])
            dm0 = TWO / (C.DM[id + 1] - C.DM[id - 1])
            qq = ((C.pra[id + 1] - C.pra[id]) * dmp
                  - (C.pra[id] - C.pra[id - 1]) * dmm) * dm0
            C.PRAD2D[id] = qq
        C.PRAD2D[1] = C.PRAD2D[2]
        C.PRAD2D[C.ND] = 0.0

    if C.IDISK == 0:
        C.pgs0[1] = C.DM[1] * (C.GRAV - C.GRD[1])
        for id in range(2, C.ND + 1):
            C.pgs0[id] = (C.pgs0[id - 1] - PCK * C.GRD[id]
                          + C.GRAV * (C.DM[id] - C.DM[id - 1]))
    else:
        C.pgs0[1] = C.PGS[1]
        for id in range(2, C.ND + 1):
            grv = ((C.DM[id] - C.DM[id - 1]) * C.QGRAV
                   * (C.ZD[id] + C.ZD[id - 1]) * HALF)
            C.pgs0[id] = C.pgs0[id - 1] - PCK * C.GRD[id] + grv
    if C.iprybh > 0:
        # 603 format(/' rybheq in iter',i4,
        #  '  dm,dens,pgs0,pra,pradfc,grd,grad,ggrav'/)
        print()
        print(' rybheq in iter%4d' % C.ITER,
              ' dm,dens,pgs0,pra,pradfc,grd,grad,ggrav')
        print()

    if C.iprybh > 0:
        for id in range(1, C.ND + 1):
            if id == 1:
                gra = C.GRD[id]
                ggr = C.QGRAV * C.ZD[id]
            else:
                gra = PCK * C.GRD[id] / (C.DM[id] - C.DM[id - 1])
                ggr = C.QGRAV * (C.ZD[id] + C.ZD[id - 1]) * HALF
            # 604 format(i4,1p9e13.4)
            if C.IDISK == 0:
                print('%4d' % id + ''.join('%13.4e' % v for v in (
                    C.DM[id], C.DENS[id], C.pgs0[id], C.pra[id],
                    pradfc[id], C.GRD[id], gra)))
            else:
                print('%4d' % id + ''.join('%13.4e' % v for v in (
                    C.DM[id], C.DENS[id], C.pgs0[id], C.pra[id],
                    pradfc[id], C.GRD[id], gra, ggr, C.ZD[id])))

    if C.IDISK == 0:
        for id in range(1, C.ND + 1):
            t = C.TEMP[id]
            C.PGS[id] = C.pgs0[id]
            an = C.PGS[id] / BOLK / t
            id, t, an, ane, enrg, entt, wm, _ipri = eldens(
                id, t, an, ane, enrg, entt, wm, 1)
            rho = C.WMM[id] * (an - ane)
            C.DENS[id] = rho
            C.ELEC[id] = ane
            wnstor(id)
            steqeq(id, C.POP, 1)
            # IF(.NOT.LCHC.and.iter.lt.ielcor) CALL ELCOR(ID)  (commented out in the original code)
    else:
        # --------------------------
        # the rest is only for disks
        # --------------------------
        cprad = 2.5213e-15                          # computed but unused in the original code
        for id in range(1, C.ND + 1):
            C.CS[id] = C.pgs0[id] / C.DENS[id] / C.TEMP[id]
            # pi(id)=cprad*pradfc(id)               (commented out in the original code)

        hr1 = C.GRD[1] / C.QGRAV
        hg1 = math.sqrt(TWO * C.CS[1] * C.TEMP[1] / C.QGRAV)
        x = (C.ZD[1] - hr1) / hg1
        if x < 3.0:
            if x < 0.0:
                x = 0.0
            C.F1HE = 8.86226925e-1 * math.exp(x * x) * erfcx(x)
        else:
            C.F1HE = HALF * (UN - HALF / x / x) / x

        ntemp = 2
        pgset(ntemp)

        for id in range(1, C.ND + 1):
            C.PGS[id] = C.pgs0[id]
            C.PTOTAL[id] = C.pgs0[id] + C.pra[id]
    return


def pgset(ntemp):
    """
    (no header comment in the original code)

    Corresponds to tlusty208.f lines 47970-48061
    """
    # common/grdpra/GRD(MDEPTH),pra(mdepth),pgs0(mdepth),ANTP(MDEPTH)
    # common/rybpgs/CS(MDEPTH),PRAD2D(MDEPTH),F1HE
    a = np.zeros(MDEPTH + 1)
    b = np.zeros(MDEPTH + 1)
    c = np.zeros(MDEPTH + 1)
    v = np.zeros(MDEPTH + 1)
    p = np.zeros(MDEPTH + 1)
    pnew = np.zeros(MDEPTH + 1)
    delp = np.zeros(MDEPTH + 1)
    temp0 = np.zeros(MDEPTH + 1)
    pg0 = np.zeros(MDEPTH + 1)

    for id in range(1, C.ND + 1):
        p[id] = C.pgs0[id]
        temp0[id] = C.TEMP[id]

    item = 0
    while True:                                     # label 10
        item = item + 1

        itp = 0
        while True:                                 # label 20
            itp = itp + 1

            id = 1
            b[id] = UN
            v[id] = (C.DM[1]
                     * math.sqrt(C.CS[id] * C.TEMP[id] * C.QGRAV * HALF)
                     / C.F1HE - p[id])
            for id in range(2, C.ND):
                dmm = UN / (C.DM[id] - C.DM[id - 1])
                dmp = UN / (C.DM[id + 1] - C.DM[id])
                dm0 = TWO / (C.DM[id + 1] - C.DM[id - 1])
                alp = dmm * dm0
                gam = dmp * dm0
                bet = alp + gam
                qq = C.PRAD2D[id]
                a[id] = p[id] * alp
                c[id] = p[id] * gam
                b[id] = (p[id - 1] * alp + p[id + 1] * gam
                         - TWO * p[id] * bet + qq)
                v[id] = (-p[id - 1] * p[id] * alp - p[id + 1] * p[id] * gam
                         + p[id] ** 2 * bet - p[id] * qq
                         - C.CS[id] * C.TEMP[id] * C.QGRAV)

            id = C.ND
            alp = TWO / (C.DM[id] - C.DM[id - 1]) ** 2
            a[id] = alp * p[id]
            b[id] = alp * (p[id - 1] - TWO * p[id])
            v[id] = (alp * p[id] * (p[id] - p[id - 1])
                     - C.CS[id] * C.TEMP[id] * C.QGRAV)

            tridag(a, b, c, v, delp, C.ND)

            pdmax = 0.0
            for id in range(1, C.ND + 1):
                pnew[id] = p[id] + delp[id]
                pd = (pnew[id] - p[id]) / p[id]
                pnew[id] = max(pnew[id], 0.5 * p[id])
                pdmax = max(pdmax, abs(pd))
                # if(ippgst.ge.2) write(6,602) iter,item,itp,id,p(id),pnew(id),pd
                # 602  format('pgset',4i4,1p3e12.4)
                p[id] = pnew[id]
            # if(ippgst.ge.1) write(6,606) iter,item,itp,pdmax
            # 606 format('pgset iter,itp,pdmax:',3i4,1pe10.2)

            if not (itp < 30 and pdmax > 1.0e-4):
                break                               # otherwise GO TO 20

        if item < ntemp:
            for id in range(1, C.ND + 1):
                temp0[id] = C.TEMP[id]
                pg0[id] = p[id]
                C.TEMP[id] = C.TEMP[id] * 1.01
            continue                                # GO TO 10
        break

    for id in range(1, C.ND + 1):
        C.ANTP[id] = p[id] / BOLK / C.TEMP[id]
        ant0 = pg0[id] / BOLK / temp0[id]           # computed but unused in the original code
        C.TEMP[id] = temp0[id]
        # if(ippgst.ge.2)
        #    write(6,605) iter,id,pg0(id),p(id),p(id)/pg0(id)
        # 605 format('new P',2i4,1p2e12.4,0p2f10.4)
    if ntemp == 1:
        for id in range(1, C.ND + 1):
            C.pgs0[id] = p[id]
    return


def locate(xx, n, x, j, nxdim):
    """
    (no header comment in the original code; Numerical Recipes bisection locate routine)

    Corresponds to tlusty208.f lines 48069-48094

    Modifies scalar dummy argument J → per convention returns all scalar dummy arguments (n, x, j, nxdim).
    """
    jl = 0
    ju = n + 1
    while ju - jl > 1:                              # label 10 loop
        jm = idiv(ju + jl, 2)                       # Fortran integer division
        if (xx[n] >= xx[1]) == (x >= xx[jm]):       # .EQV.
            jl = jm
        else:
            ju = jm
    if x == xx[1]:
        j = 1
    elif x == xx[n]:
        j = n - 1
    else:
        j = jl
    return n, x, j, nxdim


def xenini():
    """
    Initializes necessary arrays for evaluating hydrogen line profiles
    from the XENOMORPH tables

    Corresponds to tlusty208.f lines 48102-48205
    """
    for i in range(1, 5):
        for j in range(1, 23):
            C.ILXEN[i, j] = 0
    if C.IHXENB > 0:
        C.IHXENB = 23
        ihxenr = C.IHXENB + 1                       # local variable (used only in this routine)
        open_unit(C.IHXENB, 'xenomorph.blue.dat', 'r')   # OPEN status='old'
        open_unit(ihxenr, 'xenomorph.red.dat', 'r')      # OPEN status='old'
        # 641 format(' -----------'/
        #  ' reading XENOMORPH tables; ihxen =',2i3,/
        #  ' -----------')
        print(' -----------')
        print(' reading XENOMORPH tables; ihxen =%3d%3d' % (C.IHXENB, ihxenr))
        print(' -----------')
    else:
        return

    # ---------------------------------
    # read  tables - blue wing
    # ---------------------------------
    iline = 0
    # READ(IHXENB,*) NTAB -- list-directed, read by token (may span lines)
    vals = []
    while len(vals) < 1:
        vals.extend(read_line(C.IHXENB).replace(',', ' ').split())
    ntab = int(float(vals[0]))
    for itab in range(1, ntab + 1):
        ilineb = iline
        vals = []
        while len(vals) < 1:
            vals.extend(read_line(C.IHXENB).replace(',', ' ').split())
        nlxen = int(float(vals[0]))
        for ili in range(1, nlxen + 1):
            iline = iline + 1
            # READ(IHXENB,*) I,J,ALMIN,ANEMIN,TMIN,DLA,DLE,DLT,NWL,NE,NT
            vals = []
            while len(vals) < 11:
                vals.extend(read_line(C.IHXENB).replace(',', ' ').split())
            i = int(float(vals[0]))
            j = int(float(vals[1]))
            almin = float(vals[2])
            anemin = float(vals[3])
            tmin = float(vals[4])
            dla = float(vals[5])
            dle = float(vals[6])
            dlt = float(vals[7])
            nwl = int(float(vals[8]))
            ne = int(float(vals[9]))
            nt = int(float(vals[10]))
            C.XNEMIN = anemin
            C.ILXEN[i, j] = iline
            C.NWLXEN[iline] = nwl
            C.NTHXEN[iline] = nt
            C.NEHXEN[iline] = ne
            for iwl in range(1, nwl + 1):
                C.ALXEN[iline, iwl] = almin + (iwl - 1) * dla
            for ine in range(1, ne + 1):
                C.XNEXEN[ine, iline] = anemin + (ine - 1) * dle
            for it in range(1, nt + 1):
                C.XTXEN[it, iline] = tmin + (it - 1) * dlt

        for ili in range(1, nlxen + 1):
            ilne = ilineb + ili
            nwl = C.NWLXEN[ilne]
            read_line(C.IHXENB)                     # READ(IHXENB,500);500 FORMAT(1X)
            for ine in range(1, C.NEHXEN[ilne] + 1):
                for it in range(1, C.NTHXEN[ilne] + 1):
                    # READ(IHXENB,*) QLT,(PRFXB(ILNE,IWL,IT,INE),IWL=1,NWL)
                    vals = []
                    while len(vals) < nwl + 1:
                        vals.extend(read_line(C.IHXENB).replace(',', ' ').split())
                    qlt = float(vals[0])            # read but unused in the original code
                    for iwl in range(1, nwl + 1):
                        C.PRFXB[ilne, iwl, it, ine] = float(vals[iwl])
    close_unit(C.IHXENB)

    # ---------------------------------
    # read  tables - red wing
    # ---------------------------------
    iline = 0
    vals = []
    while len(vals) < 1:
        vals.extend(read_line(ihxenr).replace(',', ' ').split())
    ntab = int(float(vals[0]))
    for itab in range(1, ntab + 1):
        ilineb = iline
        vals = []
        while len(vals) < 1:
            vals.extend(read_line(ihxenr).replace(',', ' ').split())
        nlxen = int(float(vals[0]))
        for ili in range(1, nlxen + 1):
            iline = iline + 1
            # READ(IHXENR,*) I,J,ALMIN,ANEMIN,TMIN,DLA,DLE,DLT,NWL,NE,NT
            # (header values of the red-wing table read but unused in the original code)
            vals = []
            while len(vals) < 11:
                vals.extend(read_line(ihxenr).replace(',', ' ').split())

        for ili in range(1, nlxen + 1):
            ilne = ilineb + ili
            nwl = C.NWLXEN[ilne]
            read_line(ihxenr)                       # READ(IHXENR,500)
            for ine in range(1, C.NEHXEN[ilne] + 1):
                for it in range(1, C.NTHXEN[ilne] + 1):
                    # READ(IHXENR,*) QLT,(PRFXR(ILNE,IWL,IT,INE),IWL=1,NWL)
                    vals = []
                    while len(vals) < nwl + 1:
                        vals.extend(read_line(ihxenr).replace(',', ' ').split())
                    qlt = float(vals[0])            # read but unused in the original code
                    for iwl in range(1, nwl + 1):
                        C.PRFXR[ilne, iwl, it, ine] = float(vals[iwl])
    close_unit(ihxenr)
    return


def intxen(w0b, w0r, x0, z0, iwl, iline, id):
    """
    Interpolation in temperature and electron density from the
    Xenomorph tables for hydrogen lines to the actual valus of
    temperature and electron density

    Corresponds to tlusty208.f lines 48211-48261

    Modifies scalar dummy arguments W0B,W0R → per convention returns all scalar dummy arguments
    (w0b, w0r, x0, z0, iwl, iline, id).
    """
    zz = np.zeros(4)                                # ZZ(3)
    xx = np.zeros(4)                                # XX(3)
    wxb = np.zeros(4)                               # WXB(3)
    wzb = np.zeros(4)                               # WZB(3)
    wxr = np.zeros(4)                               # WXR(3)
    wzr = np.zeros(4)                               # WZR(3)

    id1 = id                                        # computed but unused in the original code
    nx = 2
    nz = 2
    nt = C.NTHXEN[iline]
    ne = C.NEHXEN[iline]

    ipz = 0
    # TODO(port): if the loop below does not trigger GO TO 20, IPZ keeps its loop-end value
    # NE-1 in Fortran; the explicit assignment here is equivalent. If NE<2 the loop does not
    # execute and IPZ is undefined in Fortran (0 here).
    for izz in range(1, ne):                        # DO IZZ=1,NE-1
        ipz = izz
        if z0 <= C.XNEXEN[izz + 1, iline]:
            break                                   # GO TO 20
    # label 20
    n0z = ipz - idiv(nz, 2) + 1                     # Fortran integer division NZ/2
    if n0z < 1:
        n0z = 1
    if n0z > ne - nz + 1:
        n0z = ne - nz + 1
    n1z = n0z + nz - 1

    for izz in range(n0z, n1z + 1):
        i0z = izz - n0z + 1
        zz[i0z] = C.XNEXEN[izz, iline]
        ipx = 0
        for ix in range(1, nt):                     # DO IX=1,NT-1
            ipx = ix
            if x0 <= C.XTXEN[ix + 1, iline]:
                break                               # GO TO 40
        # label 40
        n0x = ipx - idiv(nx, 2) + 1
        if n0x < 1:
            n0x = 1
        if n0x > nt - nx + 1:
            n0x = nt - nx + 1
        n1x = n0x + nx - 1
        for ix in range(n0x, n1x + 1):
            i0 = ix - n0x + 1
            xx[i0] = C.XTXEN[ix, iline]
            wxb[i0] = C.PRFXB[iline, iwl, ix, izz]
            wxr[i0] = C.PRFXR[iline, iwl, ix, izz]
        wzb[i0z] = yint(xx, wxb, x0)
        wzr[i0z] = yint(xx, wxr, x0)
    w0b = yint(zz, wzb, z0)
    w0r = yint(zz, wzr, z0)
    return w0b, w0r, x0, z0, iwl, iline, id


def gomini():
    """
    Initialization and reading of the opacity table for thermal processe
    and Rayleigh scattering
    raytab: scattering opacities in cm^2/gm at 5.0872638d14 Hz (sodium D)
    (NOTE: Quantities in rayleigh.tab are in log_e)

    tempvec: array of temperatures
    nu:     array of frequencies
    table:  absorptive opacities in cm^2/gm
    (NOTE:  Quantities in absorption.tab are in log_e)

    Corresponds to tlusty208.f lines 48268-48371
    """
    # common/intcfg/yint(mfreq),jgint(mfreq)
    absort = np.zeros(mfhtab + 1)
    frlt = np.zeros(mfhtab + 1)

    if C.ihgom == 0:
        return

    open_unit(53, 'gomhyd.dat', 'r')                # OPEN status='old'

    # READ(53,*) nugfreq,nugtemp,nugele -- list-directed, read by token
    vals = []
    while len(vals) < 3:
        vals.extend(read_line(53).replace(',', ' ').split())
    C.nugfreq = int(float(vals[0]))
    C.nugtemp = int(float(vals[1]))
    C.nugele = int(float(vals[2]))
    read_line(53)                                   # READ(53,*) empty list: skip one line
    # READ(53,*) (temvec(i),i=1,nugtemp)
    vals = []
    while len(vals) < C.nugtemp:
        vals.extend(read_line(53).replace(',', ' ').split())
    for i in range(1, C.nugtemp + 1):
        C.temvec[i] = float(vals[i - 1])
    read_line(53)                                   # READ(53,*)
    # READ(53,*) (elevec(j),j=1,nugele)
    vals = []
    while len(vals) < C.nugele:
        vals.extend(read_line(53).replace(',', ' ').split())
    for j in range(1, C.nugele + 1):
        C.elevec[j] = float(vals[j - 1])
    for it in range(1, C.nugtemp + 1):
        C.temvec[it] = math.log(C.temvec[it] * 1.161e4)
    # write(6,600) ihgom,nugfreq,nugtemp,nugele  (commented out in the original code)
    # 600 format(' ihgom,nugfr,nugt,nuge ',4i4)

    C.EGTAB1 = C.elevec[1]
    C.EGTAB2 = C.elevec[C.nugele]
    C.TGTAB1 = C.temvec[1]
    C.TGTAB2 = C.temvec[C.nugtemp]

    for k in range(1, C.nugfreq + 1):
        # READ(53,501) eneev ;501 format(40x,f17.14)
        line = read_line(53)
        eneev = float(line[40:57])
        C.frgtab[k] = 3.28805e15 / 13.595 * eneev
        frlt[k] = math.log10(C.frgtab[k])           # computed but unused in the original code
        for i in range(1, C.nugtemp + 1):
            # READ(53,*) (hydcrs(i,j,k),j=1,nugele)
            vals = []
            while len(vals) < C.nugele:
                vals.extend(read_line(53).replace(',', ' ').split())
            for j in range(1, C.nugele + 1):
                C.hydcrs[i, j, k] = float(vals[j - 1])
    close_unit(53)

    C.FRGTB1 = math.log10(C.frgtab[1])
    C.FRGTB2 = math.log10(C.frgtab[C.nugfreq])

    # interpolate HYDCRS from tabular to actual frequencies

    # set up interpolation coefficients for frequency interpolation
    # by bisection
    frg1 = C.frgtab[1]
    frg2 = C.frgtab[C.nugfreq]
    for ij in range(1, C.NFREQ + 1):
        C.jgint[ij] = 0
        xint = C.FREQ[ij]
        if frg1 <= xint <= frg2:
            jl = 0
            ju = C.nugfreq + 1
            while ju - jl > 1:                      # label 40 loop
                jm = idiv(ju + jl, 2)               # Fortran integer division
                if (frg2 > frg1) == (xint > C.frgtab[jm]):   # .EQV.
                    jl = jm
                else:
                    ju = jm
            j = jl
            if j == C.nugfreq:
                j = j - 1
            if j == 0:
                j = j + 1
            C.jgint[ij] = j
            # canonical name of /intcfg/ yint is INTCFG_YINT (see INLINE_COMMONS.md)
            C.INTCFG_YINT[ij] = UN / math.log10(C.frgtab[j + 1] / C.frgtab[j])

    for it in range(1, C.nugtemp + 1):
        for ir in range(1, C.nugele + 1):
            for k in range(1, C.nugfreq + 1):
                absort[k] = math.log(C.hydcrs[it, ir, k])
            for ij in range(1, C.NFREQ + 1):
                j = C.jgint[ij]
                C.hydcrs[it, ir, ij] = 0.0
                if j > 0:
                    rc = (absort[j + 1] - absort[j]) * C.INTCFG_YINT[ij]
                    hcs = rc * math.log10(C.FREQ[ij] / C.frgtab[j]) + absort[j]
                    C.hydcrs[it, ir, ij] = hcs
    return


def ghydop(ij):
    """
    hydrogen opacity -lines + pseudocontinuum from Gomez tables

    Corresponds to tlusty208.f lines 48377-48432
    """
    # common/intcfg/yint(mfreq),jgint(mfreq)
    if C.ihgom == 0 or C.jgint[ij] == 0:
        return
    jf = ij
    for id in range(1, C.ND + 1):                   # DO 10 ID=1,ND
        if C.ELEC[id] < C.hglim:
            continue                                # GO TO 10
        rl = math.log(C.ELEC[id])
        tl = math.log(C.TEMP[id])

        deltar = ((rl - C.EGTAB1) / (C.EGTAB2 - C.EGTAB1)
                  * float(C.nugele - 1))
        jr = 1 + int(dint(deltar))                  # IDINT → truncate toward zero
        if jr < 1:
            jr = 1
        if jr > C.nugele - 1:
            jr = C.nugele - 1
        r1i = C.elevec[jr]
        r2i = C.elevec[jr + 1]
        dri = (rl - r1i) / (r2i - r1i)
        if jr == 1:
            dri = 0.0

        deltat = ((tl - C.TGTAB1) / (C.TGTAB2 - C.TGTAB1)
                  * float(C.nugtemp - 1))
        jt = 1 + int(dint(deltat))                  # IDINT
        if jt < 1:
            jt = 1
        if jt > C.nugtemp - 1:
            jt = C.nugtemp - 1
        t1i = C.temvec[jt]
        t2i = C.temvec[jt + 1]
        dti = (tl - t1i) / (t2i - t1i)
        if jt == 1:
            dti = 0.0

        opr1 = (C.hydcrs[jt, jr, jf] + dti
                * (C.hydcrs[jt + 1, jr, jf] - C.hydcrs[jt, jr, jf]))
        opr2 = (C.hydcrs[jt, jr + 1, jf] + dti
                * (C.hydcrs[jt + 1, jr + 1, jf] - C.hydcrs[jt, jr + 1, jf]))
        opac = opr1 + dri * (opr2 - opr1)
        ab = math.exp(opac) * 0.0265 * 4.1347e-15

        if C.FREQ[ij] > 8.22013e14:
            ii = C.NFIRST[C.IELH]
        else:
            ii = C.NFIRST[C.IELH] + 1

        oph = ab * C.POPUL[ii, id] * C.G[ii]
        C.ABSO1[id] = C.ABSO1[id] + oph
        C.EMIS1[id] = C.EMIS1[id] + oph * C.XKFB[id] / C.XKF1[id]
    # 10 CONTINUE
    return


